","vi.md":"e99d92f0fa88a2e393e786ca844828504670751032088aaa3591f6432f0f03ce","workspace/source.test.ts":"50cbc285ef3c9556c63de548199683c07e883085fca04b6b4494510bd48307e3","workspace/source.ts":"e6fa5a8b079490f9aaa0f21dee280cd6e70c222121d64c2297025fde6b713384"}$lesson$::jsonb,
    $lesson${"locales":{"vi":{"title":"Request lifecycle — đặt logic đúng tầng","description":"Request lifecycle là thứ tự các tầng tiếp nhận, kiểm soát, xử lý và trả kết quả của một request, gồm cả đường thành công và đường lỗi.","body":"## Tóm tắt\n\nBạn đã dùng thứ tự và context để giải thích lỗi, thay vì chọn tầng theo thói quen. Khi debug request tiếp theo, hãy hỏi: tầng nào đã chạy, tầng nào chưa từng được vào, dữ liệu đó được tạo trước hay sau điểm đang đọc?\n\n## Kết quả học tập\n\n- Dự đoán trace của request hợp lệ, bị guard chặn và bị pipe chặn.\n- Đặt validation, authorization và response wrapping đúng tầng; kiểm tra bằng trace.\n- Giải thích giới hạn của wrapper và interceptor trên đường lỗi.\n\n## Kiến thức đầu vào\n\n- Đọc được hàm TypeScript, Promise và lỗi throw.\n- Phân biệt HTTP request, status và handler.\n\n## Phạm vi bao gồm\n\n- Thứ tự middleware, guard, interceptor, pipe, handler.\n- LIFO ở chiều về và đường lỗi.\n- Chọn tầng bằng thời điểm và context; đối chiếu bằng trace.\n\n## Phạm vi không bao gồm\n\n- Triển khai JWT hoàn chỉnh.\n- Request scope và dependency injection chuyên sâu.\n- Các transport WebSocket và queue.\n\n## Luận điểm chính\n\n- Guard chạy trước pipe trong lifecycle HTTP NestJS.\n- Nhiều interceptor đi vào theo thứ tự đăng ký và xử lý chiều về theo thứ tự ngược.\n- Filter xử lý exception chưa được xử lý, không phải bước bắt buộc trên đường success.\n\n## Điều chỉnh nhận thức\n\n- Nguồn vẽ exception filter ở cuối chuỗi dễ gây hiểu nhầm: filter không chạy trên mọi response.\n- Không suy guard đứng trước pipe là body chưa được parse; body parser/middleware có thể đã chạy.\n- Không tin role do client tự khai. role trong mô hình chỉ là fixture; ứng dụng thật cần principal đã xác thực.\n- Mô hình chạy local chứng minh logic minh họa, không chứng minh integration NestJS.\n\n## Tham khảo\n\n- [docs.nestjs.com/faq/request-lifecycle](https://docs.nestjs.com/faq/request-lifecycle)\n- [docs.nestjs.com/interceptors](https://docs.nestjs.com/interceptors)\n- [docs.nestjs.com/middleware](https://docs.nestjs.com/middleware)","learningOutcomes":[{"id":"request-response-lifecycle--r1--mechanism","text":"Dự đoán trace của request hợp lệ, bị guard chặn và bị pipe chặn."},{"id":"request-response-lifecycle--r1--application","text":"Đặt validation, authorization và response wrapping đúng tầng; kiểm tra bằng trace."},{"id":"request-response-lifecycle--r1--tradeoffs","text":"Giải thích giới hạn của wrapper và interceptor trên đường lỗi."}],"prerequisites":[{"id":"request-response-lifecycle--r1--input-0","text":"Đọc được hàm TypeScript, Promise và lỗi throw."},{"id":"request-response-lifecycle--r1--input-1","text":"Phân biệt HTTP request, status và handler."}],"references":[{"id":"request-response-lifecycle--r1--legacy","label":"Nguồn dữ liệu trước migration","citation":"legacy; courses/0-fullstack-mastery/modules/0-nestjs-core-and-request-lifecycle/contents/1-request-response-lifecycle/bodies/0-typescript/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 9b583cebc7917d725564f9de7afb33741bc20fa2b70c16ab3038461c9f8d3884; checked 2026-09-05; Bài mẫu V2 mới; không sửa V1."},{"id":"request-response-lifecycle--r1--official-0","label":"docs.nestjs.com/faq/request-lifecycle","url":"https://docs.nestjs.com/faq/request-lifecycle","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."},{"id":"request-response-lifecycle--r1--official-1","label":"docs.nestjs.com/interceptors","url":"https://docs.nestjs.com/interceptors","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."},{"id":"request-response-lifecycle--r1--official-2","label":"docs.nestjs.com/middleware","url":"https://docs.nestjs.com/middleware","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."}],"retrieval":[{"id":"request-response-lifecycle--r1--retrieval-1","kind":"retrieval","prompt":"Sau một ngày: log service không xuất hiện nhưng interceptor.before có. Hãy nêu một nguyên nhân và một phép kiểm phân biệt với guard failure.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism"],"afterDays":1,"rubric":[{"id":"request-response-lifecycle--r1--retrieval-1--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Pipe có thể từ chối input. Kiểm trace pipe và status; guard failure trước interceptor không tạo interceptor.before trong cấu hình này.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Pipe có thể từ chối input. Kiểm trace pipe và status; guard failure trước interceptor không tạo interceptor.before trong cấu hình này.","sampleAnswer":"Pipe có thể từ chối input. Kiểm trace pipe và status; guard failure trước interceptor không tạo interceptor.before trong cấu hình này.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"request-response-lifecycle--r1--retrieval-2","kind":"retrieval","prompt":"Sau một tuần: thêm một interceptor nén response làm timing thay đổi. Giải thích thứ tự, điều chỉnh để đo cả nén và nói giới hạn phép đo.","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--application"],"afterDays":7,"rubric":[{"id":"request-response-lifecycle--r1--retrieval-2--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Đặt timing bao ngoài phần nén để đo thời gian stream xử lý bên trong; kiểm trace LIFO. Thời gian observable vẫn không tự là thời gian người dùng tải hết response.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Đặt timing bao ngoài phần nén để đo thời gian stream xử lý bên trong; kiểm trace LIFO. Thời gian observable vẫn không tự là thời gian người dùng tải hết response.","sampleAnswer":"Đặt timing bao ngoài phần nén để đo thời gian stream xử lý bên trong; kiểm trace LIFO. Thời gian observable vẫn không tự là thời gian người dùng tải hết response.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"request-response-lifecycle--r1--retrieval-3","kind":"retrieval","prompt":"Sau 21 ngày: endpoint queue gọi cùng service HTTP. Vì sao validation HTTP không đủ? Đề xuất boundary mới mà không nhân đôi nghiệp vụ.","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"request-response-lifecycle--r1--retrieval-3--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Queue có đầu vào khác và không tự đi qua pipeline HTTP. Validate message tại consumer boundary; giữ invariant nghiệp vụ trong service dùng chung. Cần test consumer với message sai chứ không dùng HTTP test thay bằng chứng.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Queue có đầu vào khác và không tự đi qua pipeline HTTP. Validate message tại consumer boundary; giữ invariant nghiệp vụ trong service dùng chung. Cần test consumer với message sai chứ không dùng HTTP test thay bằng chứng.","sampleAnswer":"Queue có đầu vào khác và không tự đi qua pipeline HTTP. Validate message tại consumer boundary; giữ invariant nghiệp vụ trong service dùng chung. Cần test consumer với message sai chứ không dùng HTTP test thay bằng chứng.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}}],"sections":[{"title":"Bối cảnh phỏng vấn","phase":"challenge","sortIndex":0,"body":"Trong buổi phỏng vấn Backend, interviewer đưa hai request vào cùng API quản trị: một request sai quyền, một request có id = -1. “Vì sao cả hai đều không tới service nhưng log đo thời gian chỉ xuất hiện ở một request?” Bạn trả lời: “Vì validation chặn sớm.” Interviewer hỏi tiếp: “Vậy validation chạy trước hay sau kiểm quyền?”\n\nTrả lời câu hỏi bằng suy nghĩ hiện tại. Đây là lần chẩn đoán đầu vào, chưa tính đạt đầu ra. Bạn sẽ trả lời lại sau khi thực hành; bài vẫn mở nếu bạn chưa biết đáp án.","activities":[{"id":"request-response-lifecycle--r1--opening-interview","kind":"explain","prompt":"Hãy giải thích hai request trên, nêu thứ tự các tầng và nơi bạn đặt log để phân biệt lỗi quyền với lỗi input.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism","request-response-lifecycle--r1--application","request-response-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"request-response-lifecycle--r1--opening-interview--criterion-0","criterion":"Thứ tự và dữ liệu","expectedEvidence":"Nêu guard chạy trước pipe; guard không dùng kết quả transform của pipe.","misconception":"Pipe luôn chuẩn hóa trước guard.","maxScore":2},{"id":"request-response-lifecycle--r1--opening-interview--criterion-1","criterion":"Nhánh lỗi","expectedEvidence":"Phân biệt lỗi guard, lỗi pipe và lỗi service; chỉ interceptor đã vào mới có thể xử lý lỗi bên trong.","misconception":"Exception filter chạy sau mọi response thành công.","maxScore":2},{"id":"request-response-lifecycle--r1--opening-interview--criterion-2","criterion":"Bằng chứng","expectedEvidence":"Đề xuất trace theo request ID và chứng minh service không được gọi khi bị chặn.","misconception":"Chỉ nhìn HTTP status đã đủ chứng minh tầng lỗi.","maxScore":2}],"answer":{"explanation":"Middleware chạy trước guard. Guard chặn request sai quyền nên interceptor phía sau chưa được vào. Với quyền hợp lệ nhưng id sai, interceptor đã bao phần xử lý bên trong; pipe ném lỗi trước controller/service. Interceptor có thể quan sát error qua nhánh RxJS thích hợp; map chỉ chạy trên giá trị thành công. Filter nhận lỗi còn chưa được xử lý. Tôi ghi request ID từ middleware và trace từng tầng, không suy nguyên nhân chỉ từ status.","sampleAnswer":"Middleware chạy trước guard. Guard chặn request sai quyền nên interceptor phía sau chưa được vào. Với quyền hợp lệ nhưng id sai, interceptor đã bao phần xử lý bên trong; pipe ném lỗi trước controller/service. Interceptor có thể quan sát error qua nhánh RxJS thích hợp; map chỉ chạy trên giá trị thành công. Filter nhận lỗi còn chưa được xử lý. Tôi ghi request ID từ middleware và trace từng tầng, không suy nguyên nhân chỉ từ status.","misconception":"Pipe luôn chuẩn hóa trước guard.; Exception filter chạy sau mọi response thành công.; Chỉ nhìn HTTP status đã đủ chứng minh tầng lỗi."}}],"id":"0-interview"},{"title":"Dự đoán trước khi quan sát","phase":"predict","sortIndex":1,"body":"Fixture: role = guest, id = -1; guard đứng trước hai interceptor rồi tới pipe. Filter đã được cấu hình để chuẩn hóa lỗi. Chỉ chọn một đáp án.","activities":[{"id":"request-response-lifecycle--r1--predict-order","kind":"choice","prompt":"Trace nào phù hợp với request này?","stableKey":"predict-order","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Một request có thể mang nhiều lỗi, nhưng lỗi ở tầng chạy trước quyết định đường xử lý trong fixture này.","misconception":"middleware → pipe → guard → filter; middleware → guard → interceptor → pipe → filter"},"options":[{"id":"request-response-lifecycle--r1--predict-order--option-1","label":"middleware → guard → filter","explanation":"Đúng: guard từ chối trước khi interceptor và pipe được chạy.","isCorrect":true},{"id":"request-response-lifecycle--r1--predict-order--option-2","label":"middleware → pipe → guard → filter","explanation":"Sai: bạn đang giả định pipe xử lý trước guard.","isCorrect":false},{"id":"request-response-lifecycle--r1--predict-order--option-3","label":"middleware → guard → interceptor → pipe → filter","explanation":"Sai: guard đã từ chối nên không có bước tiếp theo trong pipeline nghiệp vụ.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Thử và quan sát","phase":"explore","sortIndex":2,"body":"Trong mô phỏng, thử request sai quyền trước, sau đó sửa quyền nhưng giữ id sai. Đừng sửa cả hai điều kiện cùng lúc: bạn cần thấy việc một tầng được chạy hoặc bị bỏ qua thay đổi ra sao. Cuối cùng sửa id và so sánh thứ tự inner/outer ở chiều về.\n\n**Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.**\n\n```mermaid\nflowchart TD\n M[Middleware] --> G{Guard}\n G -->|allow| I[Interceptor before]\n G -->|deny| F[Exception filter]\n I --> P{Pipe}\n P -->|valid| H[Controller and service]\n P -->|throw| E[Interceptor error path]\n H --> O[Interceptor after LIFO]\n E -->|unhandled| F\n O --> R[Success response]\n F --> X[Error response]\n```\n\n> Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.","activities":[{"id":"request-response-lifecycle--r1--exploration","kind":"simulation","prompt":"Thử đường sai trước, đọc trạng thái quan sát được, sau đó tìm đường giải quyết. Kết thúc bằng câu giải thích nguyên nhân.","stableKey":"exploration","outcomeIds":["request-response-lifecycle--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"request-response-lifecycle--r1--exploration--state-guest","debriefQuestion":"Vì sao inner.after nằm trước outer.after, và vì sao guard failure không xuất hiện trong interceptor log?","states":[{"id":"request-response-lifecycle--r1--exploration--state-guest","label":"Sai quyền","observation":"403; trace middleware, guard, filter. Không có service hoặc interceptor.","isSuccess":false},{"id":"request-response-lifecycle--r1--exploration--state-bad-id","label":"Đúng quyền, sai id","observation":"400; interceptor before có mặt; pipe dừng handler; error path rồi filter.","isSuccess":false},{"id":"request-response-lifecycle--r1--exploration--state-valid","label":"Request hợp lệ","observation":"200; outer.before, inner.before, pipe, controller, service, inner.after, outer.after.","isSuccess":true}],"actions":[{"id":"request-response-lifecycle--r1--exploration--action-allow","label":"Đổi principal sang admin"},{"id":"request-response-lifecycle--r1--exploration--action-fix-id","label":"Đổi id thành 7"}],"transitions":[{"id":"request-response-lifecycle--r1--exploration--transition-0","fromStateId":"request-response-lifecycle--r1--exploration--state-guest","actionId":"request-response-lifecycle--r1--exploration--action-allow","toStateId":"request-response-lifecycle--r1--exploration--state-bad-id"},{"id":"request-response-lifecycle--r1--exploration--transition-1","fromStateId":"request-response-lifecycle--r1--exploration--state-bad-id","actionId":"request-response-lifecycle--r1--exploration--action-fix-id","toStateId":"request-response-lifecycle--r1--exploration--state-valid"}]}}],"id":"2-experiment"},{"title":"Một pipeline có ba đường","phase":"explain","sortIndex":3,"body":"Hãy xem pipeline như một chuỗi quyền đi tiếp. Middleware chuẩn bị context chung, guard quyết định có được vào handler, pipe chuẩn hóa giá trị mà handler nhận, rồi controller gọi nghiệp vụ. Interceptor bao quanh phần phía trong nên có cả vị trí trước và sau. Đường lỗi tách khỏi đường success: nếu pipe ném lỗi, controller không chạy; nếu service ném lỗi, code sau nó trên đường success cũng không mặc nhiên chạy.\n\nSự khác nhau quan trọng là “đã vào” và “chưa từng vào”. Interceptor chưa được vào vì guard chặn không thể ghi log lỗi của request đó. Interceptor đã được vào có thể dùng xử lý error để quan sát lỗi phát sinh bên trong. Nếu nó chuyển error thành giá trị hợp lệ thì filter sẽ không nhận cùng lỗi đó nữa. Vì vậy log tập trung cho toàn bộ request thường cần một điểm sớm hơn và cơ chế ghi lúc response kết thúc.\n\nThứ tự HTTP này là kiến thức về NestJS, không phải bằng chứng rằng mọi framework đều sắp cùng thứ tự. Nó cũng không bảo đảm guard rẻ hơn pipe: một guard có thể gọi dịch vụ bên ngoài. Khi đo chi phí, hãy đo thực tế.","id":"3-theory-1"},{"title":"Chọn tầng bằng context cần dùng","phase":"explain","sortIndex":4,"body":"**Không dùng tên lớp để quyết định; dùng dữ liệu cần thấy và thời điểm cần tác động.**\n\n| Việc cần làm | Tầng phù hợp | Lý do |\n| --- | --- | --- |\n| Gắn request ID | Middleware | Cần xuất hiện sớm trên cả success và failure |\n| Đọc metadata quyền của handler | Guard | Có ExecutionContext và quyết định cho qua |\n| Đổi id chuỗi thành số nguyên dương | Pipe | Làm việc trên tham số trước khi gọi handler |\n| Kiểm tra đơn hàng có được hủy | Service | Quy tắc nghiệp vụ phải tồn tại ngoài HTTP |\n| Bọc response JSON | Interceptor | Nhìn được giá trị trả về của handler |\n| Chuẩn hóa exception chưa xử lý | Filter | Xử lý đường lỗi thay vì giá trị success |\n\nValidation tại biên không thay thế invariant nghiệp vụ. Một id đúng kiểu có thể không tồn tại; một đơn hàng tồn tại có thể đã giao. Pipe trả lời input có đúng hình dạng không; service trả lời hành động có hợp lệ trong trạng thái hiện tại không. Với authorization theo tài nguyên, còn phải tránh kiểm quyền trên dữ liệu client tự khai hoặc kiểm quyền rồi sử dụng một bản ghi đã thay đổi.","id":"4-theory-2"},{"title":"Hai interceptor là hai lớp bao","phase":"explain","sortIndex":5,"body":"Đăng ký outer rồi inner tạo thứ tự outer.before → inner.before → handler → inner.after → outer.after trên đường success. Nếu outer tạo response envelope có executionMs, còn inner tính executionMs sau handler, outer đọc được giá trị inner vừa ghi. Đảo thứ tự có thể khiến envelope lấy giá trị quá sớm. Đây là quan hệ bao nhau, không phải chạy cùng một danh sách hai lần.\n\n**Vẽ thụt lề để nhìn trách nhiệm bọc.**\n\n```text\nouter.before\n  inner.before\n    pipe\n    controller → service\n  inner.after\nouter.after\n```\n\nMột map biến đổi data không chạy khi stream phát lỗi. finalize phù hợp cho tác vụ dọn dẹp khi stream kết thúc, nhưng đo kết thúc observable không tự đồng nghĩa đã gửi xong toàn bộ response trên socket. Với streaming, file download hoặc response do handler trực tiếp điều khiển, wrapper JSON toàn cục có thể làm sai giao thức. Hãy khai rõ route nào tham gia wrapper.","id":"5-theory-3"},{"title":"Đọc mô hình rồi tìm bằng chứng","phase":"explain","sortIndex":6,"body":"**source.ts có thể chạy qua bộ kiểm tra đi kèm. Đây là mô hình nhỏ để phân tích thứ tự, không dùng thay source NestJS.**\n\n```typescript\n/** Mô hình thứ tự xử lý, không phải runtime NestJS. (EN: Educational pipeline model, not NestJS.) */\ntype Result = { status: number; trace: string[]; value?: number };\n/** Chạy một request với log từng tầng. (EN: Trace one request through the model.) */\nexport function runRequest(role: string, rawId: string): Result {\n    const trace: string[] = ['middleware'];\n    trace.push('guard');\n    if (role !== 'admin') {\n        trace.push('filter');\n        return {status: 403, trace};\n    }\n    trace.push('outer.before', 'inner.before', 'pipe');\n    const id = Number(rawId);\n    if (!Number.isSafeInteger(id) || id <= 0) {\n        trace.push('inner.error', 'outer.error', 'filter');\n        return {status: 400, trace};\n    }\n    trace.push('controller', 'service', 'inner.after', 'outer.after');\n    return {status: 200, trace, value: id};\n}\n```\n\nĐọc nhánh role trước khi đọc nhánh id. Return ở nhánh guard kết thúc hàm trước outer.before; return ở nhánh pipe giữ trace interceptor trước nhưng không có controller. Code nêu rõ chính sách error của fixture. Khi đọc ứng dụng thật, phải kiểm tra interceptor và filter đã đăng ký gì; không áp trace fixture cho mọi app.","activities":[{"id":"request-response-lifecycle--r1--quiz-filter","kind":"choice","prompt":"Request thành công có bắt buộc chạy exception filter không?","stableKey":"quiz-filter","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Không vẽ filter như một bước bắt buộc sau response.","misconception":"Có, filter luôn là bước cuối; Chỉ nếu response là JSON"},"options":[{"id":"request-response-lifecycle--r1--quiz-filter--option-1","label":"Có, filter luôn là bước cuối","explanation":"Sai: filter dành cho exception chưa được xử lý.","isCorrect":false},{"id":"request-response-lifecycle--r1--quiz-filter--option-2","label":"Không, response thành công có thể đi qua interceptor rồi trả về","explanation":"Đúng: success và exception là hai đường khác nhau.","isCorrect":true},{"id":"request-response-lifecycle--r1--quiz-filter--option-3","label":"Chỉ nếu response là JSON","explanation":"Sai: định dạng JSON không kích hoạt exception filter.","isCorrect":false}]},{"id":"request-response-lifecycle--r1--quiz-context","kind":"choice","prompt":"Guard cần dùng id đã transform bởi pipe. Quyết định nào đúng?","stableKey":"quiz-context","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism"],"placementSortIndex":1,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Mỗi tầng phải kiểm soát giả định đầu vào của chính nó.","misconception":"Đọc req.params.id như number vì pipe sẽ chạy; Di chuyển toàn bộ service vào middleware"},"options":[{"id":"request-response-lifecycle--r1--quiz-context--option-1","label":"Đọc req.params.id như number vì pipe sẽ chạy","explanation":"Sai: thời điểm tương lai không tạo dữ liệu ở hiện tại.","isCorrect":false},{"id":"request-response-lifecycle--r1--quiz-context--option-2","label":"Thiết kế guard với dữ liệu thực sự có tại thời điểm chạy; không dựa vào pipe phía sau","explanation":"Đúng: phải kiểm hoặc chuẩn hóa phần cần dùng tại boundary của guard, tránh giả định sai.","isCorrect":true},{"id":"request-response-lifecycle--r1--quiz-context--option-3","label":"Di chuyển toàn bộ service vào middleware","explanation":"Sai: làm vậy mất ranh giới nghiệp vụ và không giải quyết hợp đồng dữ liệu.","isCorrect":false}]}],"id":"6-theory-4"},{"title":"Thực hành có bằng chứng","phase":"apply","sortIndex":7,"body":"Workspace Source hiển thị source.ts bên cạnh bài đọc. Chạy test trước, sửa mô hình để quan sát lỗi, rồi phục hồi và chạy lại. Bộ test đi kèm kiểm ba đường xử lý, không gọi HTTP.\n\n**Windows PowerShell: chạy trong thư mục concept với Node.js 24.**\n\n```powershell\nnode --test source.test.ts\n```\n\n**macOS/Linux: cùng lệnh, chạy trong thư mục concept.**\n\n```bash\nnode --test source.test.ts\n```\n\nBài mở rộng với NestJS: dùng repository được dẫn trong bài V1, thêm request-ID vào log middleware/guard/pipe/service và gọi request hợp lệ, lỗi quyền, lỗi input. Đây là integration bổ sung; các test mô hình trong bộ seed chưa chứng minh repository đó chạy.","activities":[{"id":"request-response-lifecycle--r1--practice-trace","kind":"exercise","prompt":"Nộp trace của 3 cặp (guest,-1), (admin,-1), (admin,7). Đổi thứ tự inner.after và outer.after rồi mô tả trường executionMs trong wrapper có thể đọc sai ra sao. Chỉ ra test nào phát hiện thứ tự bị đổi.","stableKey":"practice-trace","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism","request-response-lifecycle--r1--application","request-response-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"request-response-lifecycle--r1--practice-trace--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Nộp đủ ba trace, phân biệt guard failure với pipe failure và service success.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"request-response-lifecycle--r1--practice-trace--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Giải thích inner.after trước outer.after; wrapper đọc executionMs phải sau bước tính nó.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"request-response-lifecycle--r1--practice-trace--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Chỉ ra assertion so thứ tự trace, không chỉ status.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"guest dừng ở guard; admin với -1 vào interceptor và pipe nhưng không tới service; admin với 7 đi đủ đường success, inner.after trước outer.after. Test phải so sánh thứ tự trace chứ không chỉ status. Nếu wrapper chạy trước bước đo cuối thì executionMs chưa được gán.","sampleAnswer":"guest dừng ở guard; admin với -1 vào interceptor và pipe nhưng không tới service; admin với 7 đi đủ đường success, inner.after trước outer.after. Test phải so sánh thứ tự trace chứ không chỉ status. Nếu wrapper chạy trước bước đo cuối thì executionMs chưa được gán.","misconception":"Pipe luôn chuẩn hóa trước guard.; Exception filter chạy sau mọi response thành công.; Chỉ nhìn HTTP status đã đủ chứng minh tầng lỗi."},"exercise":{"submissionInstructions":"Nộp trace của 3 cặp (guest,-1), (admin,-1), (admin,7). Đổi thứ tự inner.after và outer.after rồi mô tả trường executionMs trong wrapper có thể đọc sai ra sao. Chỉ ra test nào phát hiện thứ tự bị đổi.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production.","files":[{"relativePath":"source.ts","role":"reference","syntaxLanguage":"typescript","content":"/** Mô hình thứ tự xử lý, không phải runtime NestJS. (EN: Educational pipeline model, not NestJS.) */\ntype Result = { status: number; trace: string[]; value?: number };\n/** Chạy một request với log từng tầng. (EN: Trace one request through the model.) */\nexport function runRequest(role: string, rawId: string): Result {\n    const trace: string[] = ['middleware'];\n    trace.push('guard');\n    if (role !== 'admin') {\n        trace.push('filter');\n        return {status: 403, trace};\n    }\n    trace.push('outer.before', 'inner.before', 'pipe');\n    const id = Number(rawId);\n    if (!Number.isSafeInteger(id) || id <= 0) {\n        trace.push('inner.error', 'outer.error', 'filter');\n        return {status: 400, trace};\n    }\n    trace.push('controller', 'service', 'inner.after', 'outer.after');\n    return {status: 200, trace, value: id};\n}\n","sha256":"e6fa5a8b079490f9aaa0f21dee280cd6e70c222121d64c2297025fde6b713384"},{"relativePath":"source.test.ts","role":"checks","syntaxLanguage":"typescript","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {runRequest} from './source.ts';\ntest('guard stops before interceptor and pipe', (): void => {assert.deepEqual(runRequest('guest','-1'),{status:403,trace:['middleware','guard','filter']});});\ntest('invalid input never reaches business', (): void => {const r=runRequest('admin','-1');assert.equal(r.status,400);assert.deepEqual(r.trace,['middleware','guard','outer.before','inner.before','pipe','inner.error','outer.error','filter']);});\ntest('success unwinds in reverse order', (): void => {const r=runRequest('admin','7');assert.equal(r.value,7);assert.deepEqual(r.trace,['middleware','guard','outer.before','inner.before','pipe','controller','service','inner.after','outer.after']);});\n","sha256":"50cbc285ef3c9556c63de548199683c07e883085fca04b6b4494510bd48307e3"}],"checks":[{"id":"request-response-lifecycle--r1--practice-trace--node-tests","runner":"node-test","entrypoint":"source.test.ts","expectedExitCode":0,"scope":"educational-local-model","runtime":"Node.js 24","executionStatus":"passed"}]}}],"id":"7-practice"},{"title":"Tình huống mới","phase":"apply","sortIndex":8,"body":"Đóng lời giải trước khi làm. Nếu dùng gợi ý, hệ thống vẫn ghi nhận bài làm nhưng gắn nhãn có hỗ trợ.","activities":[{"id":"request-response-lifecycle--r1--transfer-download","kind":"exercise","prompt":"API tải báo cáo trả stream CSV nhưng interceptor toàn cục bọc mọi kết quả trong {data}. Thiết kế thay đổi tối thiểu để giữ JSON wrapper cho API thường và giữ giao thức download. Nêu trace/lời khẳng định cần kiểm tra.","stableKey":"transfer-download","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism","request-response-lifecycle--r1--application","request-response-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"request-response-lifecycle--r1--transfer-download--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Tách hoặc opt out wrapper JSON cho download bằng policy/metadata rõ.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"request-response-lifecycle--r1--transfer-download--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Giữ bytes CSV, content-type và header; không thay protocol bằng object data.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"request-response-lifecycle--r1--transfer-download--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Kiểm đường lỗi trước/sau khi gửi headers; 200 không tự chứng minh file đúng.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"Cho route download cơ chế bỏ wrapper hoặc tách policy của interceptor dựa vào metadata; handler/service vẫn giữ trách nhiệm tạo báo cáo. Kiểm content-type, nội dung bytes, header download và đường lỗi trước/sau khi gửi header. Không lấy một response 200 làm bằng chứng CSV còn nguyên.","sampleAnswer":"Cho route download cơ chế bỏ wrapper hoặc tách policy của interceptor dựa vào metadata; handler/service vẫn giữ trách nhiệm tạo báo cáo. Kiểm content-type, nội dung bytes, header download và đường lỗi trước/sau khi gửi header. Không lấy một response 200 làm bằng chứng CSV còn nguyên.","misconception":"Pipe luôn chuẩn hóa trước guard.; Exception filter chạy sau mọi response thành công.; Chỉ nhìn HTTP status đã đủ chứng minh tầng lỗi."},"exercise":{"submissionInstructions":"API tải báo cáo trả stream CSV nhưng interceptor toàn cục bọc mọi kết quả trong {data}. Thiết kế thay đổi tối thiểu để giữ JSON wrapper cho API thường và giữ giao thức download. Nêu trace/lời khẳng định cần kiểm tra.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production."}}],"id":"8-transfer"},{"title":"Phỏng vấn lại và tự giải thích","phase":"reflect","sortIndex":9,"body":"Bạn đã dùng thứ tự và context để giải thích lỗi, thay vì chọn tầng theo thói quen. Khi debug request tiếp theo, hãy hỏi: tầng nào đã chạy, tầng nào chưa từng được vào, dữ liệu đó được tạo trước hay sau điểm đang đọc?\n\nAI trả kết quả theo từng tiêu chí và trích đoạn bài nộp làm bằng chứng. Khi chấm chưa xong, trạng thái là đang chấm; bạn có thể tiếp tục đọc và quay lại. Điểm phỏng vấn không tăng chỉ vì câu trả lời dài.","activities":[{"id":"request-response-lifecycle--r1--final-interview","kind":"explain","prompt":"Nếu service ném lỗi sau khi hai interceptor đã vào, liệu outer.map chắc chắn chạy và filter chắc chắn bắt lỗi không? Giải thích các khả năng, đối chiếu với guard failure và đề xuất bằng chứng.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism","request-response-lifecycle--r1--application","request-response-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"request-response-lifecycle--r1--final-interview--criterion-0","criterion":"Thứ tự và dữ liệu","expectedEvidence":"Nêu guard chạy trước pipe; guard không dùng kết quả transform của pipe.","misconception":"Pipe luôn chuẩn hóa trước guard.","maxScore":2},{"id":"request-response-lifecycle--r1--final-interview--criterion-1","criterion":"Nhánh lỗi","expectedEvidence":"Phân biệt lỗi guard, lỗi pipe và lỗi service; chỉ interceptor đã vào mới có thể xử lý lỗi bên trong.","misconception":"Exception filter chạy sau mọi response thành công.","maxScore":2},{"id":"request-response-lifecycle--r1--final-interview--criterion-2","criterion":"Bằng chứng","expectedEvidence":"Đề xuất trace theo request ID và chứng minh service không được gọi khi bị chặn.","misconception":"Chỉ nhìn HTTP status đã đủ chứng minh tầng lỗi.","maxScore":2}],"answer":{"explanation":"map xử lý giá trị thành công nên không chắc chạy khi service throw. Nếu interceptor catchError đổi lỗi thành giá trị thì đường success có thể tiếp tục và filter không nhận lỗi đã xử lý; nếu rethrow thì filter thích hợp có thể nhận. Guard failure xảy ra trước hai interceptor nên chúng không quan sát lỗi đó. Cần trace theo request ID và kiểm cấu hình error handling, không chỉ dựa tên tầng.","sampleAnswer":"map xử lý giá trị thành công nên không chắc chạy khi service throw. Nếu interceptor catchError đổi lỗi thành giá trị thì đường success có thể tiếp tục và filter không nhận lỗi đã xử lý; nếu rethrow thì filter thích hợp có thể nhận. Guard failure xảy ra trước hai interceptor nên chúng không quan sát lỗi đó. Cần trace theo request ID và kiểm cấu hình error handling, không chỉ dựa tên tầng.","misconception":"Pipe luôn chuẩn hóa trước guard.; Exception filter chạy sau mọi response thành công.; Chỉ nhìn HTTP status đã đủ chứng minh tầng lỗi."}}],"id":"9-reflection"}]},"en":{"title":"Request lifecycle — put logic in the right layer","description":"The request lifecycle is the sequence of layers that receive, control, process and return a request, including success and error paths.","body":"## Summary\n\nYou have used order and context to explain failures instead of choosing layers by habit. When debugging the next request, ask which layers ran, which were never entered, and whether the data existed before the point where it was read.\n\n## Learning outcomes\n\n- Predict the trace for a valid request, a guard rejection and a pipe rejection.\n- Place validation, authorization and response wrapping in appropriate layers and verify them with traces.\n- Explain the limitations of wrappers and interceptors on error paths.\n\n## Prerequisites\n\n- Read TypeScript functions, Promises and thrown errors.\n- Distinguish an HTTP request, status and handler.\n\n## Included scope\n\n- The order of middleware, guards, interceptors, pipes and handlers.\n- LIFO on the return path and the error path.\n- Choose layers by timing and context, then verify the choice with traces.\n\n## Excluded scope\n\n- A complete JWT implementation.\n- Advanced request scope and dependency injection.\n- WebSocket and queue transports.\n\n## Key claims\n\n- Guards run before pipes in the NestJS HTTP lifecycle.\n- Interceptors enter in registration order and process the return path in reverse order.\n- Filters handle unhandled exceptions; they are not a mandatory step on the success path.\n\n## Corrections\n\n- Placing an exception filter at the end of a linear diagram is misleading: filters do not run for every response.\n- A guard preceding a pipe does not mean the body is unparsed; body parsing or middleware may already have run.\n- Do not trust a client-declared role. The model's role is a fixture; a real application needs an authenticated principal.\n- Running the local model verifies its illustrative logic, not NestJS integration.\n\n## References\n\n- [docs.nestjs.com/faq/request-lifecycle](https://docs.nestjs.com/faq/request-lifecycle)\n- [docs.nestjs.com/interceptors](https://docs.nestjs.com/interceptors)\n- [docs.nestjs.com/middleware](https://docs.nestjs.com/middleware)","learningOutcomes":[{"id":"request-response-lifecycle--r1--mechanism","text":"Predict the trace for a valid request, a guard rejection and a pipe rejection."},{"id":"request-response-lifecycle--r1--application","text":"Place validation, authorization and response wrapping in appropriate layers and verify them with traces."},{"id":"request-response-lifecycle--r1--tradeoffs","text":"Explain the limitations of wrappers and interceptors on error paths."}],"prerequisites":[{"id":"request-response-lifecycle--r1--input-0","text":"Read TypeScript functions, Promises and thrown errors."},{"id":"request-response-lifecycle--r1--input-1","text":"Distinguish an HTTP request, status and handler."}],"references":[{"id":"request-response-lifecycle--r1--legacy","label":"Pre-migration data source","citation":"legacy; courses/0-fullstack-mastery/modules/0-nestjs-core-and-request-lifecycle/contents/1-request-response-lifecycle/bodies/0-typescript/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 9b583cebc7917d725564f9de7afb33741bc20fa2b70c16ab3038461c9f8d3884; checked 2026-09-05; New V2 sample; V1 remains unchanged."},{"id":"request-response-lifecycle--r1--official-0","label":"docs.nestjs.com/faq/request-lifecycle","url":"https://docs.nestjs.com/faq/request-lifecycle","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."},{"id":"request-response-lifecycle--r1--official-1","label":"docs.nestjs.com/interceptors","url":"https://docs.nestjs.com/interceptors","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."},{"id":"request-response-lifecycle--r1--official-2","label":"docs.nestjs.com/middleware","url":"https://docs.nestjs.com/middleware","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."}],"retrieval":[{"id":"request-response-lifecycle--r1--retrieval-1","kind":"retrieval","prompt":"After one day: there is no service log, but interceptor.before appears. Give one possible cause and a check that distinguishes it from guard failure.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism"],"afterDays":1,"rubric":[{"id":"request-response-lifecycle--r1--retrieval-1--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"The pipe may have rejected the input. Inspect the pipe trace and status. A guard rejection before the interceptors produces no interceptor.before entry in this configuration.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"The pipe may have rejected the input. Inspect the pipe trace and status. A guard rejection before the interceptors produces no interceptor.before entry in this configuration.","sampleAnswer":"The pipe may have rejected the input. Inspect the pipe trace and status. A guard rejection before the interceptors produces no interceptor.before entry in this configuration.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"request-response-lifecycle--r1--retrieval-2","kind":"retrieval","prompt":"After one week: adding a response-compression interceptor changes timing. Explain the order, adjust timing to include compression, and state the measurement's limits.","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--application"],"afterDays":7,"rubric":[{"id":"request-response-lifecycle--r1--retrieval-2--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"Wrap timing around compression so it includes the inner processing, and verify LIFO order. Observable duration still does not automatically equal the time until the user finishes downloading the response.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"Wrap timing around compression so it includes the inner processing, and verify LIFO order. Observable duration still does not automatically equal the time until the user finishes downloading the response.","sampleAnswer":"Wrap timing around compression so it includes the inner processing, and verify LIFO order. Observable duration still does not automatically equal the time until the user finishes downloading the response.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"request-response-lifecycle--r1--retrieval-3","kind":"retrieval","prompt":"After 21 days: a queue consumer calls the same service as HTTP. Why is HTTP validation insufficient? Propose the new boundary without duplicating business logic.","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"request-response-lifecycle--r1--retrieval-3--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"A queue has a different input boundary and does not automatically traverse the HTTP pipeline. Validate messages at the consumer boundary and keep business invariants in the shared service. Test the consumer with invalid messages; HTTP tests are not a substitute.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"A queue has a different input boundary and does not automatically traverse the HTTP pipeline. Validate messages at the consumer boundary and keep business invariants in the shared service. Test the consumer with invalid messages; HTTP tests are not a substitute.","sampleAnswer":"A queue has a different input boundary and does not automatically traverse the HTTP pipeline. Validate messages at the consumer boundary and keep business invariants in the shared service. Test the consumer with invalid messages; HTTP tests are not a substitute.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}}],"sections":[{"title":"Interview context","phase":"challenge","sortIndex":0,"body":"In a backend interview, two requests reach the same administration API: one lacks permission, and the other has id = -1. The interviewer asks, 'Neither reaches the service, but why does only one produce a timing log?' You answer, 'Validation rejects it early.' The interviewer follows up: 'Does validation run before or after authorization?'\n\nAnswer using your current understanding. This initial diagnostic does not establish mastery. You will answer again after practice, and the lesson remains open if you do not yet know the answer.","activities":[{"id":"request-response-lifecycle--r1--opening-interview","kind":"explain","prompt":"Explain the two requests, the layer order, and where you would log to distinguish authorization failure from input failure.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism","request-response-lifecycle--r1--application","request-response-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"request-response-lifecycle--r1--opening-interview--criterion-0","criterion":"Order and data","expectedEvidence":"State that the guard precedes the pipe and cannot consume the pipe's transformed result.","misconception":"Pipes always normalize before guards.","maxScore":2},{"id":"request-response-lifecycle--r1--opening-interview--criterion-1","criterion":"Error branches","expectedEvidence":"Distinguish guard, pipe and service failures; only interceptors already entered can handle inner errors.","misconception":"Exception filters run after every successful response.","maxScore":2},{"id":"request-response-lifecycle--r1--opening-interview--criterion-2","criterion":"Evidence","expectedEvidence":"Propose request-ID traces and demonstrate that the service is not called after rejection.","misconception":"HTTP status alone proves which layer failed.","maxScore":2}],"answer":{"explanation":"Middleware runs before the guard. A guard rejects an unauthorized request before downstream interceptors are entered. With valid permissions but an invalid ID, the interceptors have wrapped the inner work and the pipe throws before the controller or service. An interceptor may observe errors through the appropriate RxJS branch; map processes successful values only. A filter receives errors that remain unhandled. Attach a request ID in middleware and trace each layer instead of inferring the cause from the status alone.","sampleAnswer":"Middleware runs before the guard. A guard rejects an unauthorized request before downstream interceptors are entered. With valid permissions but an invalid ID, the interceptors have wrapped the inner work and the pipe throws before the controller or service. An interceptor may observe errors through the appropriate RxJS branch; map processes successful values only. A filter receives errors that remain unhandled. Attach a request ID in middleware and trace each layer instead of inferring the cause from the status alone.","misconception":"Pipes always normalize before guards.; Exception filters run after every successful response.; HTTP status alone proves which layer failed."}}],"id":"0-interview"},{"title":"Predict before observing","phase":"predict","sortIndex":1,"body":"Fixture: role = guest and id = -1. The guard precedes two interceptors, followed by the pipe. A configured filter normalizes errors. Select one answer.","activities":[{"id":"request-response-lifecycle--r1--predict-order","kind":"choice","prompt":"Which trace matches this request?","stableKey":"predict-order","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"A request can contain several faults, but the first failing layer determines the path in this fixture.","misconception":"middleware → pipe → guard → filter; middleware → guard → interceptor → pipe → filter"},"options":[{"id":"request-response-lifecycle--r1--predict-order--option-1","label":"middleware → guard → filter","explanation":"Correct: the guard rejects the request before the interceptors and pipe run.","isCorrect":true},{"id":"request-response-lifecycle--r1--predict-order--option-2","label":"middleware → pipe → guard → filter","explanation":"Incorrect: this assumes that the pipe runs before the guard.","isCorrect":false},{"id":"request-response-lifecycle--r1--predict-order--option-3","label":"middleware → guard → interceptor → pipe → filter","explanation":"Incorrect: the guard has rejected the request, so the business pipeline does not continue.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Experiment and observe","phase":"explore","sortIndex":2,"body":"In the simulation, try insufficient permissions first, then fix permissions while keeping the invalid ID. Do not change both conditions at once: you need to see which layers run or are skipped. Finally, fix the ID and compare the inner and outer return order.\n\n**A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.**\n\n```mermaid\nflowchart TD\n M[Middleware] --> G{Guard}\n G -->|allow| I[Interceptor before]\n G -->|deny| F[Exception filter]\n I --> P{Pipe}\n P -->|valid| H[Controller and service]\n P -->|throw| E[Interceptor error path]\n H --> O[Interceptor after LIFO]\n E -->|unhandled| F\n O --> R[Success response]\n F --> X[Error response]\n```\n\n> A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.","activities":[{"id":"request-response-lifecycle--r1--exploration","kind":"simulation","prompt":"Try an incorrect path first, read the observed state, then find a solution. Finish by explaining the cause.","stableKey":"exploration","outcomeIds":["request-response-lifecycle--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"request-response-lifecycle--r1--exploration--state-guest","debriefQuestion":"Why does inner.after precede outer.after, and why is guard failure absent from interceptor logs?","states":[{"id":"request-response-lifecycle--r1--exploration--state-guest","label":"Unauthorized","observation":"403; trace: middleware, guard, filter. No service or interceptor entries.","isSuccess":false},{"id":"request-response-lifecycle--r1--exploration--state-bad-id","label":"Authorized, invalid ID","observation":"400; interceptor-before entries are present; the pipe prevents the handler from running, followed by the error path and filter.","isSuccess":false},{"id":"request-response-lifecycle--r1--exploration--state-valid","label":"Valid request","observation":"200; outer.before, inner.before, pipe, controller, service, inner.after, outer.after.","isSuccess":true}],"actions":[{"id":"request-response-lifecycle--r1--exploration--action-allow","label":"Change the principal to admin"},{"id":"request-response-lifecycle--r1--exploration--action-fix-id","label":"Change the ID to 7"}],"transitions":[{"id":"request-response-lifecycle--r1--exploration--transition-0","fromStateId":"request-response-lifecycle--r1--exploration--state-guest","actionId":"request-response-lifecycle--r1--exploration--action-allow","toStateId":"request-response-lifecycle--r1--exploration--state-bad-id"},{"id":"request-response-lifecycle--r1--exploration--transition-1","fromStateId":"request-response-lifecycle--r1--exploration--state-bad-id","actionId":"request-response-lifecycle--r1--exploration--action-fix-id","toStateId":"request-response-lifecycle--r1--exploration--state-valid"}]}}],"id":"2-experiment"},{"title":"One pipeline, three paths","phase":"explain","sortIndex":3,"body":"Think of the pipeline as a sequence of permissions to continue. Middleware prepares shared context, the guard permits access to the handler, the pipe normalizes handler arguments, and the controller invokes business logic. Interceptors wrap the inner work, giving them before and after positions. Error and success paths diverge: if the pipe throws, the controller does not run; if the service throws, subsequent success-path code does not automatically run either.\n\nThe key distinction is between 'entered' and 'never entered.' An interceptor skipped by a rejecting guard cannot log that request's error. An interceptor already entered can use error handling to observe failures inside it. If it converts the error into a valid value, a filter will not receive the same error. Complete request logging therefore usually needs an earlier entry point and a mechanism that records response completion.\n\nThis HTTP order describes NestJS; it does not prove that every framework uses the same order. It also does not mean a guard is cheaper than a pipe: a guard may call an external service. Measure actual costs.","id":"3-theory-1"},{"title":"Choose a layer by the context it needs","phase":"explain","sortIndex":4,"body":"**Choose by the data a layer needs and when it must act, rather than by its class name.**\n\n| Task | Suitable layer | Reason |\n| --- | --- | --- |\n| Attach a request ID | Middleware | It must be available early on both success and failure paths |\n| Read the handler's authorization metadata | Guard | ExecutionContext is available and the guard decides whether execution may continue |\n| Convert a string ID into a positive integer | Pipe | Processes parameters before the handler is invoked |\n| Check whether an order may be cancelled | Service | Business rules must also hold outside HTTP |\n| Wrap a JSON response | Interceptor | Can observe the handler's return value |\n| Normalize an unhandled exception | Filter | Handles the error path rather than a successful value |\n\nBoundary validation does not replace business invariants. A correctly typed ID may not exist, and an existing order may already have shipped. A pipe checks input shape; the service checks whether an action is valid in the current state. Resource authorization must also avoid trusting client-supplied facts or authorizing a record and then using a changed version of it.","id":"4-theory-2"},{"title":"Two interceptors form two wrappers","phase":"explain","sortIndex":5,"body":"Registering outer before inner produces outer.before → inner.before → handler → inner.after → outer.after on success. If outer creates an envelope containing executionMs and inner calculates executionMs after the handler, outer can read the value inner just wrote. Reversing them may read it too early. These are nested wrappers, not one list run twice.\n\n**Use indentation to reveal wrapping responsibilities.**\n\n```text\nouter.before\n  inner.before\n    pipe\n    controller → service\n  inner.after\nouter.after\n```\n\nA data-transforming map does not run when the stream emits an error. finalize is suitable for cleanup when a stream terminates, but observable completion does not automatically mean all response bytes have left the socket. A global JSON wrapper may break streaming, downloads or directly managed responses. Explicitly define which routes participate in wrapping.","id":"5-theory-3"},{"title":"Read the model, then find evidence","phase":"explain","sortIndex":6,"body":"**Run source.ts through the accompanying tests. This small model explains execution order; it does not replace NestJS source code.**\n\n```typescript\n/** Mô hình thứ tự xử lý, không phải runtime NestJS. (EN: Educational pipeline model, not NestJS.) */\ntype Result = { status: number; trace: string[]; value?: number };\n/** Chạy một request với log từng tầng. (EN: Trace one request through the model.) */\nexport function runRequest(role: string, rawId: string): Result {\n    const trace: string[] = ['middleware'];\n    trace.push('guard');\n    if (role !== 'admin') {\n        trace.push('filter');\n        return {status: 403, trace};\n    }\n    trace.push('outer.before', 'inner.before', 'pipe');\n    const id = Number(rawId);\n    if (!Number.isSafeInteger(id) || id <= 0) {\n        trace.push('inner.error', 'outer.error', 'filter');\n        return {status: 400, trace};\n    }\n    trace.push('controller', 'service', 'inner.after', 'outer.after');\n    return {status: 200, trace, value: id};\n}\n```\n\nRead the role branch before the ID branch. Returning from the guard ends the function before outer.before; returning from the pipe preserves the interceptor-before trace but excludes the controller. The code makes the fixture's error policy explicit. In a real application, inspect registered interceptors and filters rather than assuming every app has this trace.","activities":[{"id":"request-response-lifecycle--r1--quiz-filter","kind":"choice","prompt":"Must a successful request run an exception filter?","stableKey":"quiz-filter","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Do not draw the filter as a mandatory step after every response.","misconception":"Yes, the filter is always the last step; Only when the response is JSON"},"options":[{"id":"request-response-lifecycle--r1--quiz-filter--option-1","label":"Yes, the filter is always the last step","explanation":"Incorrect: filters handle unhandled exceptions.","isCorrect":false},{"id":"request-response-lifecycle--r1--quiz-filter--option-2","label":"No, a successful response may pass through interceptors and return directly","explanation":"Correct: success and exceptions follow different paths.","isCorrect":true},{"id":"request-response-lifecycle--r1--quiz-filter--option-3","label":"Only when the response is JSON","explanation":"Incorrect: JSON formatting does not trigger an exception filter.","isCorrect":false}]},{"id":"request-response-lifecycle--r1--quiz-context","kind":"choice","prompt":"A guard needs an ID transformed by a pipe. Which decision is correct?","stableKey":"quiz-context","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism"],"placementSortIndex":1,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Each layer must control its own assumptions about input.","misconception":"Read req.params.id as a number because the pipe will run; Move the entire service into middleware"},"options":[{"id":"request-response-lifecycle--r1--quiz-context--option-1","label":"Read req.params.id as a number because the pipe will run","explanation":"Incorrect: a later step cannot supply data to an earlier step.","isCorrect":false},{"id":"request-response-lifecycle--r1--quiz-context--option-2","label":"Design the guard around data available when it runs, without relying on a downstream pipe","explanation":"Correct: validate or normalize what the guard needs at its own boundary rather than relying on a later transformation.","isCorrect":true},{"id":"request-response-lifecycle--r1--quiz-context--option-3","label":"Move the entire service into middleware","explanation":"Incorrect: this erases the business boundary without resolving the data contract.","isCorrect":false}]}],"id":"6-theory-4"},{"title":"Practice with evidence","phase":"apply","sortIndex":7,"body":"The Source workspace places source.ts beside the lesson. Run the tests, modify the model to observe a failure, then restore it and rerun. The included tests check three execution paths without making HTTP calls.\n\n**Windows PowerShell: run in the concept workspace with Node.js 24.**\n\n```powershell\nnode --test source.test.ts\n```\n\n**macOS/Linux: run the same command in the concept workspace.**\n\n```bash\nnode --test source.test.ts\n```\n\nFor an additional NestJS integration exercise, use the repository referenced by the V1 lesson, add request IDs to middleware, guard, pipe and service logs, and send valid, unauthorized and invalid-input requests. This is additional integration work; the seed's model tests do not prove that repository runs.","activities":[{"id":"request-response-lifecycle--r1--practice-trace","kind":"exercise","prompt":"Submit traces for (guest,-1), (admin,-1) and (admin,7). Reverse inner.after and outer.after, explain how the wrapper may read executionMs incorrectly, and identify the test that catches the changed order.","stableKey":"practice-trace","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism","request-response-lifecycle--r1--application","request-response-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"request-response-lifecycle--r1--practice-trace--criterion-0","criterion":"Requested result","expectedEvidence":"Submit all three traces and distinguish guard failure, pipe failure and service success.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"request-response-lifecycle--r1--practice-trace--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Explain why inner.after precedes outer.after and why a wrapper must read executionMs after it is calculated.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"request-response-lifecycle--r1--practice-trace--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Identify an assertion that checks trace order, not merely status.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"guest stops at the guard. admin with -1 enters the interceptors and pipe but never reaches the service. admin with 7 completes the success path with inner.after before outer.after. Tests must compare trace order, not only status. If the wrapper runs before the final timing step, executionMs has not yet been assigned.","sampleAnswer":"guest stops at the guard. admin with -1 enters the interceptors and pipe but never reaches the service. admin with 7 completes the success path with inner.after before outer.after. Tests must compare trace order, not only status. If the wrapper runs before the final timing step, executionMs has not yet been assigned.","misconception":"Pipes always normalize before guards.; Exception filters run after every successful response.; HTTP status alone proves which layer failed."},"exercise":{"submissionInstructions":"Submit traces for (guest,-1), (admin,-1) and (admin,7). Reverse inner.after and outer.after, explain how the wrapper may read executionMs incorrectly, and identify the test that catches the changed order.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works.","files":[{"relativePath":"source.ts","role":"reference","syntaxLanguage":"typescript","content":"/** Mô hình thứ tự xử lý, không phải runtime NestJS. (EN: Educational pipeline model, not NestJS.) */\ntype Result = { status: number; trace: string[]; value?: number };\n/** Chạy một request với log từng tầng. (EN: Trace one request through the model.) */\nexport function runRequest(role: string, rawId: string): Result {\n    const trace: string[] = ['middleware'];\n    trace.push('guard');\n    if (role !== 'admin') {\n        trace.push('filter');\n        return {status: 403, trace};\n    }\n    trace.push('outer.before', 'inner.before', 'pipe');\n    const id = Number(rawId);\n    if (!Number.isSafeInteger(id) || id <= 0) {\n        trace.push('inner.error', 'outer.error', 'filter');\n        return {status: 400, trace};\n    }\n    trace.push('controller', 'service', 'inner.after', 'outer.after');\n    return {status: 200, trace, value: id};\n}\n","sha256":"e6fa5a8b079490f9aaa0f21dee280cd6e70c222121d64c2297025fde6b713384"},{"relativePath":"source.test.ts","role":"checks","syntaxLanguage":"typescript","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {runRequest} from './source.ts';\ntest('guard stops before interceptor and pipe', (): void => {assert.deepEqual(runRequest('guest','-1'),{status:403,trace:['middleware','guard','filter']});});\ntest('invalid input never reaches business', (): void => {const r=runRequest('admin','-1');assert.equal(r.status,400);assert.deepEqual(r.trace,['middleware','guard','outer.before','inner.before','pipe','inner.error','outer.error','filter']);});\ntest('success unwinds in reverse order', (): void => {const r=runRequest('admin','7');assert.equal(r.value,7);assert.deepEqual(r.trace,['middleware','guard','outer.before','inner.before','pipe','controller','service','inner.after','outer.after']);});\n","sha256":"50cbc285ef3c9556c63de548199683c07e883085fca04b6b4494510bd48307e3"}],"checks":[{"id":"request-response-lifecycle--r1--practice-trace--node-tests","runner":"node-test","entrypoint":"source.test.ts","expectedExitCode":0,"scope":"educational-local-model","runtime":"Node.js 24","executionStatus":"passed"}]}}],"id":"7-practice"},{"title":"A new situation","phase":"apply","sortIndex":8,"body":"Close the solution before starting. If you use hints, the system should still record your attempt and label it as assisted.","activities":[{"id":"request-response-lifecycle--r1--transfer-download","kind":"exercise","prompt":"A report endpoint returns a CSV stream, but a global interceptor wraps all results in {data}. Design the smallest change that preserves ordinary JSON wrapping and the download protocol. State the traces and assertions you would check.","stableKey":"transfer-download","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism","request-response-lifecycle--r1--application","request-response-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"request-response-lifecycle--r1--transfer-download--criterion-0","criterion":"Requested result","expectedEvidence":"Separate JSON wrapping from downloads or provide an explicit policy or metadata opt-out.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"request-response-lifecycle--r1--transfer-download--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Preserve CSV bytes, content type and headers instead of replacing the protocol with a data object.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"request-response-lifecycle--r1--transfer-download--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Check errors before and after headers are sent; status 200 alone does not prove file correctness.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"Let download routes opt out of wrapping, or use an explicit metadata-driven interceptor policy. The handler and service still generate the report. Check content type, exact bytes, download headers and failures before and after headers are sent. A 200 response alone does not prove that the CSV is intact.","sampleAnswer":"Let download routes opt out of wrapping, or use an explicit metadata-driven interceptor policy. The handler and service still generate the report. Check content type, exact bytes, download headers and failures before and after headers are sent. A 200 response alone does not prove that the CSV is intact.","misconception":"Pipes always normalize before guards.; Exception filters run after every successful response.; HTTP status alone proves which layer failed."},"exercise":{"submissionInstructions":"A report endpoint returns a CSV stream, but a global interceptor wraps all results in {data}. Design the smallest change that preserves ordinary JSON wrapping and the download protocol. State the traces and assertions you would check.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works."}}],"id":"8-transfer"},{"title":"Interview again and explain your reasoning","phase":"reflect","sortIndex":9,"body":"You have used order and context to explain failures instead of choosing layers by habit. When debugging the next request, ask which layers ran, which were never entered, and whether the data existed before the point where it was read.\n\nAI should return criterion-level results and quote evidence from your submission. While grading is pending, the state remains pending; you can continue reading and return later. Interview scores do not increase merely because an answer is longer.","activities":[{"id":"request-response-lifecycle--r1--final-interview","kind":"explain","prompt":"If the service throws after both interceptors have been entered, must outer.map run and must a filter catch the error? Explain the possibilities, contrast them with guard failure, and propose evidence.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["request-response-lifecycle--r1--mechanism","request-response-lifecycle--r1--application","request-response-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"request-response-lifecycle--r1--final-interview--criterion-0","criterion":"Order and data","expectedEvidence":"State that the guard precedes the pipe and cannot consume the pipe's transformed result.","misconception":"Pipes always normalize before guards.","maxScore":2},{"id":"request-response-lifecycle--r1--final-interview--criterion-1","criterion":"Error branches","expectedEvidence":"Distinguish guard, pipe and service failures; only interceptors already entered can handle inner errors.","misconception":"Exception filters run after every successful response.","maxScore":2},{"id":"request-response-lifecycle--r1--final-interview--criterion-2","criterion":"Evidence","expectedEvidence":"Propose request-ID traces and demonstrate that the service is not called after rejection.","misconception":"HTTP status alone proves which layer failed.","maxScore":2}],"answer":{"explanation":"map processes successful values, so it need not run after a service throws. If catchError turns the error into a value, the success path may continue and the filter will not receive that handled error. If the interceptor rethrows, an applicable filter may receive it. Guard failure occurs before both interceptors, so neither observes it. Use request-ID traces and inspect error-handling configuration rather than relying on layer names.","sampleAnswer":"map processes successful values, so it need not run after a service throws. If catchError turns the error into a value, the success path may continue and the filter will not receive that handled error. If the interceptor rethrows, an applicable filter may receive it. Guard failure occurs before both interceptors, so neither observes it. Use request-ID traces and inspect error-handling configuration rather than relying on layer names.","misconception":"Pipes always normalize before guards.; Exception filters run after every successful response.; HTTP status alone proves which layer failed."}}],"id":"9-reflection"}]}},"workspace":{"runtime":"Node.js 24","files":[{"path":"workspace/source.test.ts","role":"test"},{"path":"workspace/source.ts","role":"source"}],"commands":{"windows":"node --test workspace/source.test.ts","unix":"node --test workspace/source.test.ts"}},"files":[{"path":"workspace/source.test.ts","role":"test","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {runRequest} from './source.ts';\ntest('guard stops before interceptor and pipe', (): void => {assert.deepEqual(runRequest('guest','-1'),{status:403,trace:['middleware','guard','filter']});});\ntest('invalid input never reaches business', (): void => {const r=runRequest('admin','-1');assert.equal(r.status,400);assert.deepEqual(r.trace,['middleware','guard','outer.before','inner.before','pipe','inner.error','outer.error','filter']);});\ntest('success unwinds in reverse order', (): void => {const r=runRequest('admin','7');assert.equal(r.value,7);assert.deepEqual(r.trace,['middleware','guard','outer.before','inner.before','pipe','controller','service','inner.after','outer.after']);});\n"},{"path":"workspace/source.ts","role":"source","content":"/** Mô hình thứ tự xử lý, không phải runtime NestJS. (EN: Educational pipeline model, not NestJS.) */\ntype Result = { status: number; trace: string[]; value?: number };\n/** Chạy một request với log từng tầng. (EN: Trace one request through the model.) */\nexport function runRequest(role: string, rawId: string): Result {\n    const trace: string[] = ['middleware'];\n    trace.push('guard');\n    if (role !== 'admin') {\n        trace.push('filter');\n        return {status: 403, trace};\n    }\n    trace.push('outer.before', 'inner.before', 'pipe');\n    const id = Number(rawId);\n    if (!Number.isSafeInteger(id) || id <= 0) {\n        trace.push('inner.error', 'outer.error', 'filter');\n        return {status: 400, trace};\n    }\n    trace.push('controller', 'service', 'inner.after', 'outer.after');\n    return {status: 200, trace, value: id};\n}\n"}]}$lesson$::jsonb,
    '2026-11-08T00:00:00Z'
