    $lesson${"en.md":"67826c15626cf83c3ede042fc64a1425f463577f15a4e3fe1203152665194f9f","sections/0-interview/en.md":"37c76c34e7a4372eae8ac0d98f59c05f8ba491eb369e30e0dfce50babb8ed5a1","sections/0-interview/vi.md":"6aa2b0ef66ea880702089e3409b9b304ac7e515fd27d0034fe0c5572f364180b","sections/1-prediction/en.md":"ef61a411423636547a9a84e17a562028a3a850e0d28740e109fdfc08e986bdc6","sections/1-prediction/vi.md":"68a01c58325307b30b622ed9b90c2c0f3886c3c604451d465e38051a7b421be4","sections/2-experiment/en.md":"fa9c73f2e53d3bfcbce192f4ec6e961bdc7d8ce9c3a6d944efeaa9328c67cc3e","sections/2-experiment/vi.md":"8b20d251515ff01c747fb54f3561055add61448fbda1e0ad7a93818d1312e6f6","sections/3-theory-1/en.md":"dc75a1e1c48b8488c8b00afce9a71dc6e112d5196cc2f82b1c57a612183b596a","sections/3-theory-1/vi.md":"bcfae5092f8e49267baff9450c1a06e50a62f58627672969196264cbf964fd91","sections/4-theory-2/en.md":"349e7189906a96d744b1ab53ef7a251d436264102b0e76903c5e21af69e9bb19","sections/4-theory-2/vi.md":"2d4b87b452507bd03283559bef6b80ca7f9c229e8e4f613817ab40b2625dbffa","sections/5-theory-3/en.md":"bf5024a4a85f07a3c273feb76c8c79fd23850f9da5a4e8e7fcf3b73954b08d1d","sections/5-theory-3/vi.md":"1aa5e6b482916f944bdfdfe7776dbe0c29a0b487b6eac42211c90963c7e07cd4","sections/6-theory-4/en.md":"ae0ac31f92f02f2106603833931dbca971e5b55d14cfcced0b521ec4686ac742","sections/6-theory-4/vi.md":"531ac5944d74823035410dcc37b5b608d86a1b31024ab4560a0203905ea2a017","sections/7-practice/en.md":"8c125d5fe4462aab0a37904b7b13d8c5be3a8b99492989f3270cf8fe2389f6fa","sections/7-practice/vi.md":"1c6ecf7567a69b904d6db947a9e86611665e76595154644ca080287ee03d0a76","sections/8-transfer/en.md":"6316a1c48f4bfb9ff10dbbcaeeb8832150f7017df4c4f7697b49cf179b6c844e","sections/8-transfer/vi.md":"0ce602ad775ab8612ae81d53d5499e5ad0020a27f86b3313745f1f3a994f633e","sections/9-reflection/en.md":"6bc442fdf6f0edf71b76b29d0141f95ff60334527a790aeb3dbce2d98500dfe9","sections/9-reflection/vi.md":"dfd8560f7d10f4742311b5ef65fdcb7ca808e83a82873bcb785ecd9478b91c20","vi.md":"30143593cebdd105c016c0eb2353ab543faf26c76ce976f7a2173ac6144e3f89","workspace/source.test.ts":"2c8752dc90e2b35d79169a12611a45db2457f95ef509a332984b61f16651b72d","workspace/source.ts":"8428c8b81dcb3f055c73253640116d8029b32f7e05fd7338bf60a38e986370c5"}$lesson$::jsonb,
    $lesson${"locales":{"vi":{"title":"Server-state cache — dữ liệu cũ chưa có nghĩa là phải tải lại","description":"Vòng đời server-state cache quản lý độ mới, thời gian lưu và việc đồng bộ một bản sao dữ liệu server với các thành phần giao diện đang dùng nó.","body":"## Tóm tắt\n\nĐừng hỏi chỉ “có cache không”. Hãy hỏi bản sao thuộc query nào, mới tới đâu, ai đang dùng, và sự kiện nào yêu cầu đồng bộ. Bốn câu hỏi đó giải thích phần lớn những request tưởng là ngẫu nhiên.\n\n## Kết quả học tập\n\n- Dự đoán fresh, stale và collected theo một timeline cụ thể.\n- Chọn key, policy refetch và trạng thái UI cho danh sách dùng chung.\n- Giải thích vì sao cache có thể cũ nhưng còn hữu ích và giới hạn của deduplication.\n\n## Kiến thức đầu vào\n\n- Đọc được hàm async TypeScript và trạng thái component React.\n- Biết request HTTP nhận dữ liệu từ server.\n\n## Phạm vi bao gồm\n\n- Query key và cache dùng chung.\n- Hai đồng hồ staleTime/gcTime; trigger refetch.\n- Phân biệt tải đầu và làm mới nền; nhận diện lỗi cấu hình.\n\n## Phạm vi không bao gồm\n\n- SSR hydration.\n- Optimistic mutation và offline persistence.\n- Thiết kế cache server/CDN.\n\n## Luận điểm chính\n\n- staleTime đo độ mới; gcTime áp dụng cho query không còn observer.\n- Staleness không tự là một interval fetch.\n- Dùng chung QueryClient và query key là điều kiện nền cho chia sẻ cache.\n\n## Điều chỉnh nhận thức\n\n- Nguồn gắn agnostic nhưng ví dụ phụ thuộc React/TanStack; mẫu này khai typescript.\n- Nguồn dùng refetchOnWindowFocus=\"always\"; không suy đó là hành vi mặc định.\n- Dedup không có nghĩa hai component vĩnh viễn chỉ tạo một request.\n- JSON cast sang User[] không phải runtime validation; mẫu không dạy cast như kiểm tra dữ liệu.\n\n## Tham khảo\n\n- [tanstack.com/query/latest/docs/framework/react/guides/important-defaults](https://tanstack.com/query/latest/docs/framework/react/guides/important-defaults)\n- [tanstack.com/query/latest/docs/framework/react/guides/query-keys](https://tanstack.com/query/latest/docs/framework/react/guides/query-keys)","learningOutcomes":[{"id":"server-state-cache-lifecycle--r1--mechanism","text":"Dự đoán fresh, stale và collected theo một timeline cụ thể."},{"id":"server-state-cache-lifecycle--r1--application","text":"Chọn key, policy refetch và trạng thái UI cho danh sách dùng chung."},{"id":"server-state-cache-lifecycle--r1--tradeoffs","text":"Giải thích vì sao cache có thể cũ nhưng còn hữu ích và giới hạn của deduplication."}],"prerequisites":[{"id":"server-state-cache-lifecycle--r1--input-0","text":"Đọc được hàm async TypeScript và trạng thái component React."},{"id":"server-state-cache-lifecycle--r1--input-1","text":"Biết request HTTP nhận dữ liệu từ server."}],"references":[{"id":"server-state-cache-lifecycle--r1--legacy","label":"Nguồn dữ liệu trước migration","citation":"legacy; courses/0-fullstack-mastery/modules/4-server-state-with-tanstack-query/contents/0-usequery-and-cache-lifecycle/bodies/0-agnostic/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 e8d0f7e10d37cdb29cfe256f3ecf4f62c7f32efd400f68fd3aca24ca2e536152; checked 2026-09-05; Bài mẫu V2 mới; không sửa V1."},{"id":"server-state-cache-lifecycle--r1--official-0","label":"tanstack.com/query/latest/docs/framework/react/guides/important-defaults","url":"https://tanstack.com/query/latest/docs/framework/react/guides/important-defaults","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."},{"id":"server-state-cache-lifecycle--r1--official-1","label":"tanstack.com/query/latest/docs/framework/react/guides/query-keys","url":"https://tanstack.com/query/latest/docs/framework/react/guides/query-keys","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."}],"retrieval":[{"id":"server-state-cache-lifecycle--r1--retrieval-1","kind":"retrieval","prompt":"Một ngày: component mount liên tục 10 phút, gcTime 5 phút. Cache có bắt buộc bị xóa không? Thêm một policy có thể làm network chạy và nêu UI.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism"],"afterDays":1,"rubric":[{"id":"server-state-cache-lifecycle--r1--retrieval-1--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Không bị thu gom chỉ vì qua 5 phút khi vẫn có observer. Polling hoặc focus với policy phù hợp có thể fetch; giữ data cũ và chỉ báo cập nhật nền nếu sản phẩm chấp nhận.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Không bị thu gom chỉ vì qua 5 phút khi vẫn có observer. Polling hoặc focus với policy phù hợp có thể fetch; giữ data cũ và chỉ báo cập nhật nền nếu sản phẩm chấp nhận.","sampleAnswer":"Không bị thu gom chỉ vì qua 5 phút khi vẫn có observer. Polling hoặc focus với policy phù hợp có thể fetch; giữ data cũ và chỉ báo cập nhật nền nếu sản phẩm chấp nhận.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"server-state-cache-lifecycle--r1--retrieval-2","kind":"retrieval","prompt":"Một tuần: hai widget cùng key nhưng ở hai QueryClient. Vì sao có hai request? Bạn sửa ở đâu và kiểm gì?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--application"],"afterDays":7,"rubric":[{"id":"server-state-cache-lifecycle--r1--retrieval-2--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Hai client là hai cache độc lập. Chia sẻ client ở phạm vi thích hợp, rồi kiểm request chồng nhau và key cùng tham số; không hứa mọi lần mount chỉ có một request.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Hai client là hai cache độc lập. Chia sẻ client ở phạm vi thích hợp, rồi kiểm request chồng nhau và key cùng tham số; không hứa mọi lần mount chỉ có một request.","sampleAnswer":"Hai client là hai cache độc lập. Chia sẻ client ở phạm vi thích hợp, rồi kiểm request chồng nhau và key cùng tham số; không hứa mọi lần mount chỉ có một request.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"server-state-cache-lifecycle--r1--retrieval-3","kind":"retrieval","prompt":"21 ngày: trang giá có cache fresh 60s, server đổi giá ngay sau fetch. Có dùng giá cache làm số tiền thanh toán không?","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"server-state-cache-lifecycle--r1--retrieval-3--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Không; fresh chỉ là policy của bản sao. Server tính/kiểm giá khi thanh toán và trả thay đổi cần xác nhận. Cache giúp hiển thị nhanh nhưng không giữ quyền quyết định nghiệp vụ.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Không; fresh chỉ là policy của bản sao. Server tính/kiểm giá khi thanh toán và trả thay đổi cần xác nhận. Cache giúp hiển thị nhanh nhưng không giữ quyền quyết định nghiệp vụ.","sampleAnswer":"Không; fresh chỉ là policy của bản sao. Server tính/kiểm giá khi thanh toán và trả thay đổi cần xác nhận. Cache giúp hiển thị nhanh nhưng không giữ quyền quyết định nghiệp vụ.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}}],"sections":[{"title":"Bối cảnh phỏng vấn","phase":"challenge","sortIndex":0,"body":"Trong phỏng vấn Frontend, interviewer đưa màn quản lý nhân viên: một bảng danh sách và một ô tổng số cùng đọc /users. Người dùng chuyển trang rồi quay lại sau 10 giây. “Có cần gọi API lại không?” Bạn đáp: “Nếu có cache thì không.” Interviewer đổi một chi tiết: “Sau 40 giây thì sao? Và nếu không còn component nào dùng cache trong 5 phút?”\n\nTrả lời câu hỏi bằng suy nghĩ hiện tại. Đây là lần chẩn đoán đầu vào, chưa tính đạt đầu ra. Bạn sẽ trả lời lại sau khi thực hành; bài vẫn mở nếu bạn chưa biết đáp án.","activities":[{"id":"server-state-cache-lifecycle--r1--opening-interview","kind":"explain","prompt":"Thiết kế cách chia sẻ dữ liệu cho hai component. Phân biệt trường hợp quay lại sau 10 giây, dữ liệu quá 30 giây và cache không được dùng trong 5 phút. Nêu điều kiện nào thực sự gửi request.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism","server-state-cache-lifecycle--r1--application","server-state-cache-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"server-state-cache-lifecycle--r1--opening-interview--criterion-0","criterion":"Hai đồng hồ","expectedEvidence":"Phân biệt thời điểm dữ liệu được cập nhật với thời điểm observer cuối rời đi.","misconception":"gcTime đếm từ lần fetch thành công.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--opening-interview--criterion-1","criterion":"Kích hoạt network","expectedEvidence":"Nêu trigger cụ thể, trạng thái fresh/stale và chính sách refetch.","misconception":"Hết staleTime tự gửi request.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--opening-interview--criterion-2","criterion":"Trải nghiệm và phạm vi","expectedEvidence":"Giữ dữ liệu cũ khi refetch phù hợp; query key gồm bộ lọc và phạm vi người dùng khi cần.","misconception":"Mọi danh sách dùng cùng key; refetch phải thay toàn bộ bằng skeleton.","maxScore":2}],"answer":{"explanation":"Hai component dùng cùng QueryClient và key biểu diễn cùng dữ liệu. Với staleTime 30 giây, dữ liệu 10 giây tuổi còn fresh nên mount mặc định dùng cache. Sau 30 giây dữ liệu stale nhưng chưa bị xóa; một trigger như mount/focus theo policy mới làm refetch nền. gcTime 5 phút tính khi query inactive, không tính từ lần fetch. Khi entry đã bị thu gom, mount tiếp theo cần tải đầu. Tôi giữ danh sách cũ khi background refetch và hiển thị trạng thái cập nhật riêng.","sampleAnswer":"Hai component dùng cùng QueryClient và key biểu diễn cùng dữ liệu. Với staleTime 30 giây, dữ liệu 10 giây tuổi còn fresh nên mount mặc định dùng cache. Sau 30 giây dữ liệu stale nhưng chưa bị xóa; một trigger như mount/focus theo policy mới làm refetch nền. gcTime 5 phút tính khi query inactive, không tính từ lần fetch. Khi entry đã bị thu gom, mount tiếp theo cần tải đầu. Tôi giữ danh sách cũ khi background refetch và hiển thị trạng thái cập nhật riêng.","misconception":"gcTime đếm từ lần fetch thành công.; Hết staleTime tự gửi request.; Mọi danh sách dùng cùng key; refetch phải thay toàn bộ bằng skeleton."}}],"id":"0-interview"},{"title":"Dự đoán trước khi quan sát","phase":"predict","sortIndex":1,"body":"Dữ liệu tải thành công ở t=0. Một component vẫn mount liên tục. staleTime=30s, gcTime=300s, không polling, không focus/reconnect, không invalidation. Đồng hồ vừa tới t=31s.","activities":[{"id":"server-state-cache-lifecycle--r1--predict-timer","kind":"choice","prompt":"Điều gì xảy ra tại t=31s?","stableKey":"predict-timer","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Muốn hiểu cache phải tách thay đổi trạng thái khỏi hành động network.","misconception":"Cache bị xóa và skeleton xuất hiện; Một request tự chạy vì staleTime là chu kỳ polling"},"options":[{"id":"server-state-cache-lifecycle--r1--predict-timer--option-1","label":"Cache bị xóa và skeleton xuất hiện","explanation":"Sai: gcTime không thu gom query còn đang được dùng.","isCorrect":false},{"id":"server-state-cache-lifecycle--r1--predict-timer--option-2","label":"Dữ liệu stale, vẫn còn trong cache; chỉ việc qua mốc không tạo request","explanation":"Đúng: độ mới thay đổi, chưa có trigger refetch.","isCorrect":true},{"id":"server-state-cache-lifecycle--r1--predict-timer--option-3","label":"Một request tự chạy vì staleTime là chu kỳ polling","explanation":"Sai: bạn đang nhầm staleTime với refetchInterval.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Thử và quan sát","phase":"explore","sortIndex":2,"body":"Hãy điều khiển một timeline nhỏ. Cho thời gian đi qua mốc 30 giây, rồi kích hoạt focus. Quan sát danh sách cũ có biến mất không. Sau đó cho component rời đi và để qua mốc thu gom. Bốn thao tác này tác động lên hai đồng hồ khác nhau.\n\n**Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.**\n\n```mermaid\nflowchart LR\n A[Component A] -->|observe same key| C[QueryClient cache]\n B[Component B] -->|observe same key| C\n C -->|snapshot and fetch status| A\n C -->|snapshot and fetch status| B\n T[Mount focus reconnect or manual] --> P{Refetch policy}\n P -->|fetch needed| N[Network request]\n N -->|success updates timestamp| C\n```\n\n> Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.","activities":[{"id":"server-state-cache-lifecycle--r1--exploration","kind":"simulation","prompt":"Thử đường sai trước, đọc trạng thái quan sát được, sau đó tìm đường giải quyết. Kết thúc bằng câu giải thích nguyên nhân.","stableKey":"exploration","outcomeIds":["server-state-cache-lifecycle--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"server-state-cache-lifecycle--r1--exploration--state-fresh","debriefQuestion":"Vì sao hai mốc 30s và 300s không cùng tính từ một thời điểm?","states":[{"id":"server-state-cache-lifecycle--r1--exploration--state-fresh","label":"t=0, fresh","observation":"Có danh sách; 1 observer; request đã hoàn tất.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-stale","label":"t=31, stale","observation":"Danh sách còn; không request mới chỉ vì đồng hồ chạy.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-fetching","label":"Focus ở t=31","observation":"Danh sách cũ còn; isFetching bật trong lần refetch nền.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-updated","label":"Response mới tại t=32","observation":"Cache thay dữ liệu; đồng hồ độ mới tính lại từ lần cập nhật này.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-inactive","label":"Observer cuối rời tại t=40","observation":"Cache còn và đồng hồ gc bắt đầu.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-collected","label":"Không dùng tới t=341","observation":"Entry đã thu gom; lần mount tiếp theo cần tải đầu.","isSuccess":true}],"actions":[{"id":"server-state-cache-lifecycle--r1--exploration--action-wait","label":"Đi tới t=31"},{"id":"server-state-cache-lifecycle--r1--exploration--action-focus","label":"Focus tab"},{"id":"server-state-cache-lifecycle--r1--exploration--action-resolve","label":"Nhận response"},{"id":"server-state-cache-lifecycle--r1--exploration--action-leave","label":"Unmount observer cuối"},{"id":"server-state-cache-lifecycle--r1--exploration--action-gc","label":"Chờ hơn 300s inactive"}],"transitions":[{"id":"server-state-cache-lifecycle--r1--exploration--transition-0","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-fresh","actionId":"server-state-cache-lifecycle--r1--exploration--action-wait","toStateId":"server-state-cache-lifecycle--r1--exploration--state-stale"},{"id":"server-state-cache-lifecycle--r1--exploration--transition-1","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-stale","actionId":"server-state-cache-lifecycle--r1--exploration--action-focus","toStateId":"server-state-cache-lifecycle--r1--exploration--state-fetching"},{"id":"server-state-cache-lifecycle--r1--exploration--transition-2","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-fetching","actionId":"server-state-cache-lifecycle--r1--exploration--action-resolve","toStateId":"server-state-cache-lifecycle--r1--exploration--state-updated"},{"id":"server-state-cache-lifecycle--r1--exploration--transition-3","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-updated","actionId":"server-state-cache-lifecycle--r1--exploration--action-leave","toStateId":"server-state-cache-lifecycle--r1--exploration--state-inactive"},{"id":"server-state-cache-lifecycle--r1--exploration--transition-4","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-inactive","actionId":"server-state-cache-lifecycle--r1--exploration--action-gc","toStateId":"server-state-cache-lifecycle--r1--exploration--state-collected"}]}}],"id":"2-experiment"},{"title":"Cache là một bản sao có địa chỉ","phase":"explain","sortIndex":3,"body":"Server giữ dữ liệu gốc; giao diện giữ một bản sao để hiển thị nhanh và tránh gọi lại không cần thiết. Khi bảng danh sách và ô tổng số cần cùng tập dữ liệu, chúng có thể quan sát một entry cache chung. Entry giống một ngăn có nhãn: query key xác định bạn đang hỏi dữ liệu nào. Component không sở hữu riêng ngăn đó; nó đăng ký để được báo khi nội dung ngăn thay đổi.\n\nNếu trang có bộ lọc status, trang số 2 hoặc tenant khác, những điều kiện làm thay đổi kết quả phải tham gia key. Ví dụ [\"users\", tenantId, {status, page}] phân biệt các truy vấn. Không dùng token bí mật làm key. Đổi account cần chính sách tách/xóa dữ liệu phù hợp; cùng một key thiếu phạm vi có thể hiển thị bản sao của account trước.\n\nChia sẻ entry không phải lời hứa “mãi mãi một request”. Những request đang bay có thể được dùng chung trong điều kiện phù hợp, nhưng mount sau khi dữ liệu stale, manual refetch hoặc hai QueryClient khác nhau vẫn có thể tạo request mới. Muốn kết luận dedup hãy kiểm cùng client, cùng key và thời điểm request chồng nhau.","id":"3-theory-1"},{"title":"Hai đồng hồ, hai câu hỏi","phase":"explain","sortIndex":4,"body":"**Trong bài: staleTime 30 giây, gcTime 5 phút; không bật polling.**\n\n| Cơ chế | Câu hỏi | Bắt đầu từ |\n| --- | --- | --- |\n| staleTime | Bản sao còn được coi là mới không? | Lần dữ liệu được cập nhật thành công |\n| gcTime | Ngăn không ai dùng đã nên thu gom chưa? | Khi query không còn observer |\n| refetchInterval | Có định kỳ đồng bộ lại không? | Lịch polling được cấu hình riêng |\n\nỞ t=0 dữ liệu mới về. Đến t=31, bản sao đã cũ theo policy nhưng vẫn có thể render. Nếu component còn mount, gcTime không phải đồng hồ xóa mỗi 5 phút. Khi observer cuối rời đi tại t=40, khoảng giữ entry inactive mới bắt đầu. Người dùng quay lại đủ sớm có thể thấy dữ liệu ngay; nếu dữ liệu stale thì mount mặc định có thể kích hoạt làm mới nền.\n\n“Cũ” ở đây là nhãn theo policy thời gian, không phải chứng minh server đã đổi. Ngược lại, dữ liệu fresh có thể khác server nếu server vừa đổi sau lần fetch. Bạn chọn staleTime theo độ chấp nhận trễ của sản phẩm, không coi nó là một bảo đảm nhất quán từ server.","id":"4-theory-2"},{"title":"Làm mới nền không phải tải đầu","phase":"explain","sortIndex":5,"body":"Tải đầu chưa có dữ liệu có thể cần skeleton. Khi làm mới nền, người dùng đang đọc một danh sách hợp lệ ở thời điểm trước; xóa nó để hiện skeleton khiến trang nhảy và mất ngữ cảnh. Cách phù hợp cho danh sách thông thường là giữ data, thêm chỉ báo cập nhật nhỏ và phân biệt lỗi tải đầu với lỗi refetch. Nếu refetch lỗi nhưng data cũ còn dùng được, có thể giữ data và báo chưa cập nhật được.\n\nQuyết định giữ bản sao cũ còn phụ thuộc rủi ro của hành động. Với số liệu tham khảo, dữ liệu hơi cũ có thể chấp nhận. Với xác nhận số tiền hoặc quyền thao tác, server vẫn phải kiểm tại lúc thực hiện. Một cờ fresh trên trình duyệt không thay thế kiểm tra nghiệp vụ ở server.\n\nTanStack Query v5 có policy refetch theo mount/focus/reconnect; cấu hình \"always\" khác true. Bài legacy cố tình dùng \"always\" để dễ thấy demo, nên việc vừa focus đã fetch không chứng minh dữ liệu đã stale. Khi điều tra hãy đọc option tại query, không chỉ default ở provider.","id":"5-theory-3"},{"title":"Đọc code bằng một câu hỏi mỗi hàm","phase":"explain","sortIndex":6,"body":"**source.ts chỉ mô hình hóa policy hai đồng hồ và focus; không mô phỏng retry, cancellation, static staleTime hay toàn bộ TanStack.**\n\n```typescript\n/** Mô hình hai đồng hồ cache, không thay TanStack Query. (EN: A two-clock teaching model.) */\ntype Cache = { updatedAt: number; inactiveAt: number | null };\n/** Tính tuổi dữ liệu riêng với tuổi không sử dụng. (EN: Separate data age from inactivity.) */\nexport function inspectCache(cache: Cache, now: number, staleMs: number, gcMs: number): {fresh: boolean; collected: boolean} {\n    const collected = cache.inactiveAt !== null && now - cache.inactiveAt >= gcMs;\n    return {fresh: !collected && now - cache.updatedAt < staleMs, collected};\n}\n/** Quyết định fetch với một trigger rõ ràng. (EN: Decide fetch for an explicit trigger.) */\nexport function shouldFetch(fresh: boolean, trigger: 'none' | 'focus' | 'manual', policy: boolean | 'always'): boolean {\n    if (trigger === 'none') return false;\n    if (trigger === 'manual') return true;\n    return policy === 'always' || (policy === true && !fresh);\n}\n```\n\ninspectCache trả hai kết quả độc lập: fresh và collected. shouldFetch cần trigger tường minh, vì trạng thái một mình chưa đủ tạo hành động. Mô hình bỏ qua concurrency của network để bạn tập trung vào hai quyết định. Khi gắn React thật, giữ QueryClient ổn định qua các render và đọc query status từ thư viện, không tự sao chép mô hình này làm cache production.","activities":[{"id":"server-state-cache-lifecycle--r1--quiz-focus","kind":"choice","prompt":"Cache mới 5 giây tuổi, staleTime=30s. Focus vẫn fetch. Chi tiết nào giải thích trực tiếp?","stableKey":"quiz-focus","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Luôn đọc trigger cùng policy.","misconception":"gcTime=5 phút; Component có chữ use client"},"options":[{"id":"server-state-cache-lifecycle--r1--quiz-focus--option-1","label":"gcTime=5 phút","explanation":"Sai: đó là thu gom cache inactive.","isCorrect":false},{"id":"server-state-cache-lifecycle--r1--quiz-focus--option-2","label":"refetchOnWindowFocus=\"always\"","explanation":"Đúng: policy này chủ động fetch trên focus với cấu hình bài học.","isCorrect":true},{"id":"server-state-cache-lifecycle--r1--quiz-focus--option-3","label":"Component có chữ use client","explanation":"Sai: directive không quyết định policy refetch.","isCorrect":false}]},{"id":"server-state-cache-lifecycle--r1--quiz-key","kind":"choice","prompt":"Danh sách active và archived dùng cùng [\"users\"] trong cùng client. Cần sửa gì?","stableKey":"quiz-key","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--application"],"placementSortIndex":1,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Key phải mô tả đầy đủ dữ liệu queryFn yêu cầu.","misconception":"Tăng staleTime; Thêm skeleton khác màu"},"options":[{"id":"server-state-cache-lifecycle--r1--quiz-key--option-1","label":"Tăng staleTime","explanation":"Sai: chỉ giữ sự nhầm lẫn lâu hơn.","isCorrect":false},{"id":"server-state-cache-lifecycle--r1--quiz-key--option-2","label":"Cho bộ lọc tham gia query key và đồng bộ queryFn với bộ lọc","explanation":"Đúng: hai câu hỏi dữ liệu cần hai địa chỉ cache.","isCorrect":true},{"id":"server-state-cache-lifecycle--r1--quiz-key--option-3","label":"Thêm skeleton khác màu","explanation":"Sai: hình thức hiển thị không sửa identity.","isCorrect":false}]}],"id":"6-theory-4"},{"title":"Thực hành có bằng chứng","phase":"apply","sortIndex":7,"body":"Chạy source.test.ts để kiểm timeline. Sau đó tự ghi timeline khác trước khi mở đáp án. Nếu kiểm trên app thật, dùng Network và Query Devtools, tắt polling và ghi lại policy focus để phép thử có ý nghĩa.\n\n**Windows PowerShell, Node.js 24.**\n\n```powershell\nnode --test source.test.ts\n```\n\n**macOS/Linux, Node.js 24.**\n\n```bash\nnode --test source.test.ts\n```\n\nBảng nộp có cột thời gian, số observer, tuổi dữ liệu, fresh/stale, trigger, có request hay không và UI. Không suy request đã xảy ra chỉ từ một spinner; đối chiếu Network hoặc log queryFn. Test mô hình không phải test React/TanStack integration.","activities":[{"id":"server-state-cache-lifecycle--r1--practice-timeline","kind":"exercise","prompt":"Dữ liệu về t=0, unmount t=20, mount t=50, staleTime=30s, gcTime=300s. Sau đó response về t=52 và unmount t=60; mount lại t=361. Nộp bảng timeline và giải thích khi nào dùng data cũ, khi nào tải đầu.","stableKey":"practice-timeline","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism","server-state-cache-lifecycle--r1--application","server-state-cache-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"server-state-cache-lifecycle--r1--practice-timeline--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"t=50 còn cache nhưng stale; mount theo policy có thể refetch nền.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--practice-timeline--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"gc tính từ unmount t=60; t=361 vượt 300 giây inactive nên tải đầu.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--practice-timeline--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Phân biệt UI giữ data cũ với skeleton tải đầu và nêu trigger cụ thể.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"t=50 còn cache vì mới inactive 30s; dữ liệu stale nên mount theo policy mặc định có thể refetch nền và vẫn hiện bản sao. Response tại 52 làm mới tuổi dữ liệu. Rời tại 60, tới 361 đã inactive 301s nên entry đã thu gom theo mô hình; mount cần tải đầu. Không tính gc từ t=52.","sampleAnswer":"t=50 còn cache vì mới inactive 30s; dữ liệu stale nên mount theo policy mặc định có thể refetch nền và vẫn hiện bản sao. Response tại 52 làm mới tuổi dữ liệu. Rời tại 60, tới 361 đã inactive 301s nên entry đã thu gom theo mô hình; mount cần tải đầu. Không tính gc từ t=52.","misconception":"gcTime đếm từ lần fetch thành công.; Hết staleTime tự gửi request.; Mọi danh sách dùng cùng key; refetch phải thay toàn bộ bằng skeleton."},"exercise":{"submissionInstructions":"Dữ liệu về t=0, unmount t=20, mount t=50, staleTime=30s, gcTime=300s. Sau đó response về t=52 và unmount t=60; mount lại t=361. Nộp bảng timeline và giải thích khi nào dùng data cũ, khi nào tải đầu.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production.","files":[{"relativePath":"source.ts","role":"reference","syntaxLanguage":"typescript","content":"/** Mô hình hai đồng hồ cache, không thay TanStack Query. (EN: A two-clock teaching model.) */\ntype Cache = { updatedAt: number; inactiveAt: number | null };\n/** Tính tuổi dữ liệu riêng với tuổi không sử dụng. (EN: Separate data age from inactivity.) */\nexport function inspectCache(cache: Cache, now: number, staleMs: number, gcMs: number): {fresh: boolean; collected: boolean} {\n    const collected = cache.inactiveAt !== null && now - cache.inactiveAt >= gcMs;\n    return {fresh: !collected && now - cache.updatedAt < staleMs, collected};\n}\n/** Quyết định fetch với một trigger rõ ràng. (EN: Decide fetch for an explicit trigger.) */\nexport function shouldFetch(fresh: boolean, trigger: 'none' | 'focus' | 'manual', policy: boolean | 'always'): boolean {\n    if (trigger === 'none') return false;\n    if (trigger === 'manual') return true;\n    return policy === 'always' || (policy === true && !fresh);\n}\n","sha256":"8428c8b81dcb3f055c73253640116d8029b32f7e05fd7338bf60a38e986370c5"},{"relativePath":"source.test.ts","role":"checks","syntaxLanguage":"typescript","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {inspectCache,shouldFetch} from './source.ts';\ntest('active data is stale but not collected', (): void => {assert.deepEqual(inspectCache({updatedAt:0,inactiveAt:null},600000,30000,300000),{fresh:false,collected:false});});\ntest('gc starts on inactivity', (): void => {assert.equal(inspectCache({updatedAt:52000,inactiveAt:60000},361000,30000,300000).collected,true);assert.equal(inspectCache({updatedAt:0,inactiveAt:20000},50000,30000,300000).collected,false);});\ntest('staleness without trigger does not fetch', (): void => {assert.equal(shouldFetch(false,'none',true),false);assert.equal(shouldFetch(false,'focus',true),true);assert.equal(shouldFetch(true,'focus',true),false);assert.equal(shouldFetch(true,'focus','always'),true);});\n","sha256":"2c8752dc90e2b35d79169a12611a45db2457f95ef509a332984b61f16651b72d"}],"checks":[{"id":"server-state-cache-lifecycle--r1--practice-timeline--node-tests","runner":"node-test","entrypoint":"source.test.ts","expectedExitCode":0,"scope":"educational-local-model","runtime":"Node.js 24","executionStatus":"passed"}]}}],"id":"7-practice"},{"title":"Tình huống mới","phase":"apply","sortIndex":8,"body":"Đóng lời giải trước khi làm. Nếu dùng gợi ý, hệ thống vẫn ghi nhận bài làm nhưng gắn nhãn có hỗ trợ.","activities":[{"id":"server-state-cache-lifecycle--r1--transfer-tenant","kind":"exercise","prompt":"Ứng dụng nhiều công ty: admin đổi từ công ty A sang B, mỗi công ty có active/archived và phân trang. Đề xuất query key, cách tránh chớp dữ liệu công ty cũ và UI khi background refetch lỗi.","stableKey":"transfer-tenant","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism","server-state-cache-lifecycle--r1--application","server-state-cache-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"server-state-cache-lifecycle--r1--transfer-tenant--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Key gồm tenantId, status, page và queryFn dùng cùng tham số.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--transfer-tenant--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Không dùng data/placeholder tenant cũ; kiểm quyền thật phía server.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--transfer-tenant--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Tách lỗi tải đầu khỏi refetch lỗi có data cũ, cho retry và thông báo phù hợp.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"Dùng key gồm users, tenantId, status và page; queryFn dùng đúng cùng tham số. Không tái dùng placeholder của tenant khác; xử lý cache lúc đổi tài khoản và kiểm quyền ở server. Với lỗi refetch trong cùng phạm vi có thể giữ data cũ, báo chưa cập nhật và cho thử lại; tải đầu thất bại cần trạng thái lỗi riêng.","sampleAnswer":"Dùng key gồm users, tenantId, status và page; queryFn dùng đúng cùng tham số. Không tái dùng placeholder của tenant khác; xử lý cache lúc đổi tài khoản và kiểm quyền ở server. Với lỗi refetch trong cùng phạm vi có thể giữ data cũ, báo chưa cập nhật và cho thử lại; tải đầu thất bại cần trạng thái lỗi riêng.","misconception":"gcTime đếm từ lần fetch thành công.; Hết staleTime tự gửi request.; Mọi danh sách dùng cùng key; refetch phải thay toàn bộ bằng skeleton."},"exercise":{"submissionInstructions":"Ứng dụng nhiều công ty: admin đổi từ công ty A sang B, mỗi công ty có active/archived và phân trang. Đề xuất query key, cách tránh chớp dữ liệu công ty cũ và UI khi background refetch lỗi.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production."}}],"id":"8-transfer"},{"title":"Phỏng vấn lại và tự giải thích","phase":"reflect","sortIndex":9,"body":"Đừng hỏi chỉ “có cache không”. Hãy hỏi bản sao thuộc query nào, mới tới đâu, ai đang dùng, và sự kiện nào yêu cầu đồng bộ. Bốn câu hỏi đó giải thích phần lớn những request tưởng là ngẫu nhiên.\n\nAI trả kết quả theo từng tiêu chí và trích đoạn bài nộp làm bằng chứng. Khi chấm chưa xong, trạng thái là đang chấm; bạn có thể tiếp tục đọc và quay lại. Điểm phỏng vấn không tăng chỉ vì câu trả lời dài.","activities":[{"id":"server-state-cache-lifecycle--r1--final-interview","kind":"explain","prompt":"Thiết kế cách chia sẻ dữ liệu cho hai component. Phân biệt trường hợp quay lại sau 10 giây, dữ liệu quá 30 giây và cache không được dùng trong 5 phút. Nêu điều kiện nào thực sự gửi request.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism","server-state-cache-lifecycle--r1--application","server-state-cache-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"server-state-cache-lifecycle--r1--final-interview--criterion-0","criterion":"Hai đồng hồ","expectedEvidence":"Phân biệt thời điểm dữ liệu được cập nhật với thời điểm observer cuối rời đi.","misconception":"gcTime đếm từ lần fetch thành công.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--final-interview--criterion-1","criterion":"Kích hoạt network","expectedEvidence":"Nêu trigger cụ thể, trạng thái fresh/stale và chính sách refetch.","misconception":"Hết staleTime tự gửi request.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--final-interview--criterion-2","criterion":"Trải nghiệm và phạm vi","expectedEvidence":"Giữ dữ liệu cũ khi refetch phù hợp; query key gồm bộ lọc và phạm vi người dùng khi cần.","misconception":"Mọi danh sách dùng cùng key; refetch phải thay toàn bộ bằng skeleton.","maxScore":2}],"answer":{"explanation":"Hai component dùng cùng QueryClient và key biểu diễn cùng dữ liệu. Với staleTime 30 giây, dữ liệu 10 giây tuổi còn fresh nên mount mặc định dùng cache. Sau 30 giây dữ liệu stale nhưng chưa bị xóa; một trigger như mount/focus theo policy mới làm refetch nền. gcTime 5 phút tính khi query inactive, không tính từ lần fetch. Khi entry đã bị thu gom, mount tiếp theo cần tải đầu. Tôi giữ danh sách cũ khi background refetch và hiển thị trạng thái cập nhật riêng.","sampleAnswer":"Hai component dùng cùng QueryClient và key biểu diễn cùng dữ liệu. Với staleTime 30 giây, dữ liệu 10 giây tuổi còn fresh nên mount mặc định dùng cache. Sau 30 giây dữ liệu stale nhưng chưa bị xóa; một trigger như mount/focus theo policy mới làm refetch nền. gcTime 5 phút tính khi query inactive, không tính từ lần fetch. Khi entry đã bị thu gom, mount tiếp theo cần tải đầu. Tôi giữ danh sách cũ khi background refetch và hiển thị trạng thái cập nhật riêng.","misconception":"gcTime đếm từ lần fetch thành công.; Hết staleTime tự gửi request.; Mọi danh sách dùng cùng key; refetch phải thay toàn bộ bằng skeleton."}}],"id":"9-reflection"}]},"en":{"title":"Server-state cache — old data does not automatically require a fetch","description":"The server-state cache lifecycle manages freshness, retention and synchronization of a server-data copy used by UI components.","body":"## Summary\n\nDo not ask only whether a cache exists. Ask which query owns the copy, how fresh it is, who is observing it, and which event requests synchronization. These four questions explain most apparently random requests.\n\n## Learning outcomes\n\n- Predict fresh, stale and collected states along a concrete timeline.\n- Choose keys, refetch policies and UI states for shared lists.\n- Explain why old cached data can remain useful and where deduplication stops.\n\n## Prerequisites\n\n- Read asynchronous TypeScript functions and React component state.\n- Understand HTTP requests that retrieve server data.\n\n## Included scope\n\n- Query keys and shared cache.\n- The staleTime and gcTime clocks, and refetch triggers.\n- Distinguish initial loading from background refresh and identify configuration errors.\n\n## Excluded scope\n\n- SSR hydration.\n- Optimistic mutations and offline persistence.\n- Server and CDN cache design.\n\n## Key claims\n\n- staleTime measures freshness; gcTime applies to queries without observers.\n- Becoming stale does not itself create a fetch interval.\n- Sharing a QueryClient and query key is fundamental to sharing cache entries.\n\n## Corrections\n\n- The legacy entry is labelled agnostic but its example depends on React and TanStack; this sample declares typescript.\n- The source uses refetchOnWindowFocus=\"always\"; do not infer that this is the default behavior.\n- Deduplication does not mean two components will only ever generate one request.\n- Casting JSON to User[] is not runtime validation; this sample does not teach casts as data validation.\n\n## References\n\n- [tanstack.com/query/latest/docs/framework/react/guides/important-defaults](https://tanstack.com/query/latest/docs/framework/react/guides/important-defaults)\n- [tanstack.com/query/latest/docs/framework/react/guides/query-keys](https://tanstack.com/query/latest/docs/framework/react/guides/query-keys)","learningOutcomes":[{"id":"server-state-cache-lifecycle--r1--mechanism","text":"Predict fresh, stale and collected states along a concrete timeline."},{"id":"server-state-cache-lifecycle--r1--application","text":"Choose keys, refetch policies and UI states for shared lists."},{"id":"server-state-cache-lifecycle--r1--tradeoffs","text":"Explain why old cached data can remain useful and where deduplication stops."}],"prerequisites":[{"id":"server-state-cache-lifecycle--r1--input-0","text":"Read asynchronous TypeScript functions and React component state."},{"id":"server-state-cache-lifecycle--r1--input-1","text":"Understand HTTP requests that retrieve server data."}],"references":[{"id":"server-state-cache-lifecycle--r1--legacy","label":"Pre-migration data source","citation":"legacy; courses/0-fullstack-mastery/modules/4-server-state-with-tanstack-query/contents/0-usequery-and-cache-lifecycle/bodies/0-agnostic/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 e8d0f7e10d37cdb29cfe256f3ecf4f62c7f32efd400f68fd3aca24ca2e536152; checked 2026-09-05; New V2 sample; V1 remains unchanged."},{"id":"server-state-cache-lifecycle--r1--official-0","label":"tanstack.com/query/latest/docs/framework/react/guides/important-defaults","url":"https://tanstack.com/query/latest/docs/framework/react/guides/important-defaults","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."},{"id":"server-state-cache-lifecycle--r1--official-1","label":"tanstack.com/query/latest/docs/framework/react/guides/query-keys","url":"https://tanstack.com/query/latest/docs/framework/react/guides/query-keys","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."}],"retrieval":[{"id":"server-state-cache-lifecycle--r1--retrieval-1","kind":"retrieval","prompt":"One day later: a component stays mounted for 10 minutes with gcTime of 5 minutes. Must its cache be deleted? Add a policy that can trigger network work and describe the UI.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism"],"afterDays":1,"rubric":[{"id":"server-state-cache-lifecycle--r1--retrieval-1--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"The entry is not collected simply because five minutes pass while an observer remains. Polling or focus with an appropriate policy can fetch. Retain old data and indicate background updating if the product allows it.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"The entry is not collected simply because five minutes pass while an observer remains. Polling or focus with an appropriate policy can fetch. Retain old data and indicate background updating if the product allows it.","sampleAnswer":"The entry is not collected simply because five minutes pass while an observer remains. Polling or focus with an appropriate policy can fetch. Retain old data and indicate background updating if the product allows it.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"server-state-cache-lifecycle--r1--retrieval-2","kind":"retrieval","prompt":"One week later: two widgets use the same key in different QueryClients. Why are there two requests? Where would you fix it and what would you verify?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--application"],"afterDays":7,"rubric":[{"id":"server-state-cache-lifecycle--r1--retrieval-2--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"Two clients have independent caches. Share a client at the appropriate scope, then verify overlapping requests and matching parameterized keys. Do not promise that all future mounts will generate only one request.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"Two clients have independent caches. Share a client at the appropriate scope, then verify overlapping requests and matching parameterized keys. Do not promise that all future mounts will generate only one request.","sampleAnswer":"Two clients have independent caches. Share a client at the appropriate scope, then verify overlapping requests and matching parameterized keys. Do not promise that all future mounts will generate only one request.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"server-state-cache-lifecycle--r1--retrieval-3","kind":"retrieval","prompt":"After 21 days: a price page considers its cache fresh for 60 seconds, but the server changes the price just after fetching. Should the cached price determine the payment amount?","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"server-state-cache-lifecycle--r1--retrieval-3--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"No. Freshness is a policy for the copy. The server calculates or validates the price at checkout and returns changes that need confirmation. The cache accelerates display but does not own the business decision.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"No. Freshness is a policy for the copy. The server calculates or validates the price at checkout and returns changes that need confirmation. The cache accelerates display but does not own the business decision.","sampleAnswer":"No. Freshness is a policy for the copy. The server calculates or validates the price at checkout and returns changes that need confirmation. The cache accelerates display but does not own the business decision.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}}],"sections":[{"title":"Interview context","phase":"challenge","sortIndex":0,"body":"In a frontend interview, a staff-management page has a list and a total-count widget both reading /users. The user leaves and returns ten seconds later. 'Should we call the API again?' You answer, 'Not if there is a cache.' The interviewer changes one detail: 'What about forty seconds later? What if no component uses the cache for five minutes?'\n\nAnswer using your current understanding. This initial diagnostic does not establish mastery. You will answer again after practice, and the lesson remains open if you do not yet know the answer.","activities":[{"id":"server-state-cache-lifecycle--r1--opening-interview","kind":"explain","prompt":"Design data sharing for two components. Distinguish returning after 10 seconds, data older than 30 seconds, and a cache unused for 5 minutes. State which conditions actually send requests.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism","server-state-cache-lifecycle--r1--application","server-state-cache-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"server-state-cache-lifecycle--r1--opening-interview--criterion-0","criterion":"Two clocks","expectedEvidence":"Distinguish the successful update time from the last observer's departure.","misconception":"gcTime starts at the last successful fetch.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--opening-interview--criterion-1","criterion":"Network triggers","expectedEvidence":"Name a concrete trigger, freshness state and refetch policy.","misconception":"Expiring staleTime sends a request automatically.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--opening-interview--criterion-2","criterion":"Experience and scope","expectedEvidence":"Retain old data when appropriate during refetch; include filters and user scope in keys where needed.","misconception":"Every list uses the same key and every refetch must replace it with a skeleton.","maxScore":2}],"answer":{"explanation":"Both components use the same QueryClient and a key representing the same data. With staleTime of 30 seconds, ten-second-old data is fresh, so the default mount behavior uses the cache. After 30 seconds the data is stale but not deleted; a policy-controlled trigger such as mount or focus can initiate background refetch. The five-minute gcTime starts when the query becomes inactive, not when data was fetched. After collection, a new mount requires initial loading. Keep the existing list visible during background refetch and show updating separately.","sampleAnswer":"Both components use the same QueryClient and a key representing the same data. With staleTime of 30 seconds, ten-second-old data is fresh, so the default mount behavior uses the cache. After 30 seconds the data is stale but not deleted; a policy-controlled trigger such as mount or focus can initiate background refetch. The five-minute gcTime starts when the query becomes inactive, not when data was fetched. After collection, a new mount requires initial loading. Keep the existing list visible during background refetch and show updating separately.","misconception":"gcTime starts at the last successful fetch.; Expiring staleTime sends a request automatically.; Every list uses the same key and every refetch must replace it with a skeleton."}}],"id":"0-interview"},{"title":"Predict before observing","phase":"predict","sortIndex":1,"body":"Data loads successfully at t=0. One component remains mounted. staleTime=30s, gcTime=300s, with no polling, focus, reconnection or invalidation. The clock has just reached t=31s.","activities":[{"id":"server-state-cache-lifecycle--r1--predict-timer","kind":"choice","prompt":"What happens at t=31s?","stableKey":"predict-timer","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Understanding cache requires separating state changes from network actions.","misconception":"The cache is deleted and a skeleton appears; A request starts automatically because staleTime is a polling interval"},"options":[{"id":"server-state-cache-lifecycle--r1--predict-timer--option-1","label":"The cache is deleted and a skeleton appears","explanation":"Incorrect: gcTime does not collect a query that is still being observed.","isCorrect":false},{"id":"server-state-cache-lifecycle--r1--predict-timer--option-2","label":"The data is stale and remains cached; crossing the threshold alone sends no request","explanation":"Correct: freshness changes, but no refetch trigger has occurred.","isCorrect":true},{"id":"server-state-cache-lifecycle--r1--predict-timer--option-3","label":"A request starts automatically because staleTime is a polling interval","explanation":"Incorrect: this confuses staleTime with refetchInterval.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Experiment and observe","phase":"explore","sortIndex":2,"body":"Control a small timeline: pass the 30-second threshold, then trigger focus. Observe whether the old list disappears. Next unmount the component and wait past collection. These actions affect two different clocks.\n\n**A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.**\n\n```mermaid\nflowchart LR\n A[Component A] -->|observe same key| C[QueryClient cache]\n B[Component B] -->|observe same key| C\n C -->|snapshot and fetch status| A\n C -->|snapshot and fetch status| B\n T[Mount focus reconnect or manual] --> P{Refetch policy}\n P -->|fetch needed| N[Network request]\n N -->|success updates timestamp| C\n```\n\n> A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.","activities":[{"id":"server-state-cache-lifecycle--r1--exploration","kind":"simulation","prompt":"Try an incorrect path first, read the observed state, then find a solution. Finish by explaining the cause.","stableKey":"exploration","outcomeIds":["server-state-cache-lifecycle--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"server-state-cache-lifecycle--r1--exploration--state-fresh","debriefQuestion":"Why do the 30-second and 300-second thresholds start at different times?","states":[{"id":"server-state-cache-lifecycle--r1--exploration--state-fresh","label":"t=0, fresh","observation":"The list is present; there is one observer and the request has completed.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-stale","label":"t=31, stale","observation":"The list remains; passage of time alone sends no new request.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-fetching","label":"Focus at t=31","observation":"The old list remains and isFetching is enabled during background refetch.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-updated","label":"New response at t=32","observation":"The cache replaces its data and freshness age restarts from this update.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-inactive","label":"The last observer leaves at t=40","observation":"The cache remains and the gc clock starts.","isSuccess":false},{"id":"server-state-cache-lifecycle--r1--exploration--state-collected","label":"Unused until t=341","observation":"The entry has been collected; the next mount requires initial loading.","isSuccess":true}],"actions":[{"id":"server-state-cache-lifecycle--r1--exploration--action-wait","label":"Advance to t=31"},{"id":"server-state-cache-lifecycle--r1--exploration--action-focus","label":"Focus tab"},{"id":"server-state-cache-lifecycle--r1--exploration--action-resolve","label":"Receive the response"},{"id":"server-state-cache-lifecycle--r1--exploration--action-leave","label":"Unmount the last observer"},{"id":"server-state-cache-lifecycle--r1--exploration--action-gc","label":"Wait more than 300 inactive seconds"}],"transitions":[{"id":"server-state-cache-lifecycle--r1--exploration--transition-0","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-fresh","actionId":"server-state-cache-lifecycle--r1--exploration--action-wait","toStateId":"server-state-cache-lifecycle--r1--exploration--state-stale"},{"id":"server-state-cache-lifecycle--r1--exploration--transition-1","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-stale","actionId":"server-state-cache-lifecycle--r1--exploration--action-focus","toStateId":"server-state-cache-lifecycle--r1--exploration--state-fetching"},{"id":"server-state-cache-lifecycle--r1--exploration--transition-2","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-fetching","actionId":"server-state-cache-lifecycle--r1--exploration--action-resolve","toStateId":"server-state-cache-lifecycle--r1--exploration--state-updated"},{"id":"server-state-cache-lifecycle--r1--exploration--transition-3","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-updated","actionId":"server-state-cache-lifecycle--r1--exploration--action-leave","toStateId":"server-state-cache-lifecycle--r1--exploration--state-inactive"},{"id":"server-state-cache-lifecycle--r1--exploration--transition-4","fromStateId":"server-state-cache-lifecycle--r1--exploration--state-inactive","actionId":"server-state-cache-lifecycle--r1--exploration--action-gc","toStateId":"server-state-cache-lifecycle--r1--exploration--state-collected"}]}}],"id":"2-experiment"},{"title":"A cache is a copy with an address","phase":"explain","sortIndex":3,"body":"The server owns the original data; the UI retains a copy for fast display and fewer unnecessary calls. If the list and count widget need the same dataset, both can observe one cache entry. Think of it as a labeled compartment: the query key identifies the data question. A component does not exclusively own that compartment; it subscribes to changes.\n\nAny condition that changes the result, such as status, page or tenant, belongs in the key. For example, [\"users\", tenantId, {status, page}] distinguishes queries. Do not put secret tokens in keys. Account switching needs an appropriate separation or clearing policy: a key missing scope can display the previous account's copy.\n\nSharing an entry does not promise 'one request forever.' In-flight requests can be shared under suitable conditions, but mounting stale data, manual refetching or using separate QueryClients can create new requests. To establish deduplication, verify the same client, the same key and overlapping request timing.","id":"3-theory-1"},{"title":"Two clocks, two questions","phase":"explain","sortIndex":4,"body":"**This lesson uses staleTime of 30 seconds and gcTime of 5 minutes, with polling disabled.**\n\n| Mechanism | Question | Starting point |\n| --- | --- | --- |\n| staleTime | Is the copy still considered fresh? | The last successful data update |\n| gcTime | Should an unused entry be collected yet? | When the query loses its last observer |\n| refetchInterval | Should synchronization run periodically? | A separately configured polling schedule |\n\nData arrives at t=0. At t=31 it is old under the policy but still renderable. While the component remains mounted, gcTime is not a recurring five-minute deletion timer. The inactive retention period begins when the last observer leaves at t=40. Returning soon enough allows immediate display; if the data is stale, the default mount policy can trigger background refresh.\n\n'Stale' is a time-policy label, not proof that the server changed. Conversely, fresh data may differ from the server if the server changed after fetching. Choose staleTime according to the product's tolerance for delay; it is not a server consistency guarantee.","id":"4-theory-2"},{"title":"Background refresh is not initial loading","phase":"explain","sortIndex":5,"body":"An initial load without data may need a skeleton. During background refresh, the user is already reading a previously valid list; deleting it for a skeleton causes layout movement and lost context. An ordinary list can retain data, add a small updating indicator and distinguish initial-load failures from refetch errors. If old data remains useful after a failed refresh, keep it and explain that updating failed.\n\nWhether retaining old data is acceptable depends on the action's risk. Slightly old reference information may be fine. Confirming payment amounts or permissions still requires server checks at execution time. A browser freshness flag does not replace server business validation.\n\nTanStack Query v5 has mount, focus and reconnect refetch policies; \"always\" differs from true. The legacy demo intentionally uses \"always\", so a focus-triggered request does not prove that data is stale. Inspect the query's options as well as provider defaults.","id":"5-theory-3"},{"title":"Read each function with one question in mind","phase":"explain","sortIndex":6,"body":"**source.ts models only the two-clock policy and focus. It does not implement retries, cancellation, static staleTime or all of TanStack Query.**\n\n```typescript\n/** Mô hình hai đồng hồ cache, không thay TanStack Query. (EN: A two-clock teaching model.) */\ntype Cache = { updatedAt: number; inactiveAt: number | null };\n/** Tính tuổi dữ liệu riêng với tuổi không sử dụng. (EN: Separate data age from inactivity.) */\nexport function inspectCache(cache: Cache, now: number, staleMs: number, gcMs: number): {fresh: boolean; collected: boolean} {\n    const collected = cache.inactiveAt !== null && now - cache.inactiveAt >= gcMs;\n    return {fresh: !collected && now - cache.updatedAt < staleMs, collected};\n}\n/** Quyết định fetch với một trigger rõ ràng. (EN: Decide fetch for an explicit trigger.) */\nexport function shouldFetch(fresh: boolean, trigger: 'none' | 'focus' | 'manual', policy: boolean | 'always'): boolean {\n    if (trigger === 'none') return false;\n    if (trigger === 'manual') return true;\n    return policy === 'always' || (policy === true && !fresh);\n}\n```\n\ninspectCache returns two independent results: fresh and collected. shouldFetch requires an explicit trigger because state alone does not create an action. The model omits network concurrency to isolate these decisions. In real React integration, keep QueryClient stable across renders and use library query status; do not copy this teaching model into a production cache.","activities":[{"id":"server-state-cache-lifecycle--r1--quiz-focus","kind":"choice","prompt":"The cache is only 5 seconds old and staleTime=30s, yet focus fetches. Which detail directly explains it?","stableKey":"quiz-focus","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Always read a trigger together with its policy.","misconception":"gcTime=5 minutes; The component contains use client"},"options":[{"id":"server-state-cache-lifecycle--r1--quiz-focus--option-1","label":"gcTime=5 minutes","explanation":"Incorrect: that controls collection of inactive cache entries.","isCorrect":false},{"id":"server-state-cache-lifecycle--r1--quiz-focus--option-2","label":"refetchOnWindowFocus=\"always\"","explanation":"Correct: in the lesson's configuration this policy explicitly fetches on focus.","isCorrect":true},{"id":"server-state-cache-lifecycle--r1--quiz-focus--option-3","label":"The component contains use client","explanation":"Incorrect: that directive does not determine the refetch policy.","isCorrect":false}]},{"id":"server-state-cache-lifecycle--r1--quiz-key","kind":"choice","prompt":"Active and archived lists share [\"users\"] in the same client. What needs to change?","stableKey":"quiz-key","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--application"],"placementSortIndex":1,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"The key must fully describe the data requested by queryFn.","misconception":"Increase staleTime; Add a differently colored skeleton"},"options":[{"id":"server-state-cache-lifecycle--r1--quiz-key--option-1","label":"Increase staleTime","explanation":"Incorrect: it merely preserves the identity mistake longer.","isCorrect":false},{"id":"server-state-cache-lifecycle--r1--quiz-key--option-2","label":"Include the filter in the query key and use the same filter in queryFn","explanation":"Correct: two different data questions need two cache addresses.","isCorrect":true},{"id":"server-state-cache-lifecycle--r1--quiz-key--option-3","label":"Add a differently colored skeleton","explanation":"Incorrect: changing presentation does not fix identity.","isCorrect":false}]}],"id":"6-theory-4"},{"title":"Practice with evidence","phase":"apply","sortIndex":7,"body":"Run source.test.ts to check the timeline, then write a different timeline before opening the answer. In a real app, use Network and Query Devtools, disable polling and record focus policies so the experiment is interpretable.\n\n**Windows PowerShell, Node.js 24.**\n\n```powershell\nnode --test source.test.ts\n```\n\n**macOS/Linux, Node.js 24.**\n\n```bash\nnode --test source.test.ts\n```\n\nSubmit columns for time, observer count, data age, fresh/stale state, trigger, whether a request occurs and UI behavior. A spinner alone does not prove a request happened: inspect Network or queryFn logs. Model tests are not React/TanStack integration tests.","activities":[{"id":"server-state-cache-lifecycle--r1--practice-timeline","kind":"exercise","prompt":"Data arrives at t=0, unmount occurs at t=20 and mount at t=50; staleTime=30s and gcTime=300s. A response then arrives at t=52, followed by unmount at t=60 and mount at t=361. Submit a timeline explaining when old data is reused and when an initial load is needed.","stableKey":"practice-timeline","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism","server-state-cache-lifecycle--r1--application","server-state-cache-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"server-state-cache-lifecycle--r1--practice-timeline--criterion-0","criterion":"Requested result","expectedEvidence":"At t=50 data remains cached but is stale; the mount policy may trigger background refetch.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--practice-timeline--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"gcTime starts at unmount t=60; at t=361 inactivity exceeds 300 seconds, requiring initial loading.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--practice-timeline--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Distinguish retaining old data from an initial-load skeleton and name the specific trigger.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"At t=50 the cache remains because it has been inactive for only 30 seconds. Its data is stale, so the default mount policy can refetch in the background while displaying the copy. The response at t=52 resets data age. After unmount at t=60, t=361 represents 301 inactive seconds: the model has collected the entry and mounting requires initial loading. Do not count gcTime from t=52.","sampleAnswer":"At t=50 the cache remains because it has been inactive for only 30 seconds. Its data is stale, so the default mount policy can refetch in the background while displaying the copy. The response at t=52 resets data age. After unmount at t=60, t=361 represents 301 inactive seconds: the model has collected the entry and mounting requires initial loading. Do not count gcTime from t=52.","misconception":"gcTime starts at the last successful fetch.; Expiring staleTime sends a request automatically.; Every list uses the same key and every refetch must replace it with a skeleton."},"exercise":{"submissionInstructions":"Data arrives at t=0, unmount occurs at t=20 and mount at t=50; staleTime=30s and gcTime=300s. A response then arrives at t=52, followed by unmount at t=60 and mount at t=361. Submit a timeline explaining when old data is reused and when an initial load is needed.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works.","files":[{"relativePath":"source.ts","role":"reference","syntaxLanguage":"typescript","content":"/** Mô hình hai đồng hồ cache, không thay TanStack Query. (EN: A two-clock teaching model.) */\ntype Cache = { updatedAt: number; inactiveAt: number | null };\n/** Tính tuổi dữ liệu riêng với tuổi không sử dụng. (EN: Separate data age from inactivity.) */\nexport function inspectCache(cache: Cache, now: number, staleMs: number, gcMs: number): {fresh: boolean; collected: boolean} {\n    const collected = cache.inactiveAt !== null && now - cache.inactiveAt >= gcMs;\n    return {fresh: !collected && now - cache.updatedAt < staleMs, collected};\n}\n/** Quyết định fetch với một trigger rõ ràng. (EN: Decide fetch for an explicit trigger.) */\nexport function shouldFetch(fresh: boolean, trigger: 'none' | 'focus' | 'manual', policy: boolean | 'always'): boolean {\n    if (trigger === 'none') return false;\n    if (trigger === 'manual') return true;\n    return policy === 'always' || (policy === true && !fresh);\n}\n","sha256":"8428c8b81dcb3f055c73253640116d8029b32f7e05fd7338bf60a38e986370c5"},{"relativePath":"source.test.ts","role":"checks","syntaxLanguage":"typescript","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {inspectCache,shouldFetch} from './source.ts';\ntest('active data is stale but not collected', (): void => {assert.deepEqual(inspectCache({updatedAt:0,inactiveAt:null},600000,30000,300000),{fresh:false,collected:false});});\ntest('gc starts on inactivity', (): void => {assert.equal(inspectCache({updatedAt:52000,inactiveAt:60000},361000,30000,300000).collected,true);assert.equal(inspectCache({updatedAt:0,inactiveAt:20000},50000,30000,300000).collected,false);});\ntest('staleness without trigger does not fetch', (): void => {assert.equal(shouldFetch(false,'none',true),false);assert.equal(shouldFetch(false,'focus',true),true);assert.equal(shouldFetch(true,'focus',true),false);assert.equal(shouldFetch(true,'focus','always'),true);});\n","sha256":"2c8752dc90e2b35d79169a12611a45db2457f95ef509a332984b61f16651b72d"}],"checks":[{"id":"server-state-cache-lifecycle--r1--practice-timeline--node-tests","runner":"node-test","entrypoint":"source.test.ts","expectedExitCode":0,"scope":"educational-local-model","runtime":"Node.js 24","executionStatus":"passed"}]}}],"id":"7-practice"},{"title":"A new situation","phase":"apply","sortIndex":8,"body":"Close the solution before starting. If you use hints, the system should still record your attempt and label it as assisted.","activities":[{"id":"server-state-cache-lifecycle--r1--transfer-tenant","kind":"exercise","prompt":"In a multi-company application, an administrator switches from company A to B. Each company has active and archived lists with pagination. Propose query keys, a way to prevent flashing the previous company's data, and UI behavior when background refetch fails.","stableKey":"transfer-tenant","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism","server-state-cache-lifecycle--r1--application","server-state-cache-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"server-state-cache-lifecycle--r1--transfer-tenant--criterion-0","criterion":"Requested result","expectedEvidence":"The key includes tenantId, status and page, and queryFn uses the same parameters.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--transfer-tenant--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Do not use the previous tenant's data or placeholder; enforce real authorization on the server.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--transfer-tenant--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Separate initial-load failure from a refetch error with old data; provide suitable messaging and retry.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"Include users, tenantId, status and page in the key, and use those same parameters in queryFn. Do not reuse another tenant's placeholder data. Define account-switch cache handling and enforce authorization on the server. Within the same scope, a failed refetch may retain usable old data, indicate that updating failed and offer retry; an initial-load failure needs a separate error state.","sampleAnswer":"Include users, tenantId, status and page in the key, and use those same parameters in queryFn. Do not reuse another tenant's placeholder data. Define account-switch cache handling and enforce authorization on the server. Within the same scope, a failed refetch may retain usable old data, indicate that updating failed and offer retry; an initial-load failure needs a separate error state.","misconception":"gcTime starts at the last successful fetch.; Expiring staleTime sends a request automatically.; Every list uses the same key and every refetch must replace it with a skeleton."},"exercise":{"submissionInstructions":"In a multi-company application, an administrator switches from company A to B. Each company has active and archived lists with pagination. Propose query keys, a way to prevent flashing the previous company's data, and UI behavior when background refetch fails.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works."}}],"id":"8-transfer"},{"title":"Interview again and explain your reasoning","phase":"reflect","sortIndex":9,"body":"Do not ask only whether a cache exists. Ask which query owns the copy, how fresh it is, who is observing it, and which event requests synchronization. These four questions explain most apparently random requests.\n\nAI should return criterion-level results and quote evidence from your submission. While grading is pending, the state remains pending; you can continue reading and return later. Interview scores do not increase merely because an answer is longer.","activities":[{"id":"server-state-cache-lifecycle--r1--final-interview","kind":"explain","prompt":"Design data sharing for two components. Distinguish returning after 10 seconds, data older than 30 seconds, and a cache unused for 5 minutes. State which conditions actually send requests.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["server-state-cache-lifecycle--r1--mechanism","server-state-cache-lifecycle--r1--application","server-state-cache-lifecycle--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"server-state-cache-lifecycle--r1--final-interview--criterion-0","criterion":"Two clocks","expectedEvidence":"Distinguish the successful update time from the last observer's departure.","misconception":"gcTime starts at the last successful fetch.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--final-interview--criterion-1","criterion":"Network triggers","expectedEvidence":"Name a concrete trigger, freshness state and refetch policy.","misconception":"Expiring staleTime sends a request automatically.","maxScore":2},{"id":"server-state-cache-lifecycle--r1--final-interview--criterion-2","criterion":"Experience and scope","expectedEvidence":"Retain old data when appropriate during refetch; include filters and user scope in keys where needed.","misconception":"Every list uses the same key and every refetch must replace it with a skeleton.","maxScore":2}],"answer":{"explanation":"Both components use the same QueryClient and a key representing the same data. With staleTime of 30 seconds, ten-second-old data is fresh, so the default mount behavior uses the cache. After 30 seconds the data is stale but not deleted; a policy-controlled trigger such as mount or focus can initiate background refetch. The five-minute gcTime starts when the query becomes inactive, not when data was fetched. After collection, a new mount requires initial loading. Keep the existing list visible during background refetch and show updating separately.","sampleAnswer":"Both components use the same QueryClient and a key representing the same data. With staleTime of 30 seconds, ten-second-old data is fresh, so the default mount behavior uses the cache. After 30 seconds the data is stale but not deleted; a policy-controlled trigger such as mount or focus can initiate background refetch. The five-minute gcTime starts when the query becomes inactive, not when data was fetched. After collection, a new mount requires initial loading. Keep the existing list visible during background refetch and show updating separately.","misconception":"gcTime starts at the last successful fetch.; Expiring staleTime sends a request automatically.; Every list uses the same key and every refetch must replace it with a skeleton."}}],"id":"9-reflection"}]}},"workspace":{"runtime":"Node.js 24","files":[{"path":"workspace/source.test.ts","role":"test"},{"path":"workspace/source.ts","role":"source"}],"commands":{"windows":"node --test workspace/source.test.ts","unix":"node --test workspace/source.test.ts"}},"files":[{"path":"workspace/source.test.ts","role":"test","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {inspectCache,shouldFetch} from './source.ts';\ntest('active data is stale but not collected', (): void => {assert.deepEqual(inspectCache({updatedAt:0,inactiveAt:null},600000,30000,300000),{fresh:false,collected:false});});\ntest('gc starts on inactivity', (): void => {assert.equal(inspectCache({updatedAt:52000,inactiveAt:60000},361000,30000,300000).collected,true);assert.equal(inspectCache({updatedAt:0,inactiveAt:20000},50000,30000,300000).collected,false);});\ntest('staleness without trigger does not fetch', (): void => {assert.equal(shouldFetch(false,'none',true),false);assert.equal(shouldFetch(false,'focus',true),true);assert.equal(shouldFetch(true,'focus',true),false);assert.equal(shouldFetch(true,'focus','always'),true);});\n"},{"path":"workspace/source.ts","role":"source","content":"/** Mô hình hai đồng hồ cache, không thay TanStack Query. (EN: A two-clock teaching model.) */\ntype Cache = { updatedAt: number; inactiveAt: number | null };\n/** Tính tuổi dữ liệu riêng với tuổi không sử dụng. (EN: Separate data age from inactivity.) */\nexport function inspectCache(cache: Cache, now: number, staleMs: number, gcMs: number): {fresh: boolean; collected: boolean} {\n    const collected = cache.inactiveAt !== null && now - cache.inactiveAt >= gcMs;\n    return {fresh: !collected && now - cache.updatedAt < staleMs, collected};\n}\n/** Quyết định fetch với một trigger rõ ràng. (EN: Decide fetch for an explicit trigger.) */\nexport function shouldFetch(fresh: boolean, trigger: 'none' | 'focus' | 'manual', policy: boolean | 'always'): boolean {\n    if (trigger === 'none') return false;\n    if (trigger === 'manual') return true;\n    return policy === 'always' || (policy === true && !fresh);\n}\n"}]}$lesson$::jsonb,
    '2026-11-08T00:00:00Z'
