e6","sections/9-transfer/en.md":"f99e0e8bc93e9e9a7aa1f517eb0d5d4df0d8d8cd043673039d502eec34fc2159","sections/9-transfer/vi.md":"4be59c30137b023be4a3556e531b72205651adaa19e32b612020a3b25048319b","vi.md":"63b360458da93a91c5b5a13ee7827caea230943c8a3c0129312bc41dea8b5dd7","workspace/source.test.ts":"848304cf625b56f175f1d9fb0a66f71724b9b0ae2ab6a3b9be4f7167689162d7","workspace/source.ts":"5434fed6607928548869ee7f088eae942d72012640b827e449609b6082d14eb3"}$lesson$::jsonb,
    $lesson${"locales":{"vi":{"title":"CQRS — tách việc ghi và cách nhìn dữ liệu","description":"CQRS tách mô hình xử lý thay đổi khỏi mô hình phục vụ truy vấn để mỗi bên diễn đạt đúng trách nhiệm và nhu cầu của mình.","body":"## Tóm tắt\n\nCQRS giúp bạn chọn mô hình đúng cho một trách nhiệm. Đổi lại, khi tách store bằng bất đồng bộ, bạn phải giải thích được mỗi khoảng cách giữa ghi và đọc, cả lúc bình thường lẫn lúc một bước thất bại.\n\n## Kết quả học tập\n\n- Giải thích từ command tới projection và dự đoán thời điểm read model còn cũ.\n- Sửa projection nhận snapshot trùng hoặc sai thứ tự và đưa ra phép kiểm.\n- Chọn CQRS có điều kiện, nêu chi phí đồng bộ và phương án rebuild có nguồn thật.\n\n## Kiến thức đầu vào\n\n- Biết transaction database và HTTP API.\n- Đọc được TypeScript; biết queue chuyển message tới consumer.\n\n## Phạm vi bao gồm\n\n- Tách command/query và read model.\n- Eventual consistency, read-your-writes.\n- Dual write, outbox, ack, duplicate, ordering và rebuild trong phạm vi CQRS.\n\n## Phạm vi không bao gồm\n\n- Triển khai Event Sourcing đầy đủ.\n- Cài cluster broker/Elasticsearch production.\n- Bảo đảm exactly-once toàn hệ thống.\n\n## Luận điểm chính\n\n- CQRS không bắt buộc hai database, broker hay Event Sourcing.\n- Projection bất đồng bộ có thể chậm hơn write model.\n- Idempotency theo id không ngăn snapshot cũ ghi đè snapshot mới.\n\n## Điều chỉnh nhận thức\n\n- Sửa khẳng định legacy rằng bản chất CQRS là bắt buộc chấp nhận hai store lệch nhau: đó là biến thể async của bài.\n- Không coi save rồi publish là transaction nguyên tử; await EventBus không tự tạo bảo đảm bền vững.\n- Không coi RabbitMQ đã ack là kho lịch sử replay.\n- Không coi upsert theo id đủ chống sai thứ tự; version check cần nguyên tử khi có nhiều consumer.\n- Không khẳng định Postgres không làm tốt full-text; phải đo query/index trước khi tách store.\n\n## Tham khảo\n\n- [learn.microsoft.com/en-us/azure/architecture/patterns/cqrs](https://learn.microsoft.com/en-us/azure/architecture/patterns/cqrs)\n- [www.rabbitmq.com/docs/confirms](https://www.rabbitmq.com/docs/confirms)","learningOutcomes":[{"id":"cqrs-read-models--r1--mechanism","text":"Giải thích từ command tới projection và dự đoán thời điểm read model còn cũ."},{"id":"cqrs-read-models--r1--application","text":"Sửa projection nhận snapshot trùng hoặc sai thứ tự và đưa ra phép kiểm."},{"id":"cqrs-read-models--r1--tradeoffs","text":"Chọn CQRS có điều kiện, nêu chi phí đồng bộ và phương án rebuild có nguồn thật."}],"prerequisites":[{"id":"cqrs-read-models--r1--input-0","text":"Biết transaction database và HTTP API."},{"id":"cqrs-read-models--r1--input-1","text":"Đọc được TypeScript; biết queue chuyển message tới consumer."}],"references":[{"id":"cqrs-read-models--r1--legacy","label":"Nguồn dữ liệu trước migration","citation":"legacy; courses/1-system-design-mastery/modules/3-communication-patterns/contents/6-cqrs-and-read-models/bodies/0-typescript/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 34f20e4d0f72f02d4dcf3a4c48d722291b5fa3da483cd086e623f8226ce299e2; checked 2026-09-05; Bài mẫu V2 mới; không sửa V1."},{"id":"cqrs-read-models--r1--official-0","label":"learn.microsoft.com/en-us/azure/architecture/patterns/cqrs","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/cqrs","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."},{"id":"cqrs-read-models--r1--official-1","label":"www.rabbitmq.com/docs/confirms","url":"https://www.rabbitmq.com/docs/confirms","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."}],"retrieval":[{"id":"cqrs-read-models--r1--retrieval-1","kind":"retrieval","prompt":"Một ngày: POST thành công, queue rỗng, GET vẫn cũ. Nêu hai nguyên nhân khác nhau và bằng chứng cần phân biệt.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism"],"afterDays":1,"rubric":[{"id":"cqrs-read-models--r1--retrieval-1--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Có thể publish chưa thành công nên queue chưa từng nhận, hoặc consumer ack sai/trước project, hoặc query nhìn store/index khác. Kiểm outbox/producer confirm, consumer logs, version và query target; queue rỗng không chứng minh đồng bộ.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Có thể publish chưa thành công nên queue chưa từng nhận, hoặc consumer ack sai/trước project, hoặc query nhìn store/index khác. Kiểm outbox/producer confirm, consumer logs, version và query target; queue rỗng không chứng minh đồng bộ.","sampleAnswer":"Có thể publish chưa thành công nên queue chưa từng nhận, hoặc consumer ack sai/trước project, hoặc query nhìn store/index khác. Kiểm outbox/producer confirm, consumer logs, version và query target; queue rỗng không chứng minh đồng bộ.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"cqrs-read-models--r1--retrieval-2","kind":"retrieval","prompt":"Một tuần: đội muốn đổi tất cả CRUD sang CQRS hai store. Bạn yêu cầu bằng chứng nào trước và thiết kế tối thiểu nào có thể đủ?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--application"],"afterDays":7,"rubric":[{"id":"cqrs-read-models--r1--retrieval-2--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Đo bottleneck query và nhu cầu mô hình/scale; thử query/index hợp lý. Có thể tách command/query trong cùng app/database. Chỉ thêm async projection khi lợi ích vượt chi phí consistency, vận hành và rebuild.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Đo bottleneck query và nhu cầu mô hình/scale; thử query/index hợp lý. Có thể tách command/query trong cùng app/database. Chỉ thêm async projection khi lợi ích vượt chi phí consistency, vận hành và rebuild.","sampleAnswer":"Đo bottleneck query và nhu cầu mô hình/scale; thử query/index hợp lý. Có thể tách command/query trong cùng app/database. Chỉ thêm async projection khi lợi ích vượt chi phí consistency, vận hành và rebuild.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"cqrs-read-models--r1--retrieval-3","kind":"retrieval","prompt":"21 ngày: cần biểu đồ lịch sử giá nhưng chỉ giữ giá hiện tại và queue đã ack. Rebuild có tạo lại lịch sử không? Thiết kế hướng bổ sung.","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"cqrs-read-models--r1--retrieval-3--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Không thể suy lịch sử đã mất từ giá hiện tại. Cần nguồn lịch sử được lưu bền từ thời điểm thu thập, hoặc import archive có thật. CQRS không tự cung cấp Event Sourcing; công bố giới hạn dữ liệu lịch sử trước khi dựng projection.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Không thể suy lịch sử đã mất từ giá hiện tại. Cần nguồn lịch sử được lưu bền từ thời điểm thu thập, hoặc import archive có thật. CQRS không tự cung cấp Event Sourcing; công bố giới hạn dữ liệu lịch sử trước khi dựng projection.","sampleAnswer":"Không thể suy lịch sử đã mất từ giá hiện tại. Cần nguồn lịch sử được lưu bền từ thời điểm thu thập, hoặc import archive có thật. CQRS không tự cung cấp Event Sourcing; công bố giới hạn dữ liệu lịch sử trước khi dựng projection.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}}],"sections":[{"title":"Bối cảnh phỏng vấn","phase":"challenge","sortIndex":0,"body":"Trong phỏng vấn System Design, interviewer mô tả một ứng dụng: người dùng đổi tên thành “An Nguyễn”, API trả thành công, nhưng trang tìm kiếm vẫn hiện “An”. “Có phải ghi thất bại không?” Bạn đáp: “Chắc cache chưa xóa.” Interviewer mở sơ đồ: đường ghi dùng PostgreSQL, trang tìm kiếm đọc Elasticsearch, ở giữa là RabbitMQ. Bây giờ bạn cần giải thích hệ thống nào đã biết tên mới, hệ thống nào chưa biết, và làm sao nó bắt kịp.\n\nTrả lời câu hỏi bằng suy nghĩ hiện tại. Đây là lần chẩn đoán đầu vào, chưa tính đạt đầu ra. Bạn sẽ trả lời lại sau khi thực hành; bài vẫn mở nếu bạn chưa biết đáp án.","activities":[{"id":"cqrs-read-models--r1--opening-interview","kind":"explain","prompt":"Thiết kế đường ghi hồ sơ và đường đọc tìm kiếm. Vì sao tên cũ có thể xuất hiện sau khi ghi thành công? Hãy chỉ ra một lỗi làm read model không bao giờ bắt kịp nếu không có cơ chế sửa.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism","cqrs-read-models--r1--application","cqrs-read-models--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"cqrs-read-models--r1--opening-interview--criterion-0","criterion":"Trách nhiệm và trade-off","expectedEvidence":"Phân biệt command/query; chọn tách vì nhu cầu cụ thể, không vì số database.","misconception":"Có hai database tức là CQRS; mọi CRUD đều cần broker.","maxScore":2},{"id":"cqrs-read-models--r1--opening-interview--criterion-1","criterion":"Đường đồng bộ","expectedEvidence":"Kể commit, chuyển event, project và đọc; chỉ ra cửa sổ mất event hoặc đọc cũ.","misconception":"HTTP thành công đồng nghĩa projection đã cập nhật.","maxScore":2},{"id":"cqrs-read-models--r1--opening-interview--criterion-2","criterion":"Độ tin cậy và giới hạn","expectedEvidence":"Phân biệt duplicate với stale event; nêu version check nguyên tử, nguồn rebuild và phạm vi bằng chứng.","misconception":"Upsert theo id xử lý được mọi sai thứ tự; queue đã ack là event archive.","maxScore":2}],"answer":{"explanation":"Command kiểm invariant và lưu trạng thái ở write model; query dùng một read model tối ưu cho tìm kiếm. Với đồng bộ async, commit có thể xong trước khi consumer cập nhật read model, nên đọc cũ không tự chứng minh ghi thất bại. Nhưng crash sau commit trước publish có thể mất thông báo vĩnh viễn; outbox cùng transaction và relay retry giảm khe hở đó. Consumer phải xử lý giao lại, chống snapshot cũ bằng version nguyên tử và có nguồn snapshot/event archive cho rebuild. Tôi chỉ dùng CQRS khi lợi ích mô hình và query đáng chi phí này.","sampleAnswer":"Command kiểm invariant và lưu trạng thái ở write model; query dùng một read model tối ưu cho tìm kiếm. Với đồng bộ async, commit có thể xong trước khi consumer cập nhật read model, nên đọc cũ không tự chứng minh ghi thất bại. Nhưng crash sau commit trước publish có thể mất thông báo vĩnh viễn; outbox cùng transaction và relay retry giảm khe hở đó. Consumer phải xử lý giao lại, chống snapshot cũ bằng version nguyên tử và có nguồn snapshot/event archive cho rebuild. Tôi chỉ dùng CQRS khi lợi ích mô hình và query đáng chi phí này.","misconception":"Có hai database tức là CQRS; mọi CRUD đều cần broker.; HTTP thành công đồng nghĩa projection đã cập nhật.; Upsert theo id xử lý được mọi sai thứ tự; queue đã ack là event archive."}}],"id":"0-interview"},{"title":"Dự đoán trước khi quan sát","phase":"predict","sortIndex":1,"body":"An có version 1 trên cả hai model. Command lưu tên “An Nguyễn”, version 2 ở PostgreSQL; event đã ở queue nhưng consumer chưa xử lý. Read API vẫn hoạt động và chỉ đọc Elasticsearch.","activities":[{"id":"cqrs-read-models--r1--predict-read","kind":"choice","prompt":"GET hồ sơ từ read API ngay bây giờ có thể trả gì?","stableKey":"predict-read","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Tách thời điểm xác nhận command khỏi thời điểm read model có thể quan sát thay đổi.","misconception":"Bắt buộc tên mới vì POST đã thành công; Bắt buộc 500 vì hai model chưa đồng bộ"},"options":[{"id":"cqrs-read-models--r1--predict-read--option-1","label":"Tên cũ An","explanation":"Đúng: projection mới chưa được áp dụng, read model vẫn ở version 1.","isCorrect":true},{"id":"cqrs-read-models--r1--predict-read--option-2","label":"Bắt buộc tên mới vì POST đã thành công","explanation":"Sai: commit và project là hai mốc khác nhau.","isCorrect":false},{"id":"cqrs-read-models--r1--predict-read--option-3","label":"Bắt buộc 500 vì hai model chưa đồng bộ","explanation":"Sai: đọc dữ liệu cũ có thể là hành vi được thiết kế, không phải exception.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Thử và quan sát","phase":"explore","sortIndex":2,"body":"Mô phỏng giữ read API sống và chỉ tạm dừng projector. Thử đọc ngay sau commit rồi mới giao event. Đây là khác biệt cần chú ý với việc dừng cả read-service: khi API cũng dừng thì request có thể thất bại kết nối, không phải trả dữ liệu cũ.\n\n**Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.**\n\n```mermaid\nflowchart LR\n U[User] -->|command| W[Write handler]\n W -->|one transaction| P[(State and outbox)]\n P --> L[Outbox relay]\n L --> Q[RabbitMQ]\n Q --> C[Projector]\n C -->|apply version| R[(Read model)]\n U -->|query| A[Read API]\n A --> R\n C -->|ack after success| Q\n```\n\n> Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.","activities":[{"id":"cqrs-read-models--r1--exploration","kind":"simulation","prompt":"Thử đường sai trước, đọc trạng thái quan sát được, sau đó tìm đường giải quyết. Kết thúc bằng câu giải thích nguyên nhân.","stableKey":"exploration","outcomeIds":["cqrs-read-models--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"cqrs-read-models--r1--exploration--state-v1","debriefQuestion":"Nếu giao v1 sau v2 thì upsert theo id có đủ không? Vì sao kiểm version cần nằm trong cùng thao tác cập nhật ở kho dữ liệu?","states":[{"id":"cqrs-read-models--r1--exploration--state-v1","label":"Hai model version 1","observation":"Write: An v1. Read: An v1. Queue rỗng.","isSuccess":false},{"id":"cqrs-read-models--r1--exploration--state-pending","label":"Đã ghi version 2","observation":"Write: An Nguyễn v2. Read: An v1. Projector đang dừng.","isSuccess":false},{"id":"cqrs-read-models--r1--exploration--state-stale-read","label":"Đọc trước project","observation":"GET trả An v1; command vẫn đã commit.","isSuccess":false},{"id":"cqrs-read-models--r1--exploration--state-caught-up","label":"Project thành công","observation":"Read: An Nguyễn v2. Có thể ack message.","isSuccess":false},{"id":"cqrs-read-models--r1--exploration--state-duplicate","label":"Giao lại v2","observation":"Read vẫn An Nguyễn v2; không tạo thay đổi lần hai.","isSuccess":true}],"actions":[{"id":"cqrs-read-models--r1--exploration--action-commit","label":"Gửi command v2"},{"id":"cqrs-read-models--r1--exploration--action-read","label":"Đọc read model"},{"id":"cqrs-read-models--r1--exploration--action-deliver","label":"Cho projector nhận v2"},{"id":"cqrs-read-models--r1--exploration--action-redeliver","label":"Giao lại cùng v2"}],"transitions":[{"id":"cqrs-read-models--r1--exploration--transition-0","fromStateId":"cqrs-read-models--r1--exploration--state-v1","actionId":"cqrs-read-models--r1--exploration--action-commit","toStateId":"cqrs-read-models--r1--exploration--state-pending"},{"id":"cqrs-read-models--r1--exploration--transition-1","fromStateId":"cqrs-read-models--r1--exploration--state-pending","actionId":"cqrs-read-models--r1--exploration--action-read","toStateId":"cqrs-read-models--r1--exploration--state-stale-read"},{"id":"cqrs-read-models--r1--exploration--transition-2","fromStateId":"cqrs-read-models--r1--exploration--state-stale-read","actionId":"cqrs-read-models--r1--exploration--action-deliver","toStateId":"cqrs-read-models--r1--exploration--state-caught-up"},{"id":"cqrs-read-models--r1--exploration--transition-3","fromStateId":"cqrs-read-models--r1--exploration--state-caught-up","actionId":"cqrs-read-models--r1--exploration--action-redeliver","toStateId":"cqrs-read-models--r1--exploration--state-duplicate"}]}}],"id":"2-experiment"},{"title":"Command nói muốn thay đổi; query nói muốn biết","phase":"explain","sortIndex":3,"body":"Command là yêu cầu có ý định thay đổi trạng thái: đổi tên, xác nhận đơn hàng, hủy đặt chỗ. Nó có thể bị từ chối vì quyền hoặc invariant. Query hỏi một góc nhìn: hồ sơ hiện tại, danh sách đơn chờ xử lý, kết quả tìm kiếm. CQRS cho phép diễn đạt hai trách nhiệm bằng hai mô hình riêng thay vì buộc một cấu trúc phục vụ mọi nhu cầu.\n\nBạn có thể bắt đầu bằng một ứng dụng và một database: handler ghi bảo vệ invariant, query trả DTO phù hợp màn hình. Khi query cần một hình dạng khác hẳn hoặc cần scale độc lập, có thể thêm projection riêng. PostgreSQL và Elasticsearch trong bài là một lựa chọn để thấy sự khác biệt; chúng không phải điều kiện định nghĩa CQRS. Trước khi thêm broker và store, hãy thử đo query hiện có, index thích hợp và nhu cầu thực sự.\n\nRead model là một cách nhìn được dựng từ thông tin gốc. Ví dụ, write model giữ customer và address riêng để kiểm ràng buộc; read model của trang tìm kiếm giữ tên, thành phố và nhãn đã ghép sẵn. Tối ưu đọc bằng cách làm trước công việc kết hợp dữ liệu có lợi khi nhiều lần đọc cùng một hình dạng, đổi lại mỗi lần thay đổi có thêm công việc cập nhật projection.","id":"3-theory-1"},{"title":"Vì sao tên mới tới sau","phase":"explain","sortIndex":4,"body":"Lần thay đổi đi qua nhiều mốc: command hợp lệ; transaction ghi commit; thông báo được chuyển tới broker; consumer nhận; read model cập nhật; query đọc được trạng thái mới. Nếu cơ chế cập nhật store còn có độ trễ nhìn thấy, đó là một mốc nữa. HTTP thành công có thể chỉ nói mốc commit đã đạt, tùy contract API, không tự nói mọi mốc phía sau đã đạt.\n\nEventual consistency có ý nghĩa khi hệ thống có cơ chế tiếp tục truyền và áp thay đổi, xử lý lỗi, và nguồn dữ liệu còn đủ. Không thể giải thích một event mất vĩnh viễn bằng “chờ thêm một chút”. Vì vậy cần quan sát backlog, tuổi event chưa xử lý, lỗi projection và version chênh lệch; queue length bằng 0 một mình không chứng minh read model đúng.\n\nNếu người dùng cần thấy ngay tên vừa đổi, command response có thể trả trạng thái đã commit để UI hiển thị, hoặc trả version token và chờ query đạt version đó với timeout hữu hạn. Một đường đọc nhất quán từ write side cũng có thể phục vụ use case này. Mỗi cách cần contract rõ: hiển thị optimistic không đồng nghĩa mọi query đã bắt kịp, và không được chờ vô hạn khi projector hỏng.","id":"4-theory-2"},{"title":"Khe hở giữa lưu và thông báo","phase":"explain","sortIndex":5,"body":"Code save(row); publish(event) có hai side effect. Process có thể chết sau save nhưng trước publish. Đảo thứ tự lại tạo nguy cơ phát event cho dữ liệu chưa commit. Transaction database thông thường không tự bao cả broker. Đây là vấn đề dual write, cần giải riêng; thêm từ await không đóng khe hở.\n\nMột cách là ghi state và outbox row trong cùng transaction database. Relay đọc outbox, publish, rồi đánh dấu đã gửi. Relay có thể chết sau publish trước đánh dấu, nên event có thể xuất hiện lần nữa. Outbox đổi nguy cơ mất thông báo thành bài toán retry/duplicate có thể quản lý; nó không tự tạo exactly-once. Thiết kế relay cần claim/lock phù hợp, retry và giám sát backlog.\n\nPublisher confirm và consumer ack là hai tín hiệu khác nhau. Broker xác nhận nhận message không nói consumer đã cập nhật Elasticsearch. Consumer nên ack sau khi projection thành công; nếu crash trước ack, message có thể giao lại. Event độc cần giới hạn retry, phân loại lỗi và nơi điều tra; requeue tức thì vô hạn có thể biến một payload lỗi thành vòng lặp nóng.","id":"5-theory-3"},{"title":"Giao lại khác với sai thứ tự","phase":"explain","sortIndex":6,"body":"**Mô hình snapshot đầy đủ có version. Không dùng thuật toán bỏ version cũ này trực tiếp cho chuỗi delta cộng/trừ.**\n\n```typescript\n/** Projection snapshot có version trong bộ nhớ. (EN: In-memory versioned snapshot projection.) */\ntype Snapshot = { id: string; version: number; name: string };\n/** Áp snapshot mới hơn; mô hình tuần tự, chưa có distributed CAS. (EN: Sequential model, not distributed CAS.) */\nexport function project(current: Snapshot | undefined, incoming: Snapshot): Snapshot {\n    if (!Number.isSafeInteger(incoming.version) || incoming.version < 1) throw new Error('invalid version');\n    if (current && current.id !== incoming.id) throw new Error('different entity');\n    if (current && incoming.version <= current.version) return current;\n    return {...incoming};\n}\n```\n\nNếu v2 bị giao lại sau chính v2, việc giữ một document theo id tránh tạo bản sao mới. Nhưng nếu v1 tới sau v2, upsert mù sẽ đổi tên về giá trị cũ. Với event chứa snapshot đầy đủ, ta chỉ áp version mới hơn. Khi nhiều consumer chạy đồng thời, bước kiểm và ghi phải nguyên tử tại store, chẳng hạn conditional update theo version; đọc version rồi ghi riêng vẫn có race.\n\nNếu event là delta “cộng thêm 1”, bỏ một event chỉ vì đã thấy version cao hơn có thể mất một phép cộng cần thiết. Khi đó cần cơ chế theo dõi event ID, phát hiện khoảng trống, sắp thứ tự theo aggregate hoặc cách phục hồi phù hợp. Bài source.ts cố ý chỉ hỗ trợ snapshot, không tuyên bố giải hết các dạng event.","id":"6-theory-4"},{"title":"Rebuild phải có nguồn để dựng lại","phase":"explain","sortIndex":7,"body":"Read model phái sinh không có nghĩa bạn có thể xóa nó bất cứ lúc nào mà không chuẩn bị. RabbitMQ queue sau khi message được ack không mặc nhiên giữ toàn bộ lịch sử để replay. Nếu write model chỉ giữ trạng thái hiện tại, có thể rebuild một projection trạng thái từ snapshot hiện tại, nhưng không dựng lại được lịch sử mà state hiện tại đã bỏ mất.\n\nMột kế hoạch rebuild thực tế xác định nguồn, mốc dữ liệu và cách bắt thay đổi trong lúc quét. Ví dụ: dựng index mới từ snapshot cùng watermark, tiếp tục áp các thay đổi sau watermark, kiểm chênh lệch rồi chuyển alias. Phải nghĩ tới record bị xóa và race giữa quét/cập nhật, không chỉ đếm document. Giữ index cũ trong thời gian phù hợp giúp rollback đường đọc. Chi phí thêm là storage, tải quét và vận hành; đây là lý do CRUD nhỏ thường chưa cần biến thể nhiều store.","activities":[{"id":"cqrs-read-models--r1--quiz-ordering","kind":"choice","prompt":"v3 đến trước v2, event là snapshot đầy đủ. Cách nào bảo vệ projection?","stableKey":"quiz-ordering","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--application"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Idempotency và ordering là hai yêu cầu khác nhau.","misconception":"Upsert theo id không cần version; Ack trước để queue không trùng"},"options":[{"id":"cqrs-read-models--r1--quiz-ordering--option-1","label":"Upsert theo id không cần version","explanation":"Sai: v2 có thể ghi đè v3.","isCorrect":false},{"id":"cqrs-read-models--r1--quiz-ordering--option-2","label":"Chỉ nhận snapshot có version lớn hơn với kiểm-ghi nguyên tử","explanation":"Đúng: chống ghi lùi trong phạm vi snapshot đã khai.","isCorrect":true},{"id":"cqrs-read-models--r1--quiz-ordering--option-3","label":"Ack trước để queue không trùng","explanation":"Sai: có thể mất event khi consumer chết trước ghi.","isCorrect":false}]},{"id":"cqrs-read-models--r1--quiz-rebuild","kind":"choice","prompt":"Queue đã ack hết event, write DB chỉ giữ trạng thái hiện tại. Có replay đầy đủ lịch sử từ queue không?","stableKey":"quiz-rebuild","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--tradeoffs"],"placementSortIndex":1,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Mỗi tuyên bố rebuild phải chỉ rõ dữ liệu nằm ở đâu.","misconception":"Có vì queue durable; Chỉ cần tăng replica Elasticsearch"},"options":[{"id":"cqrs-read-models--r1--quiz-rebuild--option-1","label":"Có vì queue durable","explanation":"Sai: durable không biến message đã ack thành lịch sử vĩnh viễn.","isCorrect":false},{"id":"cqrs-read-models--r1--quiz-rebuild--option-2","label":"Không; cần event archive hoặc thiết kế rebuild từ snapshot phù hợp","explanation":"Đúng: phải có nguồn thực tế.","isCorrect":true},{"id":"cqrs-read-models--r1--quiz-rebuild--option-3","label":"Chỉ cần tăng replica Elasticsearch","explanation":"Sai: replica không tạo lại lịch sử nguồn bị thiếu.","isCorrect":false}]}],"id":"7-theory-5"},{"title":"Thực hành có bằng chứng","phase":"apply","sortIndex":8,"body":"Bắt đầu bằng source.ts để thấy lỗi ordering mà không phải dựng năm service. Test đưa v3 rồi v2, giao lại v3 và kiểm không ghi lùi. Đây là phần thực hành bắt buộc của seed; bài mở rộng hạ tầng giữ thành workspace source riêng.\n\n**Windows PowerShell, Node.js 24.**\n\n```powershell\nnode --test source.test.ts\n```\n\n**macOS/Linux, Node.js 24.**\n\n```bash\nnode --test source.test.ts\n```\n\nKhi làm tiếp với stack legacy NestJS/Postgres/RabbitMQ/Elasticsearch, cần 5 phép kiểm: command tạo; query sau project; update cùng id; query id chưa project; tạm dừng projector rồi tiêu thụ bù. Ghi producer log, consumer log và trạng thái broker. Nếu dừng cả read-service, ghi nhận lỗi kết nối khi GET, không gọi đó là stale read. Bộ seed này chưa chạy Docker integration và không ghi một response giả thành kết quả đã đo.","activities":[{"id":"cqrs-read-models--r1--practice-ordering","kind":"exercise","prompt":"Trong source.ts, bỏ điều kiện incoming.version <= current.version và chạy test. Nộp case thất bại, phục hồi điều kiện và giải thích vì sao code tuần tự này vẫn chưa đủ cho hai consumer cùng cập nhật database.","stableKey":"practice-ordering","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism","cqrs-read-models--r1--application","cqrs-read-models--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"cqrs-read-models--r1--practice-ordering--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Log test v3 rồi v2 đỏ khi bỏ version guard và xanh khi phục hồi.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"cqrs-read-models--r1--practice-ordering--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Phân biệt duplicate snapshot với event tới sai thứ tự.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"cqrs-read-models--r1--practice-ordering--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Chỉ ra read-check-write có race với nhiều consumer; cần kiểm-ghi nguyên tử tại store.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"Test v3 rồi v2 bắt việc projection ghi lùi. Phục hồi guard giữ v3, duplicate không thay kết quả. Hai consumer có thể cùng đọc version cũ trước khi ghi; cần conditional update/CAS tại store. Test trong bộ nhớ không chứng minh atomicity của database.","sampleAnswer":"Test v3 rồi v2 bắt việc projection ghi lùi. Phục hồi guard giữ v3, duplicate không thay kết quả. Hai consumer có thể cùng đọc version cũ trước khi ghi; cần conditional update/CAS tại store. Test trong bộ nhớ không chứng minh atomicity của database.","misconception":"Có hai database tức là CQRS; mọi CRUD đều cần broker.; HTTP thành công đồng nghĩa projection đã cập nhật.; Upsert theo id xử lý được mọi sai thứ tự; queue đã ack là event archive."},"exercise":{"submissionInstructions":"Trong source.ts, bỏ điều kiện incoming.version <= current.version và chạy test. Nộp case thất bại, phục hồi điều kiện và giải thích vì sao code tuần tự này vẫn chưa đủ cho hai consumer cùng cập nhật database.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production.","files":[{"relativePath":"source.ts","role":"reference","syntaxLanguage":"typescript","content":"/** Projection snapshot có version trong bộ nhớ. (EN: In-memory versioned snapshot projection.) */\ntype Snapshot = { id: string; version: number; name: string };\n/** Áp snapshot mới hơn; mô hình tuần tự, chưa có distributed CAS. (EN: Sequential model, not distributed CAS.) */\nexport function project(current: Snapshot | undefined, incoming: Snapshot): Snapshot {\n    if (!Number.isSafeInteger(incoming.version) || incoming.version < 1) throw new Error('invalid version');\n    if (current && current.id !== incoming.id) throw new Error('different entity');\n    if (current && incoming.version <= current.version) return current;\n    return {...incoming};\n}\n","sha256":"5434fed6607928548869ee7f088eae942d72012640b827e449609b6082d14eb3"},{"relativePath":"source.test.ts","role":"checks","syntaxLanguage":"typescript","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {project} from './source.ts';\ntest('late snapshot cannot overwrite latest', (): void => {const latest=project(undefined,{id:'c1',version:3,name:'New'});assert.equal(project(latest,{id:'c1',version:2,name:'Old'}).name,'New');});\ntest('duplicate is unchanged', (): void => {const row={id:'c1',version:3,name:'New'};assert.equal(project(row,{...row}),row);});\ntest('new version applies and invalid input fails', (): void => {assert.equal(project({id:'c1',version:1,name:'Old'},{id:'c1',version:2,name:'New'}).version,2);assert.throws(()=>project(undefined,{id:'c1',version:0,name:'Bad'}));});\n","sha256":"848304cf625b56f175f1d9fb0a66f71724b9b0ae2ab6a3b9be4f7167689162d7"}],"checks":[{"id":"cqrs-read-models--r1--practice-ordering--node-tests","runner":"node-test","entrypoint":"source.test.ts","expectedExitCode":0,"scope":"educational-local-model","runtime":"Node.js 24","executionStatus":"passed"}]}}],"id":"8-practice"},{"title":"Tình huống mới","phase":"apply","sortIndex":9,"body":"Đóng lời giải trước khi làm. Nếu dùng gợi ý, hệ thống vẫn ghi nhận bài làm nhưng gắn nhãn có hỗ trợ.","activities":[{"id":"cqrs-read-models--r1--transfer-inventory","kind":"exercise","prompt":"Trang tìm kiếm hàng hóa chấp nhận trễ 3 giây; xác nhận mua không được bán vượt tồn. Đề xuất đường đọc/ghi cho hai use case, xử lý read-your-writes và kế hoạch khi projector ngừng 10 phút.","stableKey":"transfer-inventory","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism","cqrs-read-models--r1--application","cqrs-read-models--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"cqrs-read-models--r1--transfer-inventory--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Tồn khi mua được quyết định ở write authority, không từ search projection cũ.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"cqrs-read-models--r1--transfer-inventory--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Nêu cách hiển thị sau command/version và chính sách search chấp nhận trễ.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"cqrs-read-models--r1--transfer-inventory--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Có kế hoạch lag/backlog, phục hồi projector và nguồn rebuild; cân nhắc một store nếu đủ.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"Danh sách tìm kiếm có thể dùng read model trễ; xác nhận mua phải kiểm và thay đổi tồn tại write authority với cơ chế concurrency phù hợp, không quyết từ read model cũ. UI dùng kết quả command/version cho thao tác vừa thực hiện. Projector ngừng làm dữ liệu tìm kiếm cũ; đo lag, báo trạng thái phù hợp, giữ event/outbox để bắt kịp và có kế hoạch snapshot/rebuild. Nếu quy mô nhỏ, giữ một database với model tách có thể đủ.","sampleAnswer":"Danh sách tìm kiếm có thể dùng read model trễ; xác nhận mua phải kiểm và thay đổi tồn tại write authority với cơ chế concurrency phù hợp, không quyết từ read model cũ. UI dùng kết quả command/version cho thao tác vừa thực hiện. Projector ngừng làm dữ liệu tìm kiếm cũ; đo lag, báo trạng thái phù hợp, giữ event/outbox để bắt kịp và có kế hoạch snapshot/rebuild. Nếu quy mô nhỏ, giữ một database với model tách có thể đủ.","misconception":"Có hai database tức là CQRS; mọi CRUD đều cần broker.; HTTP thành công đồng nghĩa projection đã cập nhật.; Upsert theo id xử lý được mọi sai thứ tự; queue đã ack là event archive."},"exercise":{"submissionInstructions":"Trang tìm kiếm hàng hóa chấp nhận trễ 3 giây; xác nhận mua không được bán vượt tồn. Đề xuất đường đọc/ghi cho hai use case, xử lý read-your-writes và kế hoạch khi projector ngừng 10 phút.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production."}}],"id":"9-transfer"},{"title":"Phỏng vấn lại và tự giải thích","phase":"reflect","sortIndex":10,"body":"CQRS giúp bạn chọn mô hình đúng cho một trách nhiệm. Đổi lại, khi tách store bằng bất đồng bộ, bạn phải giải thích được mỗi khoảng cách giữa ghi và đọc, cả lúc bình thường lẫn lúc một bước thất bại.\n\nAI trả kết quả theo từng tiêu chí và trích đoạn bài nộp làm bằng chứng. Khi chấm chưa xong, trạng thái là đang chấm; bạn có thể tiếp tục đọc và quay lại. Điểm phỏng vấn không tăng chỉ vì câu trả lời dài.","activities":[{"id":"cqrs-read-models--r1--final-interview","kind":"explain","prompt":"Thiết kế đường ghi hồ sơ và đường đọc tìm kiếm. Vì sao tên cũ có thể xuất hiện sau khi ghi thành công? Hãy chỉ ra một lỗi làm read model không bao giờ bắt kịp nếu không có cơ chế sửa.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism","cqrs-read-models--r1--application","cqrs-read-models--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"cqrs-read-models--r1--final-interview--criterion-0","criterion":"Trách nhiệm và trade-off","expectedEvidence":"Phân biệt command/query; chọn tách vì nhu cầu cụ thể, không vì số database.","misconception":"Có hai database tức là CQRS; mọi CRUD đều cần broker.","maxScore":2},{"id":"cqrs-read-models--r1--final-interview--criterion-1","criterion":"Đường đồng bộ","expectedEvidence":"Kể commit, chuyển event, project và đọc; chỉ ra cửa sổ mất event hoặc đọc cũ.","misconception":"HTTP thành công đồng nghĩa projection đã cập nhật.","maxScore":2},{"id":"cqrs-read-models--r1--final-interview--criterion-2","criterion":"Độ tin cậy và giới hạn","expectedEvidence":"Phân biệt duplicate với stale event; nêu version check nguyên tử, nguồn rebuild và phạm vi bằng chứng.","misconception":"Upsert theo id xử lý được mọi sai thứ tự; queue đã ack là event archive.","maxScore":2}],"answer":{"explanation":"Command kiểm invariant và lưu trạng thái ở write model; query dùng một read model tối ưu cho tìm kiếm. Với đồng bộ async, commit có thể xong trước khi consumer cập nhật read model, nên đọc cũ không tự chứng minh ghi thất bại. Nhưng crash sau commit trước publish có thể mất thông báo vĩnh viễn; outbox cùng transaction và relay retry giảm khe hở đó. Consumer phải xử lý giao lại, chống snapshot cũ bằng version nguyên tử và có nguồn snapshot/event archive cho rebuild. Tôi chỉ dùng CQRS khi lợi ích mô hình và query đáng chi phí này.","sampleAnswer":"Command kiểm invariant và lưu trạng thái ở write model; query dùng một read model tối ưu cho tìm kiếm. Với đồng bộ async, commit có thể xong trước khi consumer cập nhật read model, nên đọc cũ không tự chứng minh ghi thất bại. Nhưng crash sau commit trước publish có thể mất thông báo vĩnh viễn; outbox cùng transaction và relay retry giảm khe hở đó. Consumer phải xử lý giao lại, chống snapshot cũ bằng version nguyên tử và có nguồn snapshot/event archive cho rebuild. Tôi chỉ dùng CQRS khi lợi ích mô hình và query đáng chi phí này.","misconception":"Có hai database tức là CQRS; mọi CRUD đều cần broker.; HTTP thành công đồng nghĩa projection đã cập nhật.; Upsert theo id xử lý được mọi sai thứ tự; queue đã ack là event archive."}}],"id":"10-reflection"}]},"en":{"title":"CQRS — separate changing data from viewing it","description":"CQRS separates the model that processes changes from the model that serves queries, allowing each to express its own responsibilities and needs.","body":"## Summary\n\nCQRS helps match models to responsibilities. When you synchronize separate stores asynchronously, you must explain every gap between writing and reading, both during normal operation and when a step fails.\n\n## Learning outcomes\n\n- Explain the path from command to projection and predict when the read model is still old.\n- Fix a projection receiving duplicate or out-of-order snapshots and propose verification.\n- Choose CQRS conditionally, explain synchronization costs and identify a real rebuilding source.\n\n## Prerequisites\n\n- Understand database transactions and HTTP APIs.\n- Read TypeScript and understand queues delivering messages to consumers.\n\n## Included scope\n\n- Separate commands, queries and read models.\n- Eventual consistency, read-your-writes.\n- Dual writes, outboxes, acknowledgements, duplicates, ordering and rebuilding within CQRS.\n\n## Excluded scope\n\n- A complete Event Sourcing implementation.\n- Production broker and Elasticsearch cluster setup.\n- System-wide exactly-once guarantees.\n\n## Key claims\n\n- CQRS does not require two databases, a broker or Event Sourcing.\n- An asynchronous projection can lag behind the write model.\n- ID-based idempotency does not stop an old snapshot from overwriting a newer one.\n\n## Corrections\n\n- Correct the legacy claim that CQRS inherently requires accepting divergence between two stores: that describes this lesson's asynchronous variant.\n- Saving then publishing is not an atomic transaction; awaiting EventBus does not automatically provide durability.\n- Do not treat an acknowledged RabbitMQ queue as a replayable historical archive.\n- Upserting by ID does not solve ordering; concurrent consumers need an atomic version check and write.\n- Do not claim PostgreSQL is inherently poor at full-text search; measure queries and indexes before separating stores.\n\n## References\n\n- [learn.microsoft.com/en-us/azure/architecture/patterns/cqrs](https://learn.microsoft.com/en-us/azure/architecture/patterns/cqrs)\n- [www.rabbitmq.com/docs/confirms](https://www.rabbitmq.com/docs/confirms)","learningOutcomes":[{"id":"cqrs-read-models--r1--mechanism","text":"Explain the path from command to projection and predict when the read model is still old."},{"id":"cqrs-read-models--r1--application","text":"Fix a projection receiving duplicate or out-of-order snapshots and propose verification."},{"id":"cqrs-read-models--r1--tradeoffs","text":"Choose CQRS conditionally, explain synchronization costs and identify a real rebuilding source."}],"prerequisites":[{"id":"cqrs-read-models--r1--input-0","text":"Understand database transactions and HTTP APIs."},{"id":"cqrs-read-models--r1--input-1","text":"Read TypeScript and understand queues delivering messages to consumers."}],"references":[{"id":"cqrs-read-models--r1--legacy","label":"Pre-migration data source","citation":"legacy; courses/1-system-design-mastery/modules/3-communication-patterns/contents/6-cqrs-and-read-models/bodies/0-typescript/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 34f20e4d0f72f02d4dcf3a4c48d722291b5fa3da483cd086e623f8226ce299e2; checked 2026-09-05; New V2 sample; V1 remains unchanged."},{"id":"cqrs-read-models--r1--official-0","label":"learn.microsoft.com/en-us/azure/architecture/patterns/cqrs","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/cqrs","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."},{"id":"cqrs-read-models--r1--official-1","label":"www.rabbitmq.com/docs/confirms","url":"https://www.rabbitmq.com/docs/confirms","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."}],"retrieval":[{"id":"cqrs-read-models--r1--retrieval-1","kind":"retrieval","prompt":"One day later: POST succeeded, the queue is empty and GET is still old. Give two different causes and the evidence needed to distinguish them.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism"],"afterDays":1,"rubric":[{"id":"cqrs-read-models--r1--retrieval-1--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"Publishing may have failed before the queue received anything; a consumer may have acknowledged before projecting; or the query may target another store or index. Inspect outbox and producer confirms, consumer logs, versions and query targets. An empty queue does not prove synchronization.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"Publishing may have failed before the queue received anything; a consumer may have acknowledged before projecting; or the query may target another store or index. Inspect outbox and producer confirms, consumer logs, versions and query targets. An empty queue does not prove synchronization.","sampleAnswer":"Publishing may have failed before the queue received anything; a consumer may have acknowledged before projecting; or the query may target another store or index. Inspect outbox and producer confirms, consumer logs, versions and query targets. An empty queue does not prove synchronization.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"cqrs-read-models--r1--retrieval-2","kind":"retrieval","prompt":"One week later: the team wants to move all CRUD operations to two-store CQRS. What evidence do you request first, and what simpler design might suffice?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--application"],"afterDays":7,"rubric":[{"id":"cqrs-read-models--r1--retrieval-2--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"Measure query bottlenecks and modeling or scaling needs, then try suitable queries and indexes. Commands and queries can be separated inside one app and database. Add asynchronous projections only when the benefits exceed consistency, operations and rebuilding costs.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"Measure query bottlenecks and modeling or scaling needs, then try suitable queries and indexes. Commands and queries can be separated inside one app and database. Add asynchronous projections only when the benefits exceed consistency, operations and rebuilding costs.","sampleAnswer":"Measure query bottlenecks and modeling or scaling needs, then try suitable queries and indexes. Commands and queries can be separated inside one app and database. Add asynchronous projections only when the benefits exceed consistency, operations and rebuilding costs.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"cqrs-read-models--r1--retrieval-3","kind":"retrieval","prompt":"After 21 days: a historical-price chart is needed, but only current prices and an already-acknowledged queue exist. Can rebuilding recover history? Propose an extension.","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"cqrs-read-models--r1--retrieval-3--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"Current prices cannot reveal lost history. You need a durable historical source collected from a known point onward or a real archive to import. CQRS does not automatically supply Event Sourcing; state historical-data limitations before building the projection.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"Current prices cannot reveal lost history. You need a durable historical source collected from a known point onward or a real archive to import. CQRS does not automatically supply Event Sourcing; state historical-data limitations before building the projection.","sampleAnswer":"Current prices cannot reveal lost history. You need a durable historical source collected from a known point onward or a real archive to import. CQRS does not automatically supply Event Sourcing; state historical-data limitations before building the projection.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}}],"sections":[{"title":"Interview context","phase":"challenge","sortIndex":0,"body":"In a system design interview, a user changes their name to 'An Nguyễn'. The API reports success, but search still displays 'An'. 'Did the write fail?' You suggest an uncleared cache. The interviewer reveals the architecture: writes use PostgreSQL, searches read Elasticsearch, and RabbitMQ connects them. Explain which system knows the new name, which does not, and how it catches up.\n\nAnswer using your current understanding. This initial diagnostic does not establish mastery. You will answer again after practice, and the lesson remains open if you do not yet know the answer.","activities":[{"id":"cqrs-read-models--r1--opening-interview","kind":"explain","prompt":"Design profile writes and search reads. Why might the old name appear after a successful write? Identify a failure that prevents the read model from ever catching up without a repair mechanism.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism","cqrs-read-models--r1--application","cqrs-read-models--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"cqrs-read-models--r1--opening-interview--criterion-0","criterion":"Responsibilities and trade-offs","expectedEvidence":"Distinguish commands and queries; separate them for concrete needs rather than database count.","misconception":"Two databases mean CQRS and every CRUD app needs a broker.","maxScore":2},{"id":"cqrs-read-models--r1--opening-interview--criterion-1","criterion":"Synchronization path","expectedEvidence":"Describe commit, event transfer, projection and reading; identify a window for event loss or stale reads.","misconception":"HTTP success means the projection is updated.","maxScore":2},{"id":"cqrs-read-models--r1--opening-interview--criterion-2","criterion":"Reliability and limitations","expectedEvidence":"Distinguish duplicates from old events; explain atomic version checks, rebuilding sources and evidence limits.","misconception":"ID-based upsert handles every ordering problem and an acknowledged queue is an event archive.","maxScore":2}],"answer":{"explanation":"Commands protect invariants and save state in the write model; queries use a read model optimized for search. With asynchronous synchronization, commit can finish before a consumer updates the read model, so an old read does not itself prove a failed write. A crash between commit and publish can permanently lose a notification; a transactional outbox and retrying relay address that gap. Consumers must tolerate redelivery, reject old snapshots with atomic version checks and have a snapshot or event archive for rebuilding. Use CQRS when modeling and query benefits justify these costs.","sampleAnswer":"Commands protect invariants and save state in the write model; queries use a read model optimized for search. With asynchronous synchronization, commit can finish before a consumer updates the read model, so an old read does not itself prove a failed write. A crash between commit and publish can permanently lose a notification; a transactional outbox and retrying relay address that gap. Consumers must tolerate redelivery, reject old snapshots with atomic version checks and have a snapshot or event archive for rebuilding. Use CQRS when modeling and query benefits justify these costs.","misconception":"Two databases mean CQRS and every CRUD app needs a broker.; HTTP success means the projection is updated.; ID-based upsert handles every ordering problem and an acknowledged queue is an event archive."}}],"id":"0-interview"},{"title":"Predict before observing","phase":"predict","sortIndex":1,"body":"An is at version 1 in both models. A command saves 'An Nguyễn', version 2, in PostgreSQL. Its event is queued but not yet processed. The read API remains available and reads only Elasticsearch.","activities":[{"id":"cqrs-read-models--r1--predict-read","kind":"choice","prompt":"What can a profile GET from the read API return right now?","stableKey":"predict-read","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Separate command acknowledgement from the moment a read model can expose the change.","misconception":"The new name is mandatory because POST succeeded; HTTP 500 is mandatory because the models have not synchronized"},"options":[{"id":"cqrs-read-models--r1--predict-read--option-1","label":"The old name, An","explanation":"Correct: the new projection has not been applied and the read model is still at version 1.","isCorrect":true},{"id":"cqrs-read-models--r1--predict-read--option-2","label":"The new name is mandatory because POST succeeded","explanation":"Incorrect: commit and projection are separate milestones.","isCorrect":false},{"id":"cqrs-read-models--r1--predict-read--option-3","label":"HTTP 500 is mandatory because the models have not synchronized","explanation":"Incorrect: returning old data can be intentional rather than an exception.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Experiment and observe","phase":"explore","sortIndex":2,"body":"The simulation keeps the read API alive and pauses only the projector. Read immediately after commit, then deliver the event. This differs from stopping the whole read service: when the API itself is down, requests may fail to connect instead of returning old data.\n\n**A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.**\n\n```mermaid\nflowchart LR\n U[User] -->|command| W[Write handler]\n W -->|one transaction| P[(State and outbox)]\n P --> L[Outbox relay]\n L --> Q[RabbitMQ]\n Q --> C[Projector]\n C -->|apply version| R[(Read model)]\n U -->|query| A[Read API]\n A --> R\n C -->|ack after success| Q\n```\n\n> A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.","activities":[{"id":"cqrs-read-models--r1--exploration","kind":"simulation","prompt":"Try an incorrect path first, read the observed state, then find a solution. Finish by explaining the cause.","stableKey":"exploration","outcomeIds":["cqrs-read-models--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"cqrs-read-models--r1--exploration--state-v1","debriefQuestion":"If v1 arrives after v2, is upsert by ID sufficient? Why must the version check be part of the same store update?","states":[{"id":"cqrs-read-models--r1--exploration--state-v1","label":"Hai model version 1","observation":"Write: An v1. Read: An v1. The queue is empty.","isSuccess":false},{"id":"cqrs-read-models--r1--exploration--state-pending","label":"Version 2 committed","observation":"Write: An Nguyễn v2. Read: An v1. The projector is stopped.","isSuccess":false},{"id":"cqrs-read-models--r1--exploration--state-stale-read","label":"Read before projection","observation":"GET returns An v1; the command is still committed.","isSuccess":false},{"id":"cqrs-read-models--r1--exploration--state-caught-up","label":"Projection succeeds","observation":"Read: An Nguyễn v2. The message can be acknowledged.","isSuccess":false},{"id":"cqrs-read-models--r1--exploration--state-duplicate","label":"Redeliver v2","observation":"Read remains An Nguyễn v2; there is no second change.","isSuccess":true}],"actions":[{"id":"cqrs-read-models--r1--exploration--action-commit","label":"Send command v2"},{"id":"cqrs-read-models--r1--exploration--action-read","label":"Read the read model"},{"id":"cqrs-read-models--r1--exploration--action-deliver","label":"Let the projector receive v2"},{"id":"cqrs-read-models--r1--exploration--action-redeliver","label":"Redeliver the same v2"}],"transitions":[{"id":"cqrs-read-models--r1--exploration--transition-0","fromStateId":"cqrs-read-models--r1--exploration--state-v1","actionId":"cqrs-read-models--r1--exploration--action-commit","toStateId":"cqrs-read-models--r1--exploration--state-pending"},{"id":"cqrs-read-models--r1--exploration--transition-1","fromStateId":"cqrs-read-models--r1--exploration--state-pending","actionId":"cqrs-read-models--r1--exploration--action-read","toStateId":"cqrs-read-models--r1--exploration--state-stale-read"},{"id":"cqrs-read-models--r1--exploration--transition-2","fromStateId":"cqrs-read-models--r1--exploration--state-stale-read","actionId":"cqrs-read-models--r1--exploration--action-deliver","toStateId":"cqrs-read-models--r1--exploration--state-caught-up"},{"id":"cqrs-read-models--r1--exploration--transition-3","fromStateId":"cqrs-read-models--r1--exploration--state-caught-up","actionId":"cqrs-read-models--r1--exploration--action-redeliver","toStateId":"cqrs-read-models--r1--exploration--state-duplicate"}]}}],"id":"2-experiment"},{"title":"Commands express changes; queries express questions","phase":"explain","sortIndex":3,"body":"A command expresses an intention to change state: rename a user, confirm an order or cancel a reservation. Authorization or an invariant can reject it. A query requests a view: a current profile, pending orders or search results. CQRS expresses these responsibilities through distinct models instead of forcing one structure to serve every need.\n\nStart with one application and one database if sufficient: write handlers protect invariants while queries return screen-oriented DTOs. Add a separate projection when query shape or independent scaling warrants it. PostgreSQL and Elasticsearch illustrate the distinction here; they do not define CQRS. Before adding a broker and another store, measure existing queries, suitable indexes and actual requirements.\n\nA read model is a view derived from source information. The write model might keep customer and address separately to enforce constraints, while a search read model stores a prejoined name, city and labels. Precomputing this combination benefits repeated reads of the same shape, but each change creates additional projection-update work.","id":"3-theory-1"},{"title":"Why the new name arrives later","phase":"explain","sortIndex":4,"body":"A change crosses several milestones: command validation, transaction commit, broker delivery, consumer receipt, read-model update and query visibility. A store's visibility delay may add another milestone. Depending on the API contract, HTTP success can mean only that commit completed; it does not automatically certify all downstream milestones.\n\nEventual consistency relies on continued delivery and application of changes, failure handling and sufficient retained data. 'Wait a little longer' does not explain a permanently lost event. Observe backlog, oldest unprocessed event age, projection failures and version gaps. Queue length zero alone does not establish a correct read model.\n\nFor immediate read-your-writes, a command response can return committed state for the UI, or return a version token and wait for queries to reach that version with a bounded timeout. A consistent write-side read can also serve this use case. Define the contract: optimistic display does not mean every query has caught up, and waiting forever during projector failure is unacceptable.","id":"4-theory-2"},{"title":"The gap between saving and notifying","phase":"explain","sortIndex":5,"body":"save(row); publish(event) performs two side effects. The process can die after saving but before publishing. Reversing them risks announcing data that never commits. An ordinary database transaction does not automatically include a broker. This dual-write problem needs its own solution; adding await does not close the gap.\n\nOne approach writes state and an outbox row in the same database transaction. A relay reads the outbox, publishes and marks it sent. A crash after publishing but before marking can cause redelivery. The outbox turns possible notification loss into manageable retry and duplication; it does not create exactly-once behavior. Relay design still needs suitable claiming or locking, retries and backlog monitoring.\n\nPublisher confirms and consumer acknowledgements are separate signals. A broker confirming receipt says nothing about an Elasticsearch update. A consumer should acknowledge after successful projection; a crash before acknowledgement can cause redelivery. Poison events need bounded retries, error classification and a place for investigation. Immediate, unlimited requeueing can turn one invalid payload into a hot loop.","id":"5-theory-3"},{"title":"Redelivery is different from reordering","phase":"explain","sortIndex":6,"body":"**A model of full, versioned snapshots. Do not apply its old-version rejection algorithm directly to a sequence of increment/decrement deltas.**\n\n```typescript\n/** Projection snapshot có version trong bộ nhớ. (EN: In-memory versioned snapshot projection.) */\ntype Snapshot = { id: string; version: number; name: string };\n/** Áp snapshot mới hơn; mô hình tuần tự, chưa có distributed CAS. (EN: Sequential model, not distributed CAS.) */\nexport function project(current: Snapshot | undefined, incoming: Snapshot): Snapshot {\n    if (!Number.isSafeInteger(incoming.version) || incoming.version < 1) throw new Error('invalid version');\n    if (current && current.id !== incoming.id) throw new Error('different entity');\n    if (current && incoming.version <= current.version) return current;\n    return {...incoming};\n}\n```\n\nRedelivering v2 after v2 need not create another document when identity is stable. But a blind upsert of v1 after v2 can restore the old name. For full snapshots, apply only newer versions. With concurrent consumers, the check and write must be atomic at the store, for example through a conditional version update; separate reads and writes still race.\n\nFor a delta such as 'add 1', dropping an event merely because a higher version was seen can lose a required increment. Such streams need event-ID tracking, gap detection, per-aggregate ordering or another suitable recovery mechanism. source.ts intentionally supports snapshots only and does not claim to solve every event format.","id":"6-theory-4"},{"title":"Rebuilding needs a real source","phase":"explain","sortIndex":7,"body":"A derived read model cannot necessarily be deleted without preparation. An acknowledged RabbitMQ queue does not automatically retain all history for replay. Current write-state snapshots may rebuild a current-state projection, but cannot reconstruct historical information that the current state has discarded.\n\nA practical rebuild specifies the source, data boundary and capture of changes during scanning. For example, build a new index from a snapshot and watermark, apply later changes, verify differences and switch the alias. Account for deleted records and scan/update races, not merely document counts. Retaining the old index for an appropriate period enables read-path rollback. Storage, scan load and operational costs explain why small CRUD applications often do not need multiple stores.","activities":[{"id":"cqrs-read-models--r1--quiz-ordering","kind":"choice","prompt":"v3 arrives before v2 and events contain full snapshots. Which approach protects the projection?","stableKey":"quiz-ordering","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--application"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Idempotency and ordering are different requirements.","misconception":"Upsert by ID without a version; Acknowledge first to prevent queue duplicates"},"options":[{"id":"cqrs-read-models--r1--quiz-ordering--option-1","label":"Upsert by ID without a version","explanation":"Incorrect: v2 can overwrite v3.","isCorrect":false},{"id":"cqrs-read-models--r1--quiz-ordering--option-2","label":"Accept only newer snapshots using an atomic check-and-write","explanation":"Correct: this prevents regression within the stated snapshot model.","isCorrect":true},{"id":"cqrs-read-models--r1--quiz-ordering--option-3","label":"Acknowledge first to prevent queue duplicates","explanation":"Incorrect: a crash before writing may lose the event.","isCorrect":false}]},{"id":"cqrs-read-models--r1--quiz-rebuild","kind":"choice","prompt":"All events have been acknowledged and the write database keeps only current state. Can the full history be replayed from the queue?","stableKey":"quiz-rebuild","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--tradeoffs"],"placementSortIndex":1,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Every rebuilding claim must identify where its source data resides.","misconception":"Yes, because the queue is durable; Just add Elasticsearch replicas"},"options":[{"id":"cqrs-read-models--r1--quiz-rebuild--option-1","label":"Yes, because the queue is durable","explanation":"Incorrect: durability does not turn acknowledged messages into permanent history.","isCorrect":false},{"id":"cqrs-read-models--r1--quiz-rebuild--option-2","label":"No; use an event archive or an appropriate snapshot-based rebuilding design","explanation":"Correct: a real source is required.","isCorrect":true},{"id":"cqrs-read-models--r1--quiz-rebuild--option-3","label":"Just add Elasticsearch replicas","explanation":"Incorrect: replicas cannot recreate missing source history.","isCorrect":false}]}],"id":"7-theory-5"},{"title":"Practice with evidence","phase":"apply","sortIndex":8,"body":"Begin with source.ts to observe ordering errors without setting up five services. Tests send v3 then v2, redeliver v3 and check for regression. This is the seed's required practice; infrastructure extensions belong in a separate source workspace.\n\n**Windows PowerShell, Node.js 24.**\n\n```powershell\nnode --test source.test.ts\n```\n\n**macOS/Linux, Node.js 24.**\n\n```bash\nnode --test source.test.ts\n```\n\nWhen extending the legacy NestJS/PostgreSQL/RabbitMQ/Elasticsearch stack, verify five paths: create command, query after projection, update the same ID, query an ID not yet projected, and pause then catch up the projector. Record producer logs, consumer logs and broker state. If the entire read service stops, record the GET connection failure rather than calling it a stale read. This seed has not run Docker integration and does not present fabricated responses as measurements.","activities":[{"id":"cqrs-read-models--r1--practice-ordering","kind":"exercise","prompt":"Remove incoming.version <= current.version from source.ts and run the tests. Submit the failing case, restore the condition, and explain why this sequential code is still insufficient for two consumers updating a database concurrently.","stableKey":"practice-ordering","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism","cqrs-read-models--r1--application","cqrs-read-models--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"cqrs-read-models--r1--practice-ordering--criterion-0","criterion":"Requested result","expectedEvidence":"Provide a failing v3-then-v2 test without the version guard and a passing run after restoring it.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"cqrs-read-models--r1--practice-ordering--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Distinguish a duplicate snapshot from an out-of-order event.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"cqrs-read-models--r1--practice-ordering--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Identify the concurrent read-check-write race and require atomic check-and-write at the store.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"The v3-then-v2 test catches projection regression. Restoring the guard retains v3, and a duplicate does not change the result. Two consumers can both read an old version before writing, so use a conditional update or CAS at the store. An in-memory test does not establish database atomicity.","sampleAnswer":"The v3-then-v2 test catches projection regression. Restoring the guard retains v3, and a duplicate does not change the result. Two consumers can both read an old version before writing, so use a conditional update or CAS at the store. An in-memory test does not establish database atomicity.","misconception":"Two databases mean CQRS and every CRUD app needs a broker.; HTTP success means the projection is updated.; ID-based upsert handles every ordering problem and an acknowledged queue is an event archive."},"exercise":{"submissionInstructions":"Remove incoming.version <= current.version from source.ts and run the tests. Submit the failing case, restore the condition, and explain why this sequential code is still insufficient for two consumers updating a database concurrently.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works.","files":[{"relativePath":"source.ts","role":"reference","syntaxLanguage":"typescript","content":"/** Projection snapshot có version trong bộ nhớ. (EN: In-memory versioned snapshot projection.) */\ntype Snapshot = { id: string; version: number; name: string };\n/** Áp snapshot mới hơn; mô hình tuần tự, chưa có distributed CAS. (EN: Sequential model, not distributed CAS.) */\nexport function project(current: Snapshot | undefined, incoming: Snapshot): Snapshot {\n    if (!Number.isSafeInteger(incoming.version) || incoming.version < 1) throw new Error('invalid version');\n    if (current && current.id !== incoming.id) throw new Error('different entity');\n    if (current && incoming.version <= current.version) return current;\n    return {...incoming};\n}\n","sha256":"5434fed6607928548869ee7f088eae942d72012640b827e449609b6082d14eb3"},{"relativePath":"source.test.ts","role":"checks","syntaxLanguage":"typescript","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {project} from './source.ts';\ntest('late snapshot cannot overwrite latest', (): void => {const latest=project(undefined,{id:'c1',version:3,name:'New'});assert.equal(project(latest,{id:'c1',version:2,name:'Old'}).name,'New');});\ntest('duplicate is unchanged', (): void => {const row={id:'c1',version:3,name:'New'};assert.equal(project(row,{...row}),row);});\ntest('new version applies and invalid input fails', (): void => {assert.equal(project({id:'c1',version:1,name:'Old'},{id:'c1',version:2,name:'New'}).version,2);assert.throws(()=>project(undefined,{id:'c1',version:0,name:'Bad'}));});\n","sha256":"848304cf625b56f175f1d9fb0a66f71724b9b0ae2ab6a3b9be4f7167689162d7"}],"checks":[{"id":"cqrs-read-models--r1--practice-ordering--node-tests","runner":"node-test","entrypoint":"source.test.ts","expectedExitCode":0,"scope":"educational-local-model","runtime":"Node.js 24","executionStatus":"passed"}]}}],"id":"8-practice"},{"title":"A new situation","phase":"apply","sortIndex":9,"body":"Close the solution before starting. If you use hints, the system should still record your attempt and label it as assisted.","activities":[{"id":"cqrs-read-models--r1--transfer-inventory","kind":"exercise","prompt":"Product search tolerates a three-second delay, but purchase confirmation must not oversell inventory. Propose read and write paths for both use cases, read-your-writes behavior and a plan for a ten-minute projector outage.","stableKey":"transfer-inventory","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism","cqrs-read-models--r1--application","cqrs-read-models--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"cqrs-read-models--r1--transfer-inventory--criterion-0","criterion":"Requested result","expectedEvidence":"The write authority decides inventory at purchase time, not an old search projection.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"cqrs-read-models--r1--transfer-inventory--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Explain post-command or version-based display and the search delay policy.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"cqrs-read-models--r1--transfer-inventory--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Plan for lag, backlog, projector recovery and rebuilding sources; consider one store if sufficient.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"Search can use a delayed read model. Purchase confirmation must check and modify inventory at the write authority using appropriate concurrency control, rather than relying on an old search projection. The UI can use the command result or version for the recent action. A stopped projector leaves search data old: measure lag, communicate the state, retain events or outbox data for catch-up and plan snapshot rebuilding. A small application may need only separate models in one database.","sampleAnswer":"Search can use a delayed read model. Purchase confirmation must check and modify inventory at the write authority using appropriate concurrency control, rather than relying on an old search projection. The UI can use the command result or version for the recent action. A stopped projector leaves search data old: measure lag, communicate the state, retain events or outbox data for catch-up and plan snapshot rebuilding. A small application may need only separate models in one database.","misconception":"Two databases mean CQRS and every CRUD app needs a broker.; HTTP success means the projection is updated.; ID-based upsert handles every ordering problem and an acknowledged queue is an event archive."},"exercise":{"submissionInstructions":"Product search tolerates a three-second delay, but purchase confirmation must not oversell inventory. Propose read and write paths for both use cases, read-your-writes behavior and a plan for a ten-minute projector outage.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works."}}],"id":"9-transfer"},{"title":"Interview again and explain your reasoning","phase":"reflect","sortIndex":10,"body":"CQRS helps match models to responsibilities. When you synchronize separate stores asynchronously, you must explain every gap between writing and reading, both during normal operation and when a step fails.\n\nAI should return criterion-level results and quote evidence from your submission. While grading is pending, the state remains pending; you can continue reading and return later. Interview scores do not increase merely because an answer is longer.","activities":[{"id":"cqrs-read-models--r1--final-interview","kind":"explain","prompt":"Design profile writes and search reads. Why might the old name appear after a successful write? Identify a failure that prevents the read model from ever catching up without a repair mechanism.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["cqrs-read-models--r1--mechanism","cqrs-read-models--r1--application","cqrs-read-models--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"cqrs-read-models--r1--final-interview--criterion-0","criterion":"Responsibilities and trade-offs","expectedEvidence":"Distinguish commands and queries; separate them for concrete needs rather than database count.","misconception":"Two databases mean CQRS and every CRUD app needs a broker.","maxScore":2},{"id":"cqrs-read-models--r1--final-interview--criterion-1","criterion":"Synchronization path","expectedEvidence":"Describe commit, event transfer, projection and reading; identify a window for event loss or stale reads.","misconception":"HTTP success means the projection is updated.","maxScore":2},{"id":"cqrs-read-models--r1--final-interview--criterion-2","criterion":"Reliability and limitations","expectedEvidence":"Distinguish duplicates from old events; explain atomic version checks, rebuilding sources and evidence limits.","misconception":"ID-based upsert handles every ordering problem and an acknowledged queue is an event archive.","maxScore":2}],"answer":{"explanation":"Commands protect invariants and save state in the write model; queries use a read model optimized for search. With asynchronous synchronization, commit can finish before a consumer updates the read model, so an old read does not itself prove a failed write. A crash between commit and publish can permanently lose a notification; a transactional outbox and retrying relay address that gap. Consumers must tolerate redelivery, reject old snapshots with atomic version checks and have a snapshot or event archive for rebuilding. Use CQRS when modeling and query benefits justify these costs.","sampleAnswer":"Commands protect invariants and save state in the write model; queries use a read model optimized for search. With asynchronous synchronization, commit can finish before a consumer updates the read model, so an old read does not itself prove a failed write. A crash between commit and publish can permanently lose a notification; a transactional outbox and retrying relay address that gap. Consumers must tolerate redelivery, reject old snapshots with atomic version checks and have a snapshot or event archive for rebuilding. Use CQRS when modeling and query benefits justify these costs.","misconception":"Two databases mean CQRS and every CRUD app needs a broker.; HTTP success means the projection is updated.; ID-based upsert handles every ordering problem and an acknowledged queue is an event archive."}}],"id":"10-reflection"}]}},"workspace":{"runtime":"Node.js 24","files":[{"path":"workspace/source.test.ts","role":"test"},{"path":"workspace/source.ts","role":"source"}],"commands":{"windows":"node --test workspace/source.test.ts","unix":"node --test workspace/source.test.ts"}},"files":[{"path":"workspace/source.test.ts","role":"test","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {project} from './source.ts';\ntest('late snapshot cannot overwrite latest', (): void => {const latest=project(undefined,{id:'c1',version:3,name:'New'});assert.equal(project(latest,{id:'c1',version:2,name:'Old'}).name,'New');});\ntest('duplicate is unchanged', (): void => {const row={id:'c1',version:3,name:'New'};assert.equal(project(row,{...row}),row);});\ntest('new version applies and invalid input fails', (): void => {assert.equal(project({id:'c1',version:1,name:'Old'},{id:'c1',version:2,name:'New'}).version,2);assert.throws(()=>project(undefined,{id:'c1',version:0,name:'Bad'}));});\n"},{"path":"workspace/source.ts","role":"source","content":"/** Projection snapshot có version trong bộ nhớ. (EN: In-memory versioned snapshot projection.) */\ntype Snapshot = { id: string; version: number; name: string };\n/** Áp snapshot mới hơn; mô hình tuần tự, chưa có distributed CAS. (EN: Sequential model, not distributed CAS.) */\nexport function project(current: Snapshot | undefined, incoming: Snapshot): Snapshot {\n    if (!Number.isSafeInteger(incoming.version) || incoming.version < 1) throw new Error('invalid version');\n    if (current && current.id !== incoming.id) throw new Error('different entity');\n    if (current && incoming.version <= current.version) return current;\n    return {...incoming};\n}\n"}]}$lesson$::jsonb,
    '2026-11-08T00:00:00Z'
) ON CONFLICT DO NOTHING;
