    $lesson${"vi":"Unit testing — test xanh phải bảo vệ được hành vi","en":"Unit testing — passing tests must protect behavior"}$lesson$::jsonb,
    $lesson${"vi":"Unit testing kiểm một đơn vị hành vi với đầu vào và dependency được kiểm soát để phát hiện sai lệch so với yêu cầu.","en":"Unit testing checks a unit of behavior with controlled inputs and dependencies to detect departures from its requirements."}$lesson$::jsonb,
    $lesson${"en.md":"021e1e8bee80069e4700116f51dc9477b5255a4d986ae59c69581fc3634449c4","sections/0-interview/en.md":"8fae8285f56462f1c5154bf163fdc94046eb53079d88f5abe9fd24e2dd211652","sections/0-interview/vi.md":"1daaf361ebe2c472297bc4a5f2ed1a7308982e362bdfd00417c4b43249cabb94","sections/1-prediction/en.md":"48f8bd4020ff7be5a93d360c6018219efae15392d640af3a6b972c31f0aa4c63","sections/1-prediction/vi.md":"e1bf1bcc43a9eb16b7cbd9ce2bb5837e94d8eed5ec28eeff2c8d126b37ac43fb","sections/10-reflection/en.md":"57f685b331dd75f88e8a40fc8ae264feae5509007df052603228f21627c277af","sections/10-reflection/vi.md":"7133e21b2161268c678aa440aa60dd66459a72e3932fd6636677fac30cf1e88d","sections/2-experiment/en.md":"0bffbb66ba0d4463b4f55755f18268d69927917066624eb4b045c83c9936d232","sections/2-experiment/vi.md":"00cba0e7154bca84eef63c2fb3ca895411de294323b53a10e5ba05a2e8e5d723","sections/3-theory-1/en.md":"a0af6758ead7c35e1fa7f28deda1ddf92dd69d014e39682dfb588ac914f951ff","sections/3-theory-1/vi.md":"c2860d115c855b538e28b84c204d123c1d2b5c74c551f1ea606296eac8111f5f","sections/4-theory-2/en.md":"4ea69e5d0bd00a1e6297e499714496079840ca0bcddffcf92335ca478f66daf9","sections/4-theory-2/vi.md":"e4976c960fbfae8f8870f2a79116f6f3e74d9e67915bf660935a834f63ce64ec","sections/5-theory-3/en.md":"571a09bc1d0176c07f64234165cddeccc724b89a6e63c0fb494abfaea874a856","sections/5-theory-3/vi.md":"bbbb08293f46965e4eca3edef0fdfc0a097dbbee58b79cb2c4db736df449bc1c","sections/6-theory-4/en.md":"2925e1630de2b309d2f403e28ac8f12cd6bf7e377685ca3c384d49fd8d804f5c","sections/6-theory-4/vi.md":"4aa55f480cd402b2fa522742bc6441fc2b57e280b54515230635362b05b36525","sections/7-theory-5/en.md":"a975967206433c3aeb602bcccbff22512afc6f122eda8384f077a4dfa4ac3a2c","sections/7-theory-5/vi.md":"a1f5299ee3145363b27db43b49ca773df73e265a7826263993892c8bfe94dc60","sections/8-practice/en.md":"7d82e2230d3847ed9fb4b9703e309bf32fadc757f77f277d9b6997f694d2b7d9","sections/8-practice/vi.md":"061d892cd875314a44faca46a51173549f42354379dca20d551ff5c3d983d13b","sections/9-transfer/en.md":"fef19266aacf33defb123ed87ce69b91ab597f38240cb54a918ab559c54f3e55","sections/9-transfer/vi.md":"d744970aac83b14e972df33748e9ed8634408a7e3b9b02f23f2711a58686c17d","vi.md":"264a33c2957519f2ca6a97169b6de0f603d9234eccd1af5b66ef78d8400c2368","workspace/source.test.ts":"94dfffdc31bfc72fdce06aa0d4af1437472a69aaeae898c82d2b468a41f43b07","workspace/source.ts":"3dc440368960b4ab5fbe6160458f25333b2dac63c4c2fb6347fbdd4cc2768f3e"}$lesson$::jsonb,
    $lesson${"locales":{"vi":{"title":"Unit testing — test xanh phải bảo vệ được hành vi","description":"Unit testing kiểm một đơn vị hành vi với đầu vào và dependency được kiểm soát để phát hiện sai lệch so với yêu cầu.","body":"## Tóm tắt\n\nTest có giá trị khi bảo vệ một lời hứa và đỏ khi lời hứa bị phá. Hãy nhìn vào đầu vào, logic thật, nơi quan sát và lỗi cụ thể mà assertion bắt được trước khi nhìn phần trăm coverage.\n\n## Kết quả học tập\n\n- Phân biệt chạy qua code với kiểm chứng hành vi.\n- Viết kiểm thử giữ logic thật, kiểm kết quả và side effect ở nhánh lỗi.\n- Chứng minh test bắt được lỗi có chủ đích và nêu ranh giới nó chưa bao phủ.\n\n## Kiến thức đầu vào\n\n- Đọc được TypeScript, Promise và throw.\n- Biết service có thể gọi repository để lưu dữ liệu.\n\n## Phạm vi bao gồm\n\n- Arrange–Act–Assert theo hành vi.\n- Fake boundary và kiểm side effect.\n- Nhánh biên, test isolation và thử mutation.\n\n## Phạm vi không bao gồm\n\n- Cài Nest testing container.\n- E2E và coverage dashboard.\n- Framework mocking API chuyên sâu.\n\n## Luận điểm chính\n\n- Coverage đo việc thực thi, không tự đo chất lượng assertion.\n- Mock/fake boundary không được thay luôn logic cần chứng minh.\n- Test độc lập cần kiểm soát clock, state và dependency.\n\n## Điều chỉnh nhận thức\n\n- Bỏ các khẳng định tốc độ runner không có benchmark.\n- clearAllMocks chỉ xóa lịch sử gọi, không reset implementation như nguồn nói.\n- Fake timer không phải mock hệ điều hành; inject clock cũng là lựa chọn hợp lệ.\n- Seed dùng node:test để tập trung nguyên lý TypeScript; không cần dựng Nest/Vitest mới hiểu unit testing.\n\n## Tham khảo\n\n- [vitest.dev/api/vi.html](https://vitest.dev/api/vi.html)\n- [nodejs.org/api/test.html](https://nodejs.org/api/test.html)","learningOutcomes":[{"id":"unit-testing-behavior--r1--mechanism","text":"Phân biệt chạy qua code với kiểm chứng hành vi."},{"id":"unit-testing-behavior--r1--application","text":"Viết kiểm thử giữ logic thật, kiểm kết quả và side effect ở nhánh lỗi."},{"id":"unit-testing-behavior--r1--tradeoffs","text":"Chứng minh test bắt được lỗi có chủ đích và nêu ranh giới nó chưa bao phủ."}],"prerequisites":[{"id":"unit-testing-behavior--r1--input-0","text":"Đọc được TypeScript, Promise và throw."},{"id":"unit-testing-behavior--r1--input-1","text":"Biết service có thể gọi repository để lưu dữ liệu."}],"references":[{"id":"unit-testing-behavior--r1--legacy","label":"Nguồn dữ liệu trước migration","citation":"legacy; courses/0-fullstack-mastery/modules/18-testing-strategy/contents/0-vitest-unit-tests/bodies/0-typescript/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 9a00cc4239a09fb5d27a530fd557fccd4da375180d0481a40578b6cda6c4299f; checked 2026-09-05; Bài mẫu V2 mới; không sửa V1."},{"id":"unit-testing-behavior--r1--official-0","label":"vitest.dev/api/vi.html","url":"https://vitest.dev/api/vi.html","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."},{"id":"unit-testing-behavior--r1--official-1","label":"nodejs.org/api/test.html","url":"https://nodejs.org/api/test.html","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."}],"retrieval":[{"id":"unit-testing-behavior--r1--retrieval-1","kind":"retrieval","prompt":"Một ngày: test chỉ assert save được gọi một lần. Nó có bắt được tổng tiền sai không? Bổ sung một assertion và nói giới hạn.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism"],"afterDays":1,"rubric":[{"id":"unit-testing-behavior--r1--retrieval-1--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Không; assert payload totalCents theo yêu cầu. Vẫn chưa kiểm được DB lưu/mapping thật.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Không; assert payload totalCents theo yêu cầu. Vẫn chưa kiểm được DB lưu/mapping thật.","sampleAnswer":"Không; assert payload totalCents theo yêu cầu. Vẫn chưa kiểm được DB lưu/mapping thật.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"unit-testing-behavior--r1--retrieval-2","kind":"retrieval","prompt":"Một tuần: test hôm nay xanh, ngày mai đỏ vì voucher hết hạn. Sửa thiết kế test thế nào mà vẫn kiểm đúng biên?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--application"],"afterDays":7,"rubric":[{"id":"unit-testing-behavior--r1--retrieval-2--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Truyền now cố định hoặc clock kiểm soát; kiểm trước/bằng/sau expiresAt và saveCount. Không kéo dài voucher ngẫu nhiên để che phụ thuộc thời gian.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Truyền now cố định hoặc clock kiểm soát; kiểm trước/bằng/sau expiresAt và saveCount. Không kéo dài voucher ngẫu nhiên để che phụ thuộc thời gian.","sampleAnswer":"Truyền now cố định hoặc clock kiểm soát; kiểm trước/bằng/sau expiresAt và saveCount. Không kéo dài voucher ngẫu nhiên để che phụ thuộc thời gian.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"unit-testing-behavior--r1--retrieval-3","kind":"retrieval","prompt":"21 ngày: refactor tách helper làm nhiều test đỏ dù API đúng. Khi nào nên sửa test, khi nào sửa code?","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"unit-testing-behavior--r1--retrieval-3--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Nếu test khóa thứ tự gọi private helper không thuộc contract, sửa test để quan sát output/side effect. Nếu invariant hoặc boundary contract đã đổi sai thì sửa code; dùng case nghiệp vụ và integration phù hợp để phân biệt.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Nếu test khóa thứ tự gọi private helper không thuộc contract, sửa test để quan sát output/side effect. Nếu invariant hoặc boundary contract đã đổi sai thì sửa code; dùng case nghiệp vụ và integration phù hợp để phân biệt.","sampleAnswer":"Nếu test khóa thứ tự gọi private helper không thuộc contract, sửa test để quan sát output/side effect. Nếu invariant hoặc boundary contract đã đổi sai thì sửa code; dùng case nghiệp vụ và integration phù hợp để phân biệt.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}}],"sections":[{"title":"Bối cảnh phỏng vấn","phase":"challenge","sortIndex":0,"body":"Trong phỏng vấn Testing, interviewer đưa một incident: đơn hàng 3 sản phẩm, mỗi sản phẩm 1.500 cent, lại lưu tổng 1.503 cent. CI vẫn xanh. Bạn mở test: fake repository luôn trả một đơn hàng có tổng 4.500, và test chỉ so sánh kết quả với chính đơn hàng giả đó. “Bộ test đang chứng minh phép tính hay đang chứng minh fake trả đúng thứ được dặn?”\n\nTrả lời câu hỏi bằng suy nghĩ hiện tại. Đây là lần chẩn đoán đầu vào, chưa tính đạt đầu ra. Bạn sẽ trả lời lại sau khi thực hành; bài vẫn mở nếu bạn chưa biết đáp án.","activities":[{"id":"unit-testing-behavior--r1--opening-interview","kind":"explain","prompt":"Giải thích vì sao test trên không bắt lỗi cộng thay vì nhân. Thiết kế test kiểm được tổng tiền và bảo đảm quantity=0 không ghi repository.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism","unit-testing-behavior--r1--application","unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"unit-testing-behavior--r1--opening-interview--criterion-0","criterion":"Hành vi cần bảo vệ","expectedEvidence":"Assert tổng tiền đúng và không ghi khi input sai; dùng expected từ yêu cầu.","misconception":"Chỉ cần hàm đã được gọi hoặc result truthy.","maxScore":2},{"id":"unit-testing-behavior--r1--opening-interview--criterion-1","criterion":"Ranh giới unit","expectedEvidence":"Chạy logic thật, thay dependency I/O bằng fake có kiểm soát.","misconception":"Mock luôn hàm đang cần kiểm tra.","maxScore":2},{"id":"unit-testing-behavior--r1--opening-interview--criterion-2","criterion":"Độ nhạy với lỗi","expectedEvidence":"Chỉ ra thay đổi sai làm test fail và giới hạn integration chưa kiểm.","misconception":"Coverage cao hoặc một test xanh chứng minh mọi tầng đúng.","maxScore":2}],"answer":{"explanation":"Fake trả sẵn kết quả đúng có thể che lỗi payload mà service gửi vào. Tôi giữ createOrder thật, dùng fake ghi lại tham số save và trả chính tham số đó. Với quantity=3, unitPriceCents=1500, assert totalCents=4500. Với quantity=0, assert reject và số lần save bằng 0. Sau đó đổi phép nhân thành cộng để chắc test đúng hành vi thất bại. Các test này chưa chứng minh transaction hay schema database thật.","sampleAnswer":"Fake trả sẵn kết quả đúng có thể che lỗi payload mà service gửi vào. Tôi giữ createOrder thật, dùng fake ghi lại tham số save và trả chính tham số đó. Với quantity=3, unitPriceCents=1500, assert totalCents=4500. Với quantity=0, assert reject và số lần save bằng 0. Sau đó đổi phép nhân thành cộng để chắc test đúng hành vi thất bại. Các test này chưa chứng minh transaction hay schema database thật.","misconception":"Chỉ cần hàm đã được gọi hoặc result truthy.; Mock luôn hàm đang cần kiểm tra.; Coverage cao hoặc một test xanh chứng minh mọi tầng đúng."}}],"id":"0-interview"},{"title":"Dự đoán trước khi quan sát","phase":"predict","sortIndex":1,"body":"Service bị sửa total = quantity + unitPriceCents. Fake save bỏ qua input và luôn trả fixture đúng. Test chỉ assert result bằng fixture.","activities":[{"id":"unit-testing-behavior--r1--predict-fake","kind":"choice","prompt":"Test này có thể vẫn xanh không?","stableKey":"predict-fake","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Cần assertion tại nơi hành vi sai có thể quan sát được.","misconception":"Không, line coverage sẽ phát hiện phép cộng; Không, TypeScript phân biệt phép cộng sai nghiệp vụ"},"options":[{"id":"unit-testing-behavior--r1--predict-fake--option-1","label":"Có, vì fake đã che phần tính sai","explanation":"Đúng: test không quan sát payload thật đi vào boundary.","isCorrect":true},{"id":"unit-testing-behavior--r1--predict-fake--option-2","label":"Không, line coverage sẽ phát hiện phép cộng","explanation":"Sai: coverage không kiểm giá trị nghiệp vụ.","isCorrect":false},{"id":"unit-testing-behavior--r1--predict-fake--option-3","label":"Không, TypeScript phân biệt phép cộng sai nghiệp vụ","explanation":"Sai: cả cộng và nhân đều hợp lệ về kiểu number.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Thử và quan sát","phase":"explore","sortIndex":2,"body":"Mô phỏng cho bạn chọn cách quan sát service. Trước tiên chạy test yếu với implementation sai, rồi thay fake để trả/ghi nhận input thật và thêm assertion theo yêu cầu. Mục tiêu là nhìn thấy test đỏ đúng nguyên nhân trước khi sửa logic.\n\n**Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.**\n\n```mermaid\nflowchart LR\n T[Test input] --> S[Real createOrder]\n S -->|calculated payload| F[Fake repository]\n F -->|echo payload| O[Observed result]\n R[Business requirement 3 x 1500 = 4500] --> A[Assertion]\n O --> A\n```\n\n> Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.","activities":[{"id":"unit-testing-behavior--r1--exploration","kind":"simulation","prompt":"Thử đường sai trước, đọc trạng thái quan sát được, sau đó tìm đường giải quyết. Kết thúc bằng câu giải thích nguyên nhân.","stableKey":"exploration","outcomeIds":["unit-testing-behavior--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"unit-testing-behavior--r1--exploration--state-weak","debriefQuestion":"Vì sao cần giữ cùng assertion khi sửa implementation? Nếu đổi expected thành 1503 thì bạn đã thay đổi điều gì?","states":[{"id":"unit-testing-behavior--r1--exploration--state-weak","label":"Test yếu","observation":"Service dùng cộng; fake trả fixture 4500; test xanh.","isSuccess":false},{"id":"unit-testing-behavior--r1--exploration--state-observed","label":"Quan sát payload thật","observation":"Fake echo input; test so total với 4500; test đỏ vì nhận 1503.","isSuccess":false},{"id":"unit-testing-behavior--r1--exploration--state-fixed","label":"Sửa nghiệp vụ","observation":"Đổi cộng thành nhân; cùng test xanh.","isSuccess":false},{"id":"unit-testing-behavior--r1--exploration--state-boundary","label":"Kiểm nhánh lỗi","observation":"quantity=0 bị reject; saveCount=0.","isSuccess":true}],"actions":[{"id":"unit-testing-behavior--r1--exploration--action-observe","label":"Đổi fake và assertion"},{"id":"unit-testing-behavior--r1--exploration--action-fix","label":"Sửa phép tính"},{"id":"unit-testing-behavior--r1--exploration--action-invalid","label":"Thêm case quantity=0"}],"transitions":[{"id":"unit-testing-behavior--r1--exploration--transition-0","fromStateId":"unit-testing-behavior--r1--exploration--state-weak","actionId":"unit-testing-behavior--r1--exploration--action-observe","toStateId":"unit-testing-behavior--r1--exploration--state-observed"},{"id":"unit-testing-behavior--r1--exploration--transition-1","fromStateId":"unit-testing-behavior--r1--exploration--state-observed","actionId":"unit-testing-behavior--r1--exploration--action-fix","toStateId":"unit-testing-behavior--r1--exploration--state-fixed"},{"id":"unit-testing-behavior--r1--exploration--transition-2","fromStateId":"unit-testing-behavior--r1--exploration--state-fixed","actionId":"unit-testing-behavior--r1--exploration--action-invalid","toStateId":"unit-testing-behavior--r1--exploration--state-boundary"}]}}],"id":"2-experiment"},{"title":"Bắt đầu từ lời hứa của hàm","phase":"explain","sortIndex":3,"body":"Trước khi viết test, viết một câu: “Với số lượng nguyên dương và đơn giá hợp lệ, đơn hàng lưu tổng bằng số lượng nhân đơn giá; input sai không được lưu.” Câu này là contract. Nó cho bạn cả kết quả cần thấy và tác dụng phụ không được xảy ra. Nếu bắt đầu từ danh sách method trong class, bạn dễ viết một test cho mỗi tên hàm mà bỏ qua hành vi quan trọng.\n\nArrange chuẩn bị input và dependency; Act gọi hành vi thật; Assert so kết quả với contract. Expected 4500 đến từ yêu cầu 3 × 1500, không nên được tính lại bằng cách copy nguyên công thức implementation vào test. Nếu cả hai cùng sai một phép toán, test có thể xanh mà không bảo vệ gì.","id":"3-theory-1"},{"title":"Cô lập dependency, không cô lập mất hành vi","phase":"explain","sortIndex":4,"body":"Unit không bắt buộc là đúng một method. Trong bài, đơn vị cần bảo vệ là quyết định tính tiền và gọi lưu của createOrder. Repository là boundary I/O, được thay bằng fake nhỏ để test không phụ thuộc database. Helper tính tiền nếu là một phần logic cần kiểm nên chạy thật. Mock luôn createOrder rồi kiểm nó trả fixture chỉ kiểm cách bạn cấu hình mock.\n\nFake echo payload có ích vì không tự sửa kết quả hộ service. Nhưng fake cũng chỉ đại diện một contract hẹp; nó không chứng minh database có unique constraint, transaction đúng hay mapping cột đúng. Những rủi ro đó cần integration test riêng. Test unit tốt nói rõ điều đã chứng minh và điều chưa chứng minh.\n\nKhi side effect là phần contract, kiểm lời gọi có giá trị. quantity=0 không được lưu là yêu cầu nghiệp vụ có thể quan sát bằng saveCount=0. Ngược lại, assert mỗi private helper gọi đúng một lần chỉ vì hiện implementation làm vậy khiến refactor hợp lệ cũng làm test đỏ.","id":"4-theory-2"},{"title":"Chọn case làm lộ khác biệt","phase":"explain","sortIndex":5,"body":"**Chọn case từ các phân vùng hành vi, không từ một số lượng test cố định.**\n\n| Case | Kết quả cần thấy | Lỗi có thể phát hiện |\n| --- | --- | --- |\n| 3 × 1500 | 4500 cent | Cộng thay vì nhân |\n| quantity=0 hoặc -1 | Reject, không save | Thiếu kiểm invariant |\n| quantity=1.5 | Reject | Cho phép số lượng lẻ ngoài contract |\n| Giá âm hoặc NaN | Reject | Validation chỉ kiểm một phía |\n| Tổng vượt safe integer | Reject | Mất chính xác số nguyên |\n| Repository từ chối | Promise reject | Nuốt lỗi và báo thành công giả |\n\nCode dùng cent nguyên để bỏ nhiễu số thập phân trong ví dụ, không tuyên bố giải hết tiền tệ đa currency và rounding. quantity=1 đôi khi không phân biệt được các lỗi bạn định bắt; case 3 và 1500 cho thấy phép cộng khác phép nhân rõ ràng. Với mỗi test, hãy tự hỏi: implementation sai nào sẽ làm nó đỏ?","id":"5-theory-3"},{"title":"Giữ mỗi lần chạy độc lập","phase":"explain","sortIndex":6,"body":"Một test phụ thuộc đồng hồ thật, thứ tự chạy hoặc state do test trước để lại có thể đổi kết quả mà code không đổi. Tạo fake mới cho mỗi test. Nếu cần thời gian, truyền clock hoặc dùng fake timers và phục hồi sau test. Dùng múi giờ rõ trong case ngày tháng để tránh test chỉ xanh trên máy người viết.\n\nTrong Vitest, xóa lịch sử gọi không đồng nghĩa xóa implementation giả. Vì vậy cần phân biệt clear, reset và restore khi dùng mock; tạo fake mới thường là cách dễ hiểu cho bài nhập môn. Với async, phải await hành vi và assertion rejection, nếu không test có thể kết thúc trước khi lỗi xảy ra.\n\n**source.ts là logic thật được kiểm; save được truyền vào để giữ I/O trong tầm kiểm soát.**\n\n```typescript\n/** Đặt hàng với repository truyền vào để kiểm soát I/O. (EN: Order logic with an injected I/O boundary.) */\ntype Draft = {quantity: number; unitPriceCents: number};\ntype Order = Draft & {totalCents: number};\ntype Save = (order: Order) => Promise<Order>;\n/** Kiểm invariant trước khi lưu, tiền dùng đơn vị cent nguyên. (EN: Validate before save; use integer cents.) */\nexport async function createOrder(draft: Draft, save: Save): Promise<Order> {\n    if (!Number.isSafeInteger(draft.quantity) || draft.quantity <= 0) throw new Error('invalid quantity');\n    if (!Number.isSafeInteger(draft.unitPriceCents) || draft.unitPriceCents < 0) throw new Error('invalid price');\n    const totalCents = draft.quantity * draft.unitPriceCents;\n    if (!Number.isSafeInteger(totalCents)) throw new Error('unsafe total');\n    return save({...draft,totalCents});\n}\n```","id":"6-theory-4"},{"title":"Test xanh là điểm bắt đầu để chất vấn","phase":"explain","sortIndex":7,"body":"Coverage cho biết vùng code đã được đi qua. Nó giúp tìm vùng chưa chạm tới, nhưng không bảo đảm assertion bắt lỗi. Một phép kiểm hữu ích là mutation nhỏ: đổi nhân thành cộng, bỏ một guard hoặc nuốt lỗi save. Nếu test phù hợp vẫn xanh, xem lại contract hoặc độ quan sát của assertion.\n\nKhông cần tiêu diệt mọi mutation để gọi một bộ test có ích: có mutation tương đương hoặc nằm ngoài contract. Giá trị nằm ở việc lỗi nghiệp vụ quan trọng bị phát hiện nhanh, ổn định và dễ hiểu. Cũng không cần bắt test unit gánh mọi rủi ro; bổ sung integration/E2E ở boundary có khả năng sai thật.","activities":[{"id":"unit-testing-behavior--r1--quiz-assert","kind":"choice","prompt":"Assertion nào trực tiếp bảo vệ yêu cầu input sai không tạo đơn?","stableKey":"quiz-assert","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--application"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Một nhánh lỗi có thể vừa ném lỗi vừa đã lưu sai; chỉ assert throw chưa đủ.","misconception":"result không null; Service class có method createOrder"},"options":[{"id":"unit-testing-behavior--r1--quiz-assert--option-1","label":"result không null","explanation":"Sai: không quan sát side effect.","isCorrect":false},{"id":"unit-testing-behavior--r1--quiz-assert--option-2","label":"Promise reject và save chưa được gọi","explanation":"Đúng: kiểm cả phản hồi và tác động không được phép.","isCorrect":true},{"id":"unit-testing-behavior--r1--quiz-assert--option-3","label":"Service class có method createOrder","explanation":"Sai: có method không nói hành vi đúng.","isCorrect":false}]},{"id":"unit-testing-behavior--r1--quiz-coverage","kind":"choice","prompt":"100% line coverage chứng minh điều gì?","stableKey":"quiz-coverage","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":1,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Đọc metric theo chính điều nó đo.","misconception":"Mọi invariant đã được kiểm; Database thật tương thích với fake"},"options":[{"id":"unit-testing-behavior--r1--quiz-coverage--option-1","label":"Mọi invariant đã được kiểm","explanation":"Sai: chạy một dòng không nói assertion đủ.","isCorrect":false},{"id":"unit-testing-behavior--r1--quiz-coverage--option-2","label":"Các dòng được công cụ đo đã chạy trong bộ test","explanation":"Đúng: đây là phạm vi thực sự của số đo.","isCorrect":true},{"id":"unit-testing-behavior--r1--quiz-coverage--option-3","label":"Database thật tương thích với fake","explanation":"Sai: cần integration proof.","isCorrect":false}]}],"id":"7-theory-5"},{"title":"Thực hành có bằng chứng","phase":"apply","sortIndex":8,"body":"Chạy bộ test đi kèm bằng Node.js 24. Không có database, không cần cài runner. Sau khi thấy xanh, tạo một bản sao source trong thư mục làm bài, đổi phép nhân thành cộng và chạy lại để tạo bằng chứng đỏ.\n\n**Windows PowerShell.**\n\n```powershell\nnode --test source.test.ts\n```\n\n**macOS/Linux.**\n\n```bash\nnode --test source.test.ts\n```\n\nNộp output test trước/sau mutation và đoạn assertion bắt lỗi. Phục hồi source rồi chạy lại. Không sửa expected để khớp kết quả sai. Đây là thực hành sửa code thật, không phải nút “đã hiểu”.","activities":[{"id":"unit-testing-behavior--r1--practice-mutation","kind":"exercise","prompt":"Thực hiện mutation nhân thành cộng. Sau đó thêm test cho quantity=1.5 và repository reject. Nộp patch, log đỏ/xanh và một câu cho mỗi test: nó bảo vệ lời hứa nào?","stableKey":"practice-mutation","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism","unit-testing-behavior--r1--application","unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"unit-testing-behavior--r1--practice-mutation--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Test tổng tiền đỏ với phép cộng và xanh sau phục hồi, giữ expected theo contract.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"unit-testing-behavior--r1--practice-mutation--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Thêm test số lượng lẻ không save và repository reject được truyền ra.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"unit-testing-behavior--r1--practice-mutation--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Giải thích lời hứa mỗi test bảo vệ và giới hạn database integration chưa kiểm.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"Case tổng tiền bắt phép cộng; case quantity lẻ kiểm contract số nguyên và không save; fake save reject kiểm lỗi được truyền ra thay vì thành công giả. Giữ fake mới từng test và await assertion. Các test này không nói gì về transaction database thật.","sampleAnswer":"Case tổng tiền bắt phép cộng; case quantity lẻ kiểm contract số nguyên và không save; fake save reject kiểm lỗi được truyền ra thay vì thành công giả. Giữ fake mới từng test và await assertion. Các test này không nói gì về transaction database thật.","misconception":"Chỉ cần hàm đã được gọi hoặc result truthy.; Mock luôn hàm đang cần kiểm tra.; Coverage cao hoặc một test xanh chứng minh mọi tầng đúng."},"exercise":{"submissionInstructions":"Thực hiện mutation nhân thành cộng. Sau đó thêm test cho quantity=1.5 và repository reject. Nộp patch, log đỏ/xanh và một câu cho mỗi test: nó bảo vệ lời hứa nào?","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production.","files":[{"relativePath":"source.ts","role":"reference","syntaxLanguage":"typescript","content":"/** Đặt hàng với repository truyền vào để kiểm soát I/O. (EN: Order logic with an injected I/O boundary.) */\ntype Draft = {quantity: number; unitPriceCents: number};\ntype Order = Draft & {totalCents: number};\ntype Save = (order: Order) => Promise<Order>;\n/** Kiểm invariant trước khi lưu, tiền dùng đơn vị cent nguyên. (EN: Validate before save; use integer cents.) */\nexport async function createOrder(draft: Draft, save: Save): Promise<Order> {\n    if (!Number.isSafeInteger(draft.quantity) || draft.quantity <= 0) throw new Error('invalid quantity');\n    if (!Number.isSafeInteger(draft.unitPriceCents) || draft.unitPriceCents < 0) throw new Error('invalid price');\n    const totalCents = draft.quantity * draft.unitPriceCents;\n    if (!Number.isSafeInteger(totalCents)) throw new Error('unsafe total');\n    return save({...draft,totalCents});\n}\n","sha256":"3dc440368960b4ab5fbe6160458f25333b2dac63c4c2fb6347fbdd4cc2768f3e"},{"relativePath":"source.test.ts","role":"checks","syntaxLanguage":"typescript","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {createOrder} from './source.ts';\ntest('calculates payload from business requirement', async (): Promise<void> => {const result=await createOrder({quantity:3,unitPriceCents:1500},async (row)=>row);assert.equal(result.totalCents,4500);});\ntest('invalid quantity never writes', async (): Promise<void> => {let calls=0;await assert.rejects(()=>createOrder({quantity:0,unitPriceCents:1500},async (row)=>{calls++;return row;}),/quantity/);assert.equal(calls,0);});\ntest('invalid price and unsafe total reject', async (): Promise<void> => {await assert.rejects(()=>createOrder({quantity:1,unitPriceCents:NaN},async(row)=>row));await assert.rejects(()=>createOrder({quantity:2,unitPriceCents:Number.MAX_SAFE_INTEGER},async(row)=>row));});\n","sha256":"94dfffdc31bfc72fdce06aa0d4af1437472a69aaeae898c82d2b468a41f43b07"}],"checks":[{"id":"unit-testing-behavior--r1--practice-mutation--node-tests","runner":"node-test","entrypoint":"source.test.ts","expectedExitCode":0,"scope":"educational-local-model","runtime":"Node.js 24","executionStatus":"passed"}]}}],"id":"8-practice"},{"title":"Tình huống mới","phase":"apply","sortIndex":9,"body":"Đóng lời giải trước khi làm. Nếu dùng gợi ý, hệ thống vẫn ghi nhận bài làm nhưng gắn nhãn có hỗ trợ.","activities":[{"id":"unit-testing-behavior--r1--transfer-expiry","kind":"exercise","prompt":"Voucher hết hạn tại đúng expiresAt. Hàm applyVoucher nhận now và gọi saveDiscount. Thiết kế ba case quanh mốc hết hạn, cách kiểm side effect và một mutation mà bộ test phải bắt.","stableKey":"transfer-expiry","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism","unit-testing-behavior--r1--application","unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"unit-testing-behavior--r1--transfer-expiry--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Chốt rõ now >= expiresAt bị từ chối và case trước/bằng/sau mốc.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"unit-testing-behavior--r1--transfer-expiry--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Kiểm không save ở hai case hết hạn; kiểm có save ở case trước mốc.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"unit-testing-behavior--r1--transfer-expiry--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Kiểm soát now; mutation >= thành > phải bị case đúng mốc bắt, không dựa clock thật.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"Chốt contract now >= expiresAt là hết hạn. Test expiresAt-1 được lưu, bằng mốc và sau mốc bị từ chối không save. Truyền now cố định để không phụ thuộc clock thật. Mutation >= thành > phải làm case đúng mốc đỏ. Còn timezone parsing thuộc boundary khác cần kiểm riêng.","sampleAnswer":"Chốt contract now >= expiresAt là hết hạn. Test expiresAt-1 được lưu, bằng mốc và sau mốc bị từ chối không save. Truyền now cố định để không phụ thuộc clock thật. Mutation >= thành > phải làm case đúng mốc đỏ. Còn timezone parsing thuộc boundary khác cần kiểm riêng.","misconception":"Chỉ cần hàm đã được gọi hoặc result truthy.; Mock luôn hàm đang cần kiểm tra.; Coverage cao hoặc một test xanh chứng minh mọi tầng đúng."},"exercise":{"submissionInstructions":"Voucher hết hạn tại đúng expiresAt. Hàm applyVoucher nhận now và gọi saveDiscount. Thiết kế ba case quanh mốc hết hạn, cách kiểm side effect và một mutation mà bộ test phải bắt.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production."}}],"id":"9-transfer"},{"title":"Phỏng vấn lại và tự giải thích","phase":"reflect","sortIndex":10,"body":"Test có giá trị khi bảo vệ một lời hứa và đỏ khi lời hứa bị phá. Hãy nhìn vào đầu vào, logic thật, nơi quan sát và lỗi cụ thể mà assertion bắt được trước khi nhìn phần trăm coverage.\n\nAI trả kết quả theo từng tiêu chí và trích đoạn bài nộp làm bằng chứng. Khi chấm chưa xong, trạng thái là đang chấm; bạn có thể tiếp tục đọc và quay lại. Điểm phỏng vấn không tăng chỉ vì câu trả lời dài.","activities":[{"id":"unit-testing-behavior--r1--final-interview","kind":"explain","prompt":"Giải thích vì sao test trên không bắt lỗi cộng thay vì nhân. Thiết kế test kiểm được tổng tiền và bảo đảm quantity=0 không ghi repository.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism","unit-testing-behavior--r1--application","unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"unit-testing-behavior--r1--final-interview--criterion-0","criterion":"Hành vi cần bảo vệ","expectedEvidence":"Assert tổng tiền đúng và không ghi khi input sai; dùng expected từ yêu cầu.","misconception":"Chỉ cần hàm đã được gọi hoặc result truthy.","maxScore":2},{"id":"unit-testing-behavior--r1--final-interview--criterion-1","criterion":"Ranh giới unit","expectedEvidence":"Chạy logic thật, thay dependency I/O bằng fake có kiểm soát.","misconception":"Mock luôn hàm đang cần kiểm tra.","maxScore":2},{"id":"unit-testing-behavior--r1--final-interview--criterion-2","criterion":"Độ nhạy với lỗi","expectedEvidence":"Chỉ ra thay đổi sai làm test fail và giới hạn integration chưa kiểm.","misconception":"Coverage cao hoặc một test xanh chứng minh mọi tầng đúng.","maxScore":2}],"answer":{"explanation":"Fake trả sẵn kết quả đúng có thể che lỗi payload mà service gửi vào. Tôi giữ createOrder thật, dùng fake ghi lại tham số save và trả chính tham số đó. Với quantity=3, unitPriceCents=1500, assert totalCents=4500. Với quantity=0, assert reject và số lần save bằng 0. Sau đó đổi phép nhân thành cộng để chắc test đúng hành vi thất bại. Các test này chưa chứng minh transaction hay schema database thật.","sampleAnswer":"Fake trả sẵn kết quả đúng có thể che lỗi payload mà service gửi vào. Tôi giữ createOrder thật, dùng fake ghi lại tham số save và trả chính tham số đó. Với quantity=3, unitPriceCents=1500, assert totalCents=4500. Với quantity=0, assert reject và số lần save bằng 0. Sau đó đổi phép nhân thành cộng để chắc test đúng hành vi thất bại. Các test này chưa chứng minh transaction hay schema database thật.","misconception":"Chỉ cần hàm đã được gọi hoặc result truthy.; Mock luôn hàm đang cần kiểm tra.; Coverage cao hoặc một test xanh chứng minh mọi tầng đúng."}}],"id":"10-reflection"}]},"en":{"title":"Unit testing — passing tests must protect behavior","description":"Unit testing checks a unit of behavior with controlled inputs and dependencies to detect departures from its requirements.","body":"## Summary\n\nA test is valuable when it protects a promise and fails when that promise is broken. Examine inputs, real logic, observation points and the defect an assertion catches before looking at coverage percentages.\n\n## Learning outcomes\n\n- Distinguish executing code from verifying behavior.\n- Keep real logic in tests and verify results and side effects on failure paths.\n- Show that tests catch deliberate defects and identify boundaries they do not cover.\n\n## Prerequisites\n\n- Read TypeScript, Promises and thrown errors.\n- Understand that a service may call a repository to persist data.\n\n## Included scope\n\n- Behavior-oriented Arrange–Act–Assert.\n- Fake boundaries and side-effect checks.\n- Edge cases, isolation and deliberate mutations.\n\n## Excluded scope\n\n- Setting up the Nest testing container.\n- E2E tests and coverage dashboards.\n- Advanced framework-specific mocking APIs.\n\n## Key claims\n\n- Coverage measures execution, not assertion quality.\n- Mocking a boundary must not replace the very logic being verified.\n- Independent tests control clocks, state and dependencies.\n\n## Corrections\n\n- Remove runner-speed claims unsupported by benchmarks.\n- clearAllMocks clears call history; it does not reset implementations as the source claims.\n- Fake timers do not mock the operating system; injecting a clock is another valid choice.\n- This seed uses node:test to focus on TypeScript principles; understanding unit testing does not require Nest or Vitest setup.\n\n## References\n\n- [vitest.dev/api/vi.html](https://vitest.dev/api/vi.html)\n- [nodejs.org/api/test.html](https://nodejs.org/api/test.html)","learningOutcomes":[{"id":"unit-testing-behavior--r1--mechanism","text":"Distinguish executing code from verifying behavior."},{"id":"unit-testing-behavior--r1--application","text":"Keep real logic in tests and verify results and side effects on failure paths."},{"id":"unit-testing-behavior--r1--tradeoffs","text":"Show that tests catch deliberate defects and identify boundaries they do not cover."}],"prerequisites":[{"id":"unit-testing-behavior--r1--input-0","text":"Read TypeScript, Promises and thrown errors."},{"id":"unit-testing-behavior--r1--input-1","text":"Understand that a service may call a repository to persist data."}],"references":[{"id":"unit-testing-behavior--r1--legacy","label":"Pre-migration data source","citation":"legacy; courses/0-fullstack-mastery/modules/18-testing-strategy/contents/0-vitest-unit-tests/bodies/0-typescript/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 9a00cc4239a09fb5d27a530fd557fccd4da375180d0481a40578b6cda6c4299f; checked 2026-09-05; New V2 sample; V1 remains unchanged."},{"id":"unit-testing-behavior--r1--official-0","label":"vitest.dev/api/vi.html","url":"https://vitest.dev/api/vi.html","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."},{"id":"unit-testing-behavior--r1--official-1","label":"nodejs.org/api/test.html","url":"https://nodejs.org/api/test.html","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."}],"retrieval":[{"id":"unit-testing-behavior--r1--retrieval-1","kind":"retrieval","prompt":"One day later: a test only asserts that save was called once. Can it catch an incorrect total? Add an assertion and state its limit.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism"],"afterDays":1,"rubric":[{"id":"unit-testing-behavior--r1--retrieval-1--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"No. Assert the payload's totalCents against the requirement. Real database persistence and mapping remain unverified.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"No. Assert the payload's totalCents against the requirement. Real database persistence and mapping remain unverified.","sampleAnswer":"No. Assert the payload's totalCents against the requirement. Real database persistence and mapping remain unverified.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"unit-testing-behavior--r1--retrieval-2","kind":"retrieval","prompt":"One week later: a test passes today and fails tomorrow because a voucher expires. How would you redesign it while preserving boundary checks?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--application"],"afterDays":7,"rubric":[{"id":"unit-testing-behavior--r1--retrieval-2--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"Inject fixed time or a controlled clock; check before, exactly at and after expiresAt, including saveCount. Do not randomly extend voucher lifetime to hide the clock dependency.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"Inject fixed time or a controlled clock; check before, exactly at and after expiresAt, including saveCount. Do not randomly extend voucher lifetime to hide the clock dependency.","sampleAnswer":"Inject fixed time or a controlled clock; check before, exactly at and after expiresAt, including saveCount. Do not randomly extend voucher lifetime to hide the clock dependency.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"unit-testing-behavior--r1--retrieval-3","kind":"retrieval","prompt":"After 21 days: extracting helpers breaks many tests although the API remains correct. When should you change tests, and when should you fix code?","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"unit-testing-behavior--r1--retrieval-3--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"If tests lock in private-helper call order outside the contract, change them to observe outputs and side effects. If an invariant or boundary contract was broken, fix the code. Use business cases and suitable integration checks to distinguish these situations.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"If tests lock in private-helper call order outside the contract, change them to observe outputs and side effects. If an invariant or boundary contract was broken, fix the code. Use business cases and suitable integration checks to distinguish these situations.","sampleAnswer":"If tests lock in private-helper call order outside the contract, change them to observe outputs and side effects. If an invariant or boundary contract was broken, fix the code. Use business cases and suitable integration checks to distinguish these situations.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}}],"sections":[{"title":"Interview context","phase":"challenge","sortIndex":0,"body":"In a testing interview, an incident shows an order for three items at 1,500 cents each saved with a total of 1,503 cents. CI is green. The repository fake always returns an order totaling 4,500, and the test compares the result only with that fixture. 'Does this test prove the calculation, or merely that the fake returns what it was told?'\n\nAnswer using your current understanding. This initial diagnostic does not establish mastery. You will answer again after practice, and the lesson remains open if you do not yet know the answer.","activities":[{"id":"unit-testing-behavior--r1--opening-interview","kind":"explain","prompt":"Explain why the test misses addition in place of multiplication. Design tests for the total and for quantity=0 never reaching repository persistence.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism","unit-testing-behavior--r1--application","unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"unit-testing-behavior--r1--opening-interview--criterion-0","criterion":"Protected behavior","expectedEvidence":"Assert the correct total and no save for invalid input; derive expectations from requirements.","misconception":"A function call or truthy result is sufficient.","maxScore":2},{"id":"unit-testing-behavior--r1--opening-interview--criterion-1","criterion":"Unit boundary","expectedEvidence":"Run real logic and replace the I/O dependency with a controlled fake.","misconception":"Mock the function under test itself.","maxScore":2},{"id":"unit-testing-behavior--r1--opening-interview--criterion-2","criterion":"Defect sensitivity","expectedEvidence":"Identify a wrong change that fails the test and the untested integration boundary.","misconception":"High coverage or one passing test proves every layer correct.","maxScore":2}],"answer":{"explanation":"A fake that always returns the correct fixture can hide a bad payload sent by the service. Keep createOrder real; use a fake that records and returns its save argument. For quantity=3 and unitPriceCents=1500, assert totalCents=4500. For quantity=0, assert rejection and zero save calls. Then change multiplication to addition to confirm the behavioral test fails. These tests do not verify real database transactions or schemas.","sampleAnswer":"A fake that always returns the correct fixture can hide a bad payload sent by the service. Keep createOrder real; use a fake that records and returns its save argument. For quantity=3 and unitPriceCents=1500, assert totalCents=4500. For quantity=0, assert rejection and zero save calls. Then change multiplication to addition to confirm the behavioral test fails. These tests do not verify real database transactions or schemas.","misconception":"A function call or truthy result is sufficient.; Mock the function under test itself.; High coverage or one passing test proves every layer correct."}}],"id":"0-interview"},{"title":"Predict before observing","phase":"predict","sortIndex":1,"body":"The service now calculates total = quantity + unitPriceCents. The save fake ignores input and always returns the correct fixture. The test only compares result with fixture.","activities":[{"id":"unit-testing-behavior--r1--predict-fake","kind":"choice","prompt":"Could this test still pass?","stableKey":"predict-fake","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Place assertions where incorrect behavior can be observed.","misconception":"No, line coverage detects addition; No, TypeScript distinguishes business-invalid addition"},"options":[{"id":"unit-testing-behavior--r1--predict-fake--option-1","label":"Yes, because the fake hides the incorrect calculation","explanation":"Correct: the test never observes the actual payload crossing the boundary.","isCorrect":true},{"id":"unit-testing-behavior--r1--predict-fake--option-2","label":"No, line coverage detects addition","explanation":"Incorrect: coverage does not validate business values.","isCorrect":false},{"id":"unit-testing-behavior--r1--predict-fake--option-3","label":"No, TypeScript distinguishes business-invalid addition","explanation":"Incorrect: both addition and multiplication are valid number operations.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Experiment and observe","phase":"explore","sortIndex":2,"body":"The simulation lets you choose how to observe the service. Run the weak test against the broken implementation, then make the fake return or record real input and assert the requirement. First observe a failure for the right reason; only then fix the logic.\n\n**A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.**\n\n```mermaid\nflowchart LR\n T[Test input] --> S[Real createOrder]\n S -->|calculated payload| F[Fake repository]\n F -->|echo payload| O[Observed result]\n R[Business requirement 3 x 1500 = 4500] --> A[Assertion]\n O --> A\n```\n\n> A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.","activities":[{"id":"unit-testing-behavior--r1--exploration","kind":"simulation","prompt":"Try an incorrect path first, read the observed state, then find a solution. Finish by explaining the cause.","stableKey":"exploration","outcomeIds":["unit-testing-behavior--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"unit-testing-behavior--r1--exploration--state-weak","debriefQuestion":"Why keep the same assertion while fixing implementation? What have you changed if you replace the expected value with 1503?","states":[{"id":"unit-testing-behavior--r1--exploration--state-weak","label":"Weak test","observation":"The service adds; the fake returns a 4500 fixture; the test passes.","isSuccess":false},{"id":"unit-testing-behavior--r1--exploration--state-observed","label":"Observe the real payload","observation":"The fake echoes input; the test compares against 4500 and fails because it receives 1503.","isSuccess":false},{"id":"unit-testing-behavior--r1--exploration--state-fixed","label":"Fix business logic","observation":"Change addition to multiplication; the same test passes.","isSuccess":false},{"id":"unit-testing-behavior--r1--exploration--state-boundary","label":"Check the failure path","observation":"quantity=0 is rejected; saveCount=0.","isSuccess":true}],"actions":[{"id":"unit-testing-behavior--r1--exploration--action-observe","label":"Change the fake and assertion"},{"id":"unit-testing-behavior--r1--exploration--action-fix","label":"Fix the calculation"},{"id":"unit-testing-behavior--r1--exploration--action-invalid","label":"Add quantity=0"}],"transitions":[{"id":"unit-testing-behavior--r1--exploration--transition-0","fromStateId":"unit-testing-behavior--r1--exploration--state-weak","actionId":"unit-testing-behavior--r1--exploration--action-observe","toStateId":"unit-testing-behavior--r1--exploration--state-observed"},{"id":"unit-testing-behavior--r1--exploration--transition-1","fromStateId":"unit-testing-behavior--r1--exploration--state-observed","actionId":"unit-testing-behavior--r1--exploration--action-fix","toStateId":"unit-testing-behavior--r1--exploration--state-fixed"},{"id":"unit-testing-behavior--r1--exploration--transition-2","fromStateId":"unit-testing-behavior--r1--exploration--state-fixed","actionId":"unit-testing-behavior--r1--exploration--action-invalid","toStateId":"unit-testing-behavior--r1--exploration--state-boundary"}]}}],"id":"2-experiment"},{"title":"Start with the function's promise","phase":"explain","sortIndex":3,"body":"Before testing, write the promise: 'For a positive integer quantity and valid unit price, the saved total equals quantity times price; invalid input must not be saved.' This contract specifies both an observable result and a prohibited effect. Starting from a class's method list encourages one test per method name while overlooking important behavior.\n\nArrange prepares inputs and dependencies; Act invokes real behavior; Assert compares results with the contract. The expected 4500 comes from the requirement 3 × 1500. Do not reproduce the implementation's entire formula to calculate expectations: if both share the same mistake, the test may pass without protecting anything.","id":"3-theory-1"},{"title":"Isolate dependencies without removing behavior","phase":"explain","sortIndex":4,"body":"A unit need not be exactly one method. Here it is createOrder's pricing and saving decision. The repository is an I/O boundary replaced with a small fake to remove database dependence. A pricing helper that belongs to the behavior under test should remain real. Mocking createOrder and checking its fixture verifies only mock configuration.\n\nAn echo fake is useful because it does not repair the service's output. But it represents only a narrow contract: it cannot establish real unique constraints, transactions or column mapping. Those risks require separate integration tests. A good unit test states both what it proves and what it leaves open.\n\nWhen a side effect is part of the contract, checking calls is meaningful. 'quantity=0 must not save' is observable through saveCount=0. In contrast, asserting a private helper is called exactly once merely because the current implementation does so can make valid refactoring fail tests.","id":"4-theory-2"},{"title":"Choose cases that expose differences","phase":"explain","sortIndex":5,"body":"**Choose cases from behavioral partitions, not a fixed test count.**\n\n| Case | Expected observation | Detectable defect |\n| --- | --- | --- |\n| 3 × 1500 | 4500 cent | Addition instead of multiplication |\n| quantity=0 or -1 | Reject without saving | Missing invariant validation |\n| quantity=1.5 | Reject | Fractional quantities accepted outside the contract |\n| Negative price or NaN | Reject | One-sided validation |\n| Total exceeds the safe-integer range | Reject | Loss of integer precision |\n| Repository rejection | Promise reject | Swallowed error reported as success |\n\nInteger cents remove decimal distractions from this example; they do not solve all currencies and rounding. quantity=1 may not distinguish the defects you want to catch, while 3 and 1500 clearly separate addition from multiplication. For each test, ask which incorrect implementation would make it fail.","id":"5-theory-3"},{"title":"Keep runs independent","phase":"explain","sortIndex":6,"body":"A test depending on the real clock, execution order or state left by another test can change without a code change. Create fresh fakes. Inject a clock or use fake timers with cleanup when time matters. Make time zones explicit so date tests do not pass only on the author's machine.\n\nIn Vitest, clearing call history is not the same as removing a fake implementation. Distinguish clear, reset and restore; fresh fakes are often simpler for introductory material. Await asynchronous behavior and rejection assertions, or the test may finish before the error occurs.\n\n**source.ts contains the real logic under test; save is injected to keep I/O controlled.**\n\n```typescript\n/** Đặt hàng với repository truyền vào để kiểm soát I/O. (EN: Order logic with an injected I/O boundary.) */\ntype Draft = {quantity: number; unitPriceCents: number};\ntype Order = Draft & {totalCents: number};\ntype Save = (order: Order) => Promise<Order>;\n/** Kiểm invariant trước khi lưu, tiền dùng đơn vị cent nguyên. (EN: Validate before save; use integer cents.) */\nexport async function createOrder(draft: Draft, save: Save): Promise<Order> {\n    if (!Number.isSafeInteger(draft.quantity) || draft.quantity <= 0) throw new Error('invalid quantity');\n    if (!Number.isSafeInteger(draft.unitPriceCents) || draft.unitPriceCents < 0) throw new Error('invalid price');\n    const totalCents = draft.quantity * draft.unitPriceCents;\n    if (!Number.isSafeInteger(totalCents)) throw new Error('unsafe total');\n    return save({...draft,totalCents});\n}\n```","id":"6-theory-4"},{"title":"A passing test is a starting point for scrutiny","phase":"explain","sortIndex":7,"body":"Coverage identifies executed regions and helps find untouched code, but does not guarantee defect-catching assertions. Try a small mutation: replace multiplication with addition, remove a guard or swallow a save error. If the relevant test stays green, revisit its contract or observation point.\n\nA useful suite need not kill every mutation: some are equivalent or outside the contract. Value comes from detecting important business failures quickly, reliably and clearly. Unit tests need not cover every risk; add integration and E2E checks at boundaries where real failures are plausible.","activities":[{"id":"unit-testing-behavior--r1--quiz-assert","kind":"choice","prompt":"Which assertion directly protects the requirement that invalid input creates no order?","stableKey":"quiz-assert","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--application"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"A failure path can both throw and have already saved invalid data; asserting a throw alone is insufficient.","misconception":"result is not null; The service class has a createOrder method"},"options":[{"id":"unit-testing-behavior--r1--quiz-assert--option-1","label":"result is not null","explanation":"Incorrect: this does not observe side effects.","isCorrect":false},{"id":"unit-testing-behavior--r1--quiz-assert--option-2","label":"The Promise rejects and save was never called","explanation":"Correct: it checks both the response and a forbidden effect.","isCorrect":true},{"id":"unit-testing-behavior--r1--quiz-assert--option-3","label":"The service class has a createOrder method","explanation":"Incorrect: having a method says nothing about correct behavior.","isCorrect":false}]},{"id":"unit-testing-behavior--r1--quiz-coverage","kind":"choice","prompt":"What does 100% line coverage prove?","stableKey":"quiz-coverage","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":1,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Interpret a metric according to what it actually measures.","misconception":"Every invariant is verified; The real database is compatible with the fake"},"options":[{"id":"unit-testing-behavior--r1--quiz-coverage--option-1","label":"Every invariant is verified","explanation":"Incorrect: executing a line does not establish assertion strength.","isCorrect":false},{"id":"unit-testing-behavior--r1--quiz-coverage--option-2","label":"The instrumented lines executed during the test suite","explanation":"Correct: this is the actual scope of the metric.","isCorrect":true},{"id":"unit-testing-behavior--r1--quiz-coverage--option-3","label":"The real database is compatible with the fake","explanation":"Incorrect: that requires integration evidence.","isCorrect":false}]}],"id":"7-theory-5"},{"title":"Practice with evidence","phase":"apply","sortIndex":8,"body":"Run the included tests with Node.js 24. No database or runner installation is needed. After they pass, copy the source into your exercise workspace, change multiplication to addition and rerun to collect failing evidence.\n\n**Windows PowerShell.**\n\n```powershell\nnode --test source.test.ts\n```\n\n**macOS/Linux.**\n\n```bash\nnode --test source.test.ts\n```\n\nSubmit output before and after mutation and the assertion that catches it. Restore the source and rerun. Do not change the expectation to fit the wrong result. This is actual code practice, not an 'I understand' button.","activities":[{"id":"unit-testing-behavior--r1--practice-mutation","kind":"exercise","prompt":"Mutate multiplication into addition. Then add tests for quantity=1.5 and repository rejection. Submit the patch, failing and passing output, and one sentence per test explaining the promise it protects.","stableKey":"practice-mutation","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism","unit-testing-behavior--r1--application","unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"unit-testing-behavior--r1--practice-mutation--criterion-0","criterion":"Requested result","expectedEvidence":"The total test fails with addition and passes after restoration, with contract-based expectations unchanged.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"unit-testing-behavior--r1--practice-mutation--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Add a no-save test for fractional quantities and verify repository rejection propagates.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"unit-testing-behavior--r1--practice-mutation--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Explain each protected promise and the remaining database-integration limit.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"The total test catches addition; the fractional-quantity test checks the integer contract and absence of saving; a rejecting save fake checks error propagation instead of false success. Create a fresh fake per test and await assertions. These tests say nothing about real database transactions.","sampleAnswer":"The total test catches addition; the fractional-quantity test checks the integer contract and absence of saving; a rejecting save fake checks error propagation instead of false success. Create a fresh fake per test and await assertions. These tests say nothing about real database transactions.","misconception":"A function call or truthy result is sufficient.; Mock the function under test itself.; High coverage or one passing test proves every layer correct."},"exercise":{"submissionInstructions":"Mutate multiplication into addition. Then add tests for quantity=1.5 and repository rejection. Submit the patch, failing and passing output, and one sentence per test explaining the promise it protects.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works.","files":[{"relativePath":"source.ts","role":"reference","syntaxLanguage":"typescript","content":"/** Đặt hàng với repository truyền vào để kiểm soát I/O. (EN: Order logic with an injected I/O boundary.) */\ntype Draft = {quantity: number; unitPriceCents: number};\ntype Order = Draft & {totalCents: number};\ntype Save = (order: Order) => Promise<Order>;\n/** Kiểm invariant trước khi lưu, tiền dùng đơn vị cent nguyên. (EN: Validate before save; use integer cents.) */\nexport async function createOrder(draft: Draft, save: Save): Promise<Order> {\n    if (!Number.isSafeInteger(draft.quantity) || draft.quantity <= 0) throw new Error('invalid quantity');\n    if (!Number.isSafeInteger(draft.unitPriceCents) || draft.unitPriceCents < 0) throw new Error('invalid price');\n    const totalCents = draft.quantity * draft.unitPriceCents;\n    if (!Number.isSafeInteger(totalCents)) throw new Error('unsafe total');\n    return save({...draft,totalCents});\n}\n","sha256":"3dc440368960b4ab5fbe6160458f25333b2dac63c4c2fb6347fbdd4cc2768f3e"},{"relativePath":"source.test.ts","role":"checks","syntaxLanguage":"typescript","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {createOrder} from './source.ts';\ntest('calculates payload from business requirement', async (): Promise<void> => {const result=await createOrder({quantity:3,unitPriceCents:1500},async (row)=>row);assert.equal(result.totalCents,4500);});\ntest('invalid quantity never writes', async (): Promise<void> => {let calls=0;await assert.rejects(()=>createOrder({quantity:0,unitPriceCents:1500},async (row)=>{calls++;return row;}),/quantity/);assert.equal(calls,0);});\ntest('invalid price and unsafe total reject', async (): Promise<void> => {await assert.rejects(()=>createOrder({quantity:1,unitPriceCents:NaN},async(row)=>row));await assert.rejects(()=>createOrder({quantity:2,unitPriceCents:Number.MAX_SAFE_INTEGER},async(row)=>row));});\n","sha256":"94dfffdc31bfc72fdce06aa0d4af1437472a69aaeae898c82d2b468a41f43b07"}],"checks":[{"id":"unit-testing-behavior--r1--practice-mutation--node-tests","runner":"node-test","entrypoint":"source.test.ts","expectedExitCode":0,"scope":"educational-local-model","runtime":"Node.js 24","executionStatus":"passed"}]}}],"id":"8-practice"},{"title":"A new situation","phase":"apply","sortIndex":9,"body":"Close the solution before starting. If you use hints, the system should still record your attempt and label it as assisted.","activities":[{"id":"unit-testing-behavior--r1--transfer-expiry","kind":"exercise","prompt":"A voucher expires exactly at expiresAt. applyVoucher receives now and calls saveDiscount. Design three cases around expiry, side-effect checks and a mutation that the tests must catch.","stableKey":"transfer-expiry","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism","unit-testing-behavior--r1--application","unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"unit-testing-behavior--r1--transfer-expiry--criterion-0","criterion":"Requested result","expectedEvidence":"Explicitly reject now >= expiresAt and test before, at and after the boundary.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"unit-testing-behavior--r1--transfer-expiry--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Check no save for both expired cases and a save before expiry.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"unit-testing-behavior--r1--transfer-expiry--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Control now; mutating >= to > must fail the exact-boundary case without relying on the real clock.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"Define now >= expiresAt as expired. Test successful saving at expiresAt-1 and rejection without saving exactly at and after expiry. Supply a fixed now rather than using the real clock. Mutating >= to > must fail the equality case. Time-zone parsing is a separate boundary requiring separate checks.","sampleAnswer":"Define now >= expiresAt as expired. Test successful saving at expiresAt-1 and rejection without saving exactly at and after expiry. Supply a fixed now rather than using the real clock. Mutating >= to > must fail the equality case. Time-zone parsing is a separate boundary requiring separate checks.","misconception":"A function call or truthy result is sufficient.; Mock the function under test itself.; High coverage or one passing test proves every layer correct."},"exercise":{"submissionInstructions":"A voucher expires exactly at expiresAt. applyVoucher receives now and calls saveDiscount. Design three cases around expiry, side-effect checks and a mutation that the tests must catch.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works."}}],"id":"9-transfer"},{"title":"Interview again and explain your reasoning","phase":"reflect","sortIndex":10,"body":"A test is valuable when it protects a promise and fails when that promise is broken. Examine inputs, real logic, observation points and the defect an assertion catches before looking at coverage percentages.\n\nAI should return criterion-level results and quote evidence from your submission. While grading is pending, the state remains pending; you can continue reading and return later. Interview scores do not increase merely because an answer is longer.","activities":[{"id":"unit-testing-behavior--r1--final-interview","kind":"explain","prompt":"Explain why the test misses addition in place of multiplication. Design tests for the total and for quantity=0 never reaching repository persistence.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["unit-testing-behavior--r1--mechanism","unit-testing-behavior--r1--application","unit-testing-behavior--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"unit-testing-behavior--r1--final-interview--criterion-0","criterion":"Protected behavior","expectedEvidence":"Assert the correct total and no save for invalid input; derive expectations from requirements.","misconception":"A function call or truthy result is sufficient.","maxScore":2},{"id":"unit-testing-behavior--r1--final-interview--criterion-1","criterion":"Unit boundary","expectedEvidence":"Run real logic and replace the I/O dependency with a controlled fake.","misconception":"Mock the function under test itself.","maxScore":2},{"id":"unit-testing-behavior--r1--final-interview--criterion-2","criterion":"Defect sensitivity","expectedEvidence":"Identify a wrong change that fails the test and the untested integration boundary.","misconception":"High coverage or one passing test proves every layer correct.","maxScore":2}],"answer":{"explanation":"A fake that always returns the correct fixture can hide a bad payload sent by the service. Keep createOrder real; use a fake that records and returns its save argument. For quantity=3 and unitPriceCents=1500, assert totalCents=4500. For quantity=0, assert rejection and zero save calls. Then change multiplication to addition to confirm the behavioral test fails. These tests do not verify real database transactions or schemas.","sampleAnswer":"A fake that always returns the correct fixture can hide a bad payload sent by the service. Keep createOrder real; use a fake that records and returns its save argument. For quantity=3 and unitPriceCents=1500, assert totalCents=4500. For quantity=0, assert rejection and zero save calls. Then change multiplication to addition to confirm the behavioral test fails. These tests do not verify real database transactions or schemas.","misconception":"A function call or truthy result is sufficient.; Mock the function under test itself.; High coverage or one passing test proves every layer correct."}}],"id":"10-reflection"}]}},"workspace":{"runtime":"Node.js 24","files":[{"path":"workspace/source.test.ts","role":"test"},{"path":"workspace/source.ts","role":"source"}],"commands":{"windows":"node --test workspace/source.test.ts","unix":"node --test workspace/source.test.ts"}},"files":[{"path":"workspace/source.test.ts","role":"test","content":"import {test} from 'node:test';\nimport assert from 'node:assert/strict';\nimport {createOrder} from './source.ts';\ntest('calculates payload from business requirement', async (): Promise<void> => {const result=await createOrder({quantity:3,unitPriceCents:1500},async (row)=>row);assert.equal(result.totalCents,4500);});\ntest('invalid quantity never writes', async (): Promise<void> => {let calls=0;await assert.rejects(()=>createOrder({quantity:0,unitPriceCents:1500},async (row)=>{calls++;return row;}),/quantity/);assert.equal(calls,0);});\ntest('invalid price and unsafe total reject', async (): Promise<void> => {await assert.rejects(()=>createOrder({quantity:1,unitPriceCents:NaN},async(row)=>row));await assert.rejects(()=>createOrder({quantity:2,unitPriceCents:Number.MAX_SAFE_INTEGER},async(row)=>row));});\n"},{"path":"workspace/source.ts","role":"source","content":"/** Đặt hàng với repository truyền vào để kiểm soát I/O. (EN: Order logic with an injected I/O boundary.) */\ntype Draft = {quantity: number; unitPriceCents: number};\ntype Order = Draft & {totalCents: number};\ntype Save = (order: Order) => Promise<Order>;\n/** Kiểm invariant trước khi lưu, tiền dùng đơn vị cent nguyên. (EN: Validate before save; use integer cents.) */\nexport async function createOrder(draft: Draft, save: Save): Promise<Order> {\n    if (!Number.isSafeInteger(draft.quantity) || draft.quantity <= 0) throw new Error('invalid quantity');\n    if (!Number.isSafeInteger(draft.unitPriceCents) || draft.unitPriceCents < 0) throw new Error('invalid price');\n    const totalCents = draft.quantity * draft.unitPriceCents;\n    if (!Number.isSafeInteger(totalCents)) throw new Error('unsafe total');\n    return save({...draft,totalCents});\n}\n"}]}$lesson$::jsonb,
    '2026-11-08T00:00:00Z'
) ON CONFLICT DO NOTHING;
