    'health-probe-semantics', '231d8cc57', 'bbf20b4c6c71057442a93ed9af2a6fbbaee26ca2ea0b6f1ad7808af32b9a8f8b', 'published', 'devops', 'infra', 'kubernetes', 'courses/2-devops-mastery/modules/18-kubernetes-core-and-internals/contents/4-probes-autoscaling-and-rollouts', 'foundation', 65, 'agnostic', 4,
    $lesson${"vi":"Health probes — rút traffic hay khởi động lại?","en":"Health probes — withdraw traffic or restart?"}$lesson$::jsonb,
    $lesson${"vi":"Health probes là tín hiệu để bộ điều khiển quyết định container có nên nhận traffic, tiếp tục khởi động hay cần khởi động lại.","en":"Health probes provide signals for a controller to decide whether a container should receive traffic, continue starting or restart."}$lesson$::jsonb,
    $lesson${"en.md":"6cba004e69cb85fa432d857558c0b872fb90ebd25061f266fc88a62723f7e700","sections/0-interview/en.md":"0b73d944653d988a46e9698c2f4c0736397156fce9dbf97b1b442a23fde58ae6","sections/0-interview/vi.md":"a5c0b96cf40e451e24a21c57eb760a380ffdee4d51894c6d658ff4f2da5162a2","sections/1-prediction/en.md":"51996a10cf45cd7692a5e70ee92eedbf34f03e0233a94f5701e8f496609889a9","sections/1-prediction/vi.md":"9285895a77bee07c95e778b0b0422468b798c0700af68e8585150777bdfe830c","sections/10-reflection/en.md":"2a15c8a6d1a7eb6e699d992878a681b000ab52fd751c038b00df2c9a4e540f94","sections/10-reflection/vi.md":"d6b7878a45fa492c30e8c5abe5e393fa631b7a285ffec6ab285e66589d75cbd7","sections/2-experiment/en.md":"638874ce9e90fbdb778d5fbe4f0b0f387226d9a0fd53ca43603b78ac6bd7edab","sections/2-experiment/vi.md":"24457de0c22903ad9f8b41a389bae6585363f1ec9915bce9f03ca050122aff4b","sections/3-theory-1/en.md":"6912a2b965aeef163d14d7d98f3dcaa0eaf67909d652c2bbf4a3c7231cf07d74","sections/3-theory-1/vi.md":"a8db5391a9de07c82e4cc2d55208abdfb5b895d905ac267e076931014fcf6139","sections/4-theory-2/en.md":"956809980601b20f82d11492ce4c02c1cfe4047e7a8e19b74eba9713c0e8158c","sections/4-theory-2/vi.md":"3bf887c4ec70d894aed05f1988741fedf77f86cbd096b8ffbc3880fb79ddc618","sections/5-theory-3/en.md":"6e129dadbf74b56edd8623c1d8229fff00f8f8148867e51cdbf108471a104f0e","sections/5-theory-3/vi.md":"b40f61f9259e87bfe48d52555bddad52a563674a7cacbdad7150239799e278f1","sections/6-theory-4/en.md":"06e65055cb7f8aa2d5cf6d3126ec69b224d15fee3808f484bf72fbddbd8a7254","sections/6-theory-4/vi.md":"c159985abcdec3d595b563d2202d4c58b15cbd70bc0e9884f0958f3cf1f729c7","sections/7-theory-5/en.md":"d8aa61b3cf074c17a842f2f81e45d3dcc8ae2b124a004c9e22bf7f9bc81642b8","sections/7-theory-5/vi.md":"cd1436680393180b6776184b55cd49a0647052538d63b607f926117d0f80f752","sections/8-practice/en.md":"257a1db643b06ecb25d26ea971c4b13dd254b3f3806f0f3b45447870bd41247f","sections/8-practice/vi.md":"eec3695911c834197f5b31322d7556e254762e3a62ca38d9e739e36d7051a8da","sections/9-transfer/en.md":"6563dfbe39380272d1fa94f32c5a2e7ae17dcc16be0c23f5108a60993eaa0673","sections/9-transfer/vi.md":"0e45421e1e09823912f2e845bb6d5d87b40cb40f63f4e002dde97a44b7775988","vi.md":"27f56157b0175390220663fa38b62c3d0232d01b049acc1d7bb2fa2500375f20"}$lesson$::jsonb,
    $lesson${"locales":{"vi":{"title":"Health probes — rút traffic hay khởi động lại?","description":"Health probes là tín hiệu để bộ điều khiển quyết định container có nên nhận traffic, tiếp tục khởi động hay cần khởi động lại.","body":"## Tóm tắt\n\nProbe tốt không hỏi chung chung hệ thống có hoàn hảo không. Nó trả đúng thông tin cho một hành động cụ thể và giúp hệ thống hồi phục mà không tự khuếch đại sự cố.\n\n## Kết quả học tập\n\n- Chọn hành động phù hợp với lỗi boot, lỗi nội tại và lỗi dependency.\n- Thiết kế probe policy cho app có chế độ degraded.\n- Giải thích restart storm, timeout và bằng chứng cần để kết luận phục hồi.\n\n## Kiến thức đầu vào\n\n- Biết container, Pod và Service trong Kubernetes.\n- Phân biệt app với database/cache mà app gọi.\n\n## Phạm vi bao gồm\n\n- Liveness, readiness, startup và hậu quả failure.\n- Dependency bắt buộc/tùy chọn, timeout và flapping.\n- Thiết kế bảng quyết định và kiểm bằng trạng thái điều khiển.\n\n## Phạm vi không bao gồm\n\n- Viết health endpoint bằng framework.\n- Deploy cluster và tuning production tổng thể.\n- Triển khai monitoring stack.\n\n## Luận điểm chính\n\n- Readiness failure không tự restart container.\n- Liveness failure vượt ngưỡng có thể dẫn tới restart container.\n- Startup probe giữ liveness/readiness chưa chạy cho tới khi startup thành công.\n\n## Điều chỉnh nhận thức\n\n- Không dùng DB ping làm liveness mặc định: DB bên ngoài down không được sửa bằng restart app.\n- Readiness không bắt buộc ping mọi dependency, phải xét khả năng phục vụ degraded.\n- Promise.race giới hạn chờ nhưng không tự hủy I/O đang chạy.\n- Phân biệt HTTP health check với hành động Kubernetes; Docker Compose không tự chứng minh semantics kubelet.\n\n## Tham khảo\n\n- [kubernetes.io/docs/concepts/workloads/pods/probes/](https://kubernetes.io/docs/concepts/workloads/pods/probes/)\n- [kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/](https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/)","learningOutcomes":[{"id":"health-probe-semantics--r1--mechanism","text":"Chọn hành động phù hợp với lỗi boot, lỗi nội tại và lỗi dependency."},{"id":"health-probe-semantics--r1--application","text":"Thiết kế probe policy cho app có chế độ degraded."},{"id":"health-probe-semantics--r1--tradeoffs","text":"Giải thích restart storm, timeout và bằng chứng cần để kết luận phục hồi."}],"prerequisites":[{"id":"health-probe-semantics--r1--input-0","text":"Biết container, Pod và Service trong Kubernetes."},{"id":"health-probe-semantics--r1--input-1","text":"Phân biệt app với database/cache mà app gọi."}],"references":[{"id":"health-probe-semantics--r1--legacy","label":"Nguồn dữ liệu trước migration","citation":"legacy; courses/0-fullstack-mastery/modules/16-observability-logs-tracing-errors/contents/3-health-readiness-liveness-probes/bodies/0-typescript/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 0e662b08d1b6eaa70352be1993bf8993508e428d82392aa8d5fd9e7f50d4f0fa; checked 2026-09-05; Bài mẫu V2 mới; không sửa V1."},{"id":"health-probe-semantics--r1--official-0","label":"kubernetes.io/docs/concepts/workloads/pods/probes/","url":"https://kubernetes.io/docs/concepts/workloads/pods/probes/","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."},{"id":"health-probe-semantics--r1--official-1","label":"kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/","url":"https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."}],"retrieval":[{"id":"health-probe-semantics--r1--retrieval-1","kind":"retrieval","prompt":"Một ngày: /ready=503 nhưng restartCount=0. Có sai không? Nêu một case đúng và cách kiểm hồi phục.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism"],"afterDays":1,"rubric":[{"id":"health-probe-semantics--r1--retrieval-1--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Không sai: dependency bắt buộc down có thể làm Not Ready mà không restart. Khôi phục dependency rồi quan sát Ready về true; endpoint và events cùng chứng minh.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Không sai: dependency bắt buộc down có thể làm Not Ready mà không restart. Khôi phục dependency rồi quan sát Ready về true; endpoint và events cùng chứng minh.","sampleAnswer":"Không sai: dependency bắt buộc down có thể làm Not Ready mà không restart. Khôi phục dependency rồi quan sát Ready về true; endpoint và events cùng chứng minh.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"health-probe-semantics--r1--retrieval-2","kind":"retrieval","prompt":"Một tuần: cache timeout làm cả Service rỗng endpoint dù app có fallback. Sửa threshold hay semantics trước?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--application"],"afterDays":7,"rubric":[{"id":"health-probe-semantics--r1--retrieval-2--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Kiểm cache có thật sự bắt buộc và fallback đủ tải trước. Nếu tùy chọn, sửa readiness semantics; threshold chỉ giảm flapping, không sửa chọn sai dependency.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Kiểm cache có thật sự bắt buộc và fallback đủ tải trước. Nếu tùy chọn, sửa readiness semantics; threshold chỉ giảm flapping, không sửa chọn sai dependency.","sampleAnswer":"Kiểm cache có thật sự bắt buộc và fallback đủ tải trước. Nếu tùy chọn, sửa readiness semantics; threshold chỉ giảm flapping, không sửa chọn sai dependency.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"health-probe-semantics--r1--retrieval-3","kind":"retrieval","prompt":"21 ngày: app memory tăng dù mọi health call timeout sau 2s. Đưa giả thuyết liên quan tới check và phép kiểm.","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"health-probe-semantics--r1--retrieval-3--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"I/O thua Promise.race vẫn treo và tích tụ. Quan sát số request/socket đang bay; thêm cancellation/client timeout và concurrency bound rồi kiểm tài nguyên ổn định. Không kết luận chỉ từ thời gian HTTP trả.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"I/O thua Promise.race vẫn treo và tích tụ. Quan sát số request/socket đang bay; thêm cancellation/client timeout và concurrency bound rồi kiểm tài nguyên ổn định. Không kết luận chỉ từ thời gian HTTP trả.","sampleAnswer":"I/O thua Promise.race vẫn treo và tích tụ. Quan sát số request/socket đang bay; thêm cancellation/client timeout và concurrency bound rồi kiểm tài nguyên ổn định. Không kết luận chỉ từ thời gian HTTP trả.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}}],"sections":[{"title":"Bối cảnh phỏng vấn","phase":"challenge","sortIndex":0,"body":"Trong phỏng vấn DevOps, interviewer đưa biểu đồ: Redis down 2 phút, đồng thời mọi container app restart liên tục. Redis đã sống lại nhưng app vẫn mất thêm thời gian boot và tải cấu hình. “Restart app có giúp Redis sống lại không?” Bạn đáp: “Health check fail thì phải restart.” Bài này bắt đầu từ chỗ phải tách câu hỏi “có phục vụ được không” khỏi câu hỏi “restart có giúp không”.\n\nTrả lời câu hỏi bằng suy nghĩ hiện tại. Đây là lần chẩn đoán đầu vào, chưa tính đạt đầu ra. Bạn sẽ trả lời lại sau khi thực hành; bài vẫn mở nếu bạn chưa biết đáp án.","activities":[{"id":"health-probe-semantics--r1--opening-interview","kind":"explain","prompt":"Thiết kế probes cho app checkout dùng database bắt buộc và Redis cache tùy chọn. Khi Redis down, khi database down và khi app deadlock, bộ điều khiển nên làm gì?","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism","health-probe-semantics--r1--application","health-probe-semantics--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"health-probe-semantics--r1--opening-interview--criterion-0","criterion":"Hành động điều khiển","expectedEvidence":"Nối readiness với nhận traffic, liveness với restart container và startup với giai đoạn boot.","misconception":"Mọi health failure đều restart pod.","maxScore":2},{"id":"health-probe-semantics--r1--opening-interview--criterion-1","criterion":"Phụ thuộc và phục hồi","expectedEvidence":"Chọn check theo khả năng phục vụ và liệu restart app có sửa nguyên nhân không.","misconception":"Cứ dependency fail là liveness fail.","maxScore":2},{"id":"health-probe-semantics--r1--opening-interview--criterion-2","criterion":"Bằng chứng vận hành","expectedEvidence":"Nêu Ready, restartCount, sự kiện probe và khả năng phục hồi; không chỉ HTTP status.","misconception":"Gọi endpoint 503 đã chứng minh kubelet restart.","maxScore":2}],"answer":{"explanation":"Redis tùy chọn mất thì app có thể degraded và vẫn Ready nếu fallback đủ khả năng phục vụ. Database bắt buộc mất làm readiness fail nhưng liveness của app không nên fail chỉ vì dependency đó. Deadlock khiến tiến trình không xử lý được thì liveness failure tới ngưỡng có thể restart container. Startup kiểm boot để tránh kill app đang khởi động hợp lệ. Cần quan sát Ready, restartCount, probe events và request thật để xác nhận.","sampleAnswer":"Redis tùy chọn mất thì app có thể degraded và vẫn Ready nếu fallback đủ khả năng phục vụ. Database bắt buộc mất làm readiness fail nhưng liveness của app không nên fail chỉ vì dependency đó. Deadlock khiến tiến trình không xử lý được thì liveness failure tới ngưỡng có thể restart container. Startup kiểm boot để tránh kill app đang khởi động hợp lệ. Cần quan sát Ready, restartCount, probe events và request thật để xác nhận.","misconception":"Mọi health failure đều restart pod.; Cứ dependency fail là liveness fail.; Gọi endpoint 503 đã chứng minh kubelet restart."}}],"id":"0-interview"},{"title":"Dự đoán trước khi quan sát","phase":"predict","sortIndex":1,"body":"App vẫn xử lý request được qua database khi Redis mất; Redis chỉ tăng tốc. Liveness hiện ping Redis và failureThreshold đã đạt.","activities":[{"id":"health-probe-semantics--r1--predict-restart","kind":"choice","prompt":"Hậu quả nào có thể xảy ra với cấu hình này?","stableKey":"predict-restart","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Health check là một tín hiệu điều khiển, nên thiết kế từ hậu quả của tín hiệu.","misconception":"Redis tự được restart vì probe nằm trong app; Readiness tự biến thành liveness"},"options":[{"id":"health-probe-semantics--r1--predict-restart--option-1","label":"Restart container khỏe mà nguyên nhân Redis vẫn còn","explanation":"Đúng: hành động không tác động tới thành phần gây lỗi.","isCorrect":true},{"id":"health-probe-semantics--r1--predict-restart--option-2","label":"Redis tự được restart vì probe nằm trong app","explanation":"Sai: kubelet đang kiểm và tác động container được cấu hình, không điều khiển Redis từ xa.","isCorrect":false},{"id":"health-probe-semantics--r1--predict-restart--option-3","label":"Readiness tự biến thành liveness","explanation":"Sai: hai probe có ngữ nghĩa riêng.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Thử và quan sát","phase":"explore","sortIndex":2,"body":"Bạn vận hành mô hình có ba sự kiện: Redis down, database down, app deadlock. Quan sát hai cột Ready và restartCount. Một thiết kế tốt không tối đa hóa số lần restart; nó chọn hành động giải quyết đúng loại hỏng.\n\n**Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.**\n\n```mermaid\nflowchart TD\n S{Boot complete?} -->|no| W[Startup probe budget]\n S -->|yes| L{Internal liveness}\n L -->|failure threshold| R[Restart container]\n L -->|healthy| D{Can serve required traffic?}\n D -->|yes or acceptable degraded| Y[Ready]\n D -->|no| N[Not ready: remove from normal Service traffic]\n```\n\n> Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.","activities":[{"id":"health-probe-semantics--r1--exploration","kind":"simulation","prompt":"Thử đường sai trước, đọc trạng thái quan sát được, sau đó tìm đường giải quyết. Kết thúc bằng câu giải thích nguyên nhân.","stableKey":"exploration","outcomeIds":["health-probe-semantics--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"health-probe-semantics--r1--exploration--state-healthy","debriefQuestion":"Ở bước nào restart giúp, ở bước nào restart chỉ khuếch đại sự cố?","states":[{"id":"health-probe-semantics--r1--exploration--state-healthy","label":"Hệ thống khỏe","observation":"Ready=true; restartCount=0.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-degraded","label":"Redis tùy chọn down","observation":"Ready=true; dùng fallback DB; restartCount=0.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-not-ready","label":"DB bắt buộc down","observation":"Ready=false; không restart do dependency outage.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-recovered","label":"DB phục hồi","observation":"Ready=true sau khi check đạt ngưỡng; restartCount=0.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-deadlock","label":"App deadlock","observation":"Liveness liên tiếp fail; container không tiến triển.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-restarted","label":"Khởi động lại container","observation":"restartCount=1; startup kiểm boot; chỉ Ready khi đã sẵn sàng.","isSuccess":true}],"actions":[{"id":"health-probe-semantics--r1--exploration--action-redis-down","label":"Ngắt Redis"},{"id":"health-probe-semantics--r1--exploration--action-db-down","label":"Ngắt database"},{"id":"health-probe-semantics--r1--exploration--action-db-up","label":"Khôi phục database"},{"id":"health-probe-semantics--r1--exploration--action-deadlock","label":"Gây lỗi nội tại"},{"id":"health-probe-semantics--r1--exploration--action-restart","label":"Đạt liveness failure threshold"}],"transitions":[{"id":"health-probe-semantics--r1--exploration--transition-0","fromStateId":"health-probe-semantics--r1--exploration--state-healthy","actionId":"health-probe-semantics--r1--exploration--action-redis-down","toStateId":"health-probe-semantics--r1--exploration--state-degraded"},{"id":"health-probe-semantics--r1--exploration--transition-1","fromStateId":"health-probe-semantics--r1--exploration--state-degraded","actionId":"health-probe-semantics--r1--exploration--action-db-down","toStateId":"health-probe-semantics--r1--exploration--state-not-ready"},{"id":"health-probe-semantics--r1--exploration--transition-2","fromStateId":"health-probe-semantics--r1--exploration--state-not-ready","actionId":"health-probe-semantics--r1--exploration--action-db-up","toStateId":"health-probe-semantics--r1--exploration--state-recovered"},{"id":"health-probe-semantics--r1--exploration--transition-3","fromStateId":"health-probe-semantics--r1--exploration--state-recovered","actionId":"health-probe-semantics--r1--exploration--action-deadlock","toStateId":"health-probe-semantics--r1--exploration--state-deadlock"},{"id":"health-probe-semantics--r1--exploration--transition-4","fromStateId":"health-probe-semantics--r1--exploration--state-deadlock","actionId":"health-probe-semantics--r1--exploration--action-restart","toStateId":"health-probe-semantics--r1--exploration--state-restarted"}]}}],"id":"2-experiment"},{"title":"Một endpoint 200 chưa có ý nghĩa nếu chưa biết ai dùng","phase":"explain","sortIndex":3,"body":"Giả sử /health trả 503. Bản thân con số chưa nói hệ thống phải làm gì. Nếu kubelet dùng nó làm readiness, Pod sẽ không được coi là sẵn sàng nhận traffic Service thông thường. Nếu dùng làm liveness và đủ ngưỡng failure, kubelet có thể restart container. Cùng một endpoint nhưng gắn vào quyết định khác sẽ tạo hậu quả khác.\n\nHãy bắt đầu từ hành động mong muốn. Khi app không phục vụ được do database ngoài mất kết nối, rút traffic có thể phù hợp; restart hàng loạt app không làm database hồi phục. Khi event loop bị kẹt vĩnh viễn do lỗi nội tại, restart có thể giúp. Một check chỉ báo “có lỗi ở đâu đó” quá mơ hồ để dùng cho mọi hành động.","id":"3-theory-1"},{"title":"Ba câu hỏi cần trả lời riêng","phase":"explain","sortIndex":4,"body":"**Với startup probe đã cấu hình, liveness/readiness đợi startup thành công.**\n\n| Probe | Câu hỏi | Failure dẫn tới |\n| --- | --- | --- |\n| Startup | Container đã hoàn thành khởi động chưa? | Tiếp tục kiểm trong budget; tới ngưỡng có thể restart |\n| Liveness | Container còn hoạt động theo cách có thể tiến triển không? | Restart container khi đạt failure threshold |\n| Readiness | Hiện có thể nhận traffic theo contract không? | Not Ready; không tự restart |\n\nStartup budget cần bao được thời gian boot hợp lệ, ví dụ tải model hoặc warm dữ liệu cục bộ. Sau khi startup thành công, liveness vẫn có thể dùng ngưỡng phát hiện lỗi trong lúc chạy. Không dùng một initial delay rất dài để che mọi kiểu boot chậm rồi làm phát hiện runtime failure chậm theo.\n\nFailure không nhất thiết tạo hành động ngay sau một lần check. period, timeout, failureThreshold và khi thích hợp successThreshold ảnh hưởng thời điểm đổi trạng thái. Budget gần bằng period × threshold là cách ước lượng, không phải bảo đảm thời điểm chính xác từng millisecond. Cần kiểm events và thực nghiệm với cấu hình cụ thể.","id":"4-theory-2"},{"title":"Dependency bắt buộc là quyết định sản phẩm","phase":"explain","sortIndex":5,"body":"Redis có thể là cache tùy chọn trong app A nhưng là kho session bắt buộc trong app B. Không thể chốt readiness chỉ theo tên công nghệ. Với cache tùy chọn, fallback database phải đủ sức gánh tải khi cache mất; nếu fallback làm database sập thì tuyên bố degraded không có cơ sở. Hãy nêu workload và khả năng giảm tính năng.\n\nDeep readiness ping mọi dependency dễ làm toàn bộ replicas cùng Not Ready khi một dịch vụ phụ chập chờn. Tăng threshold có thể giảm nhiễu ngắn, nhưng không sửa việc chọn sai dependency. Tách cái bắt buộc để phục vụ contract khỏi dịch vụ phụ; đồng thời có metrics/cảnh báo cho degraded để lỗi không bị giấu.\n\nMột connection pool cục bộ hỏng khác với database từ xa down. Nếu muốn restart vì pool hỏng, check phải phân biệt tình trạng cục bộ có thể sửa với outage bên ngoài; DB ping thất bại một mình không làm được việc đó.","id":"5-theory-3"},{"title":"Timeout phải giới hạn cả chi phí kiểm tra","phase":"explain","sortIndex":6,"body":"Một check gọi dependency treo không nên giữ health request vô hạn. Deadline ứng dụng cần phối hợp với timeout probe. Nhưng trả về sau Promise.race không hủy promise I/O thua cuộc: nếu mỗi giây tạo một ping treo mới, tài nguyên vẫn tích tụ. Dùng timeout/cancellation của client khi có, giới hạn số check đang bay và dọn timer.\n\nProbe cũng tạo tải. Một check chạy truy vấn nặng trên mọi replica có thể làm hại chính dependency nó đang quan sát. Chọn tín hiệu rẻ và sát khả năng phục vụ. Với readiness flapping, ghi chuỗi trạng thái và nguyên nhân, xem các ngưỡng hysteresis phù hợp; không tăng timeout tới mức che deadlock.","id":"6-theory-4"},{"title":"Kết quả cần quan sát là vòng phục hồi","phase":"explain","sortIndex":7,"body":"Thực hành đầy đủ không dừng ở thấy /ready trả 503. Sau khi ngắt dependency, quan sát Pod Ready đổi không, restartCount có tăng trái ý không, traffic còn được gửi tới đâu và sau khi khôi phục hệ thống mất bao lâu để Ready lại. Endpoint thành công ở Compose chỉ kiểm code endpoint; muốn kết luận hành vi Kubernetes phải có probe configuration và kubelet thật.\n\nBài này dùng mô phỏng xác định để học cách chọn hành động. Bằng chứng mô phỏng được lưu riêng và không được gắn nhãn cluster đã test. Khi triển khai thật, còn phải xét shutdown/draining: Not Ready không tự bảo đảm mọi kết nối đang mở đã kết thúc và mọi client cache endpoint đã cập nhật tức thì.","activities":[{"id":"health-probe-semantics--r1--quiz-dependency","kind":"choice","prompt":"Database ngoài down, mọi app process vẫn lành. Hành động nào thường đúng nếu DB là bắt buộc?","stableKey":"quiz-dependency","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--application"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Liveness và readiness trả lời hai câu hỏi khác nhau.","misconception":"Restart tất cả app mỗi giây; Luôn Ready vì process còn sống"},"options":[{"id":"health-probe-semantics--r1--quiz-dependency--option-1","label":"Fail readiness; không fail liveness chỉ vì DB","explanation":"Đúng: rút traffic theo contract, tránh restart không chữa nguyên nhân.","isCorrect":true},{"id":"health-probe-semantics--r1--quiz-dependency--option-2","label":"Restart tất cả app mỗi giây","explanation":"Sai: có thể tạo storm và thêm tải reconnect.","isCorrect":false},{"id":"health-probe-semantics--r1--quiz-dependency--option-3","label":"Luôn Ready vì process còn sống","explanation":"Sai: sống không có nghĩa phục vụ được.","isCorrect":false}]},{"id":"health-probe-semantics--r1--quiz-timeout","kind":"choice","prompt":"Promise.race trả timeout có tự hủy socket request đang treo không?","stableKey":"quiz-timeout","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--tradeoffs"],"placementSortIndex":1,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Một check phải vừa trả kết quả hữu hạn vừa kiểm soát tài nguyên.","misconception":"Có; Chỉ cần tăng failureThreshold"},"options":[{"id":"health-probe-semantics--r1--quiz-timeout--option-1","label":"Có","explanation":"Sai: promise thua không tự bị hủy.","isCorrect":false},{"id":"health-probe-semantics--r1--quiz-timeout--option-2","label":"Không; cần cancellation/timeout ở I/O client nếu muốn dừng việc đó","explanation":"Đúng: tách giới hạn chờ khỏi giới hạn công việc.","isCorrect":true},{"id":"health-probe-semantics--r1--quiz-timeout--option-3","label":"Chỉ cần tăng failureThreshold","explanation":"Sai: threshold không hủy I/O.","isCorrect":false}]}],"id":"7-theory-5"},{"title":"Thực hành có bằng chứng","phase":"apply","sortIndex":8,"body":"Thực hành agnostic bằng bảng quyết định và mô phỏng, không cần viết một backend mới. Dùng từng event trong exploration và ghi Ready/restartCount dự đoán trước khi xem observation.\n\n**Điền cùng lý do và tín hiệu quan sát; dấu hỏi là phần bài làm.**\n\n```text\nCase                Ready   Restart?\nRedis optional down  ?       ?\nDatabase down        ?       ?\nApp deadlock         ?       ?\nValid slow boot      ?       ?\n```\n\nBản triển khai trên Kubernetes là hoạt động mở rộng sau này: cần manifest probe, logs và events thật. Mẫu hiện tại không tạo cluster, không chạy các lệnh phá dependency thật.","activities":[{"id":"health-probe-semantics--r1--practice-policy","kind":"exercise","prompt":"Nộp bảng cho bốn case ở workspace, thêm một cột “điều kiện làm câu trả lời thay đổi”. Ví dụ Redis trở thành session store bắt buộc thì sao? Nêu cách kiểm trạng thái sau khi dependency hồi phục.","stableKey":"practice-policy","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism","health-probe-semantics--r1--application","health-probe-semantics--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"health-probe-semantics--r1--practice-policy--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Phân biệt bốn case với Ready/restart: optional cache, required DB, deadlock, boot.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"health-probe-semantics--r1--practice-policy--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Chỉ ra điều kiện Redis thành bắt buộc hoặc fallback không đủ làm readiness thay đổi.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"health-probe-semantics--r1--practice-policy--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Nêu cách xem Ready hồi phục và restartCount không tăng sai ý.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"Redis optional down vẫn Ready nếu fallback đủ; DB required down Not Ready nhưng không restart chỉ vì DB; deadlock qua ngưỡng liveness restart; boot hợp lệ còn trong startup budget không bị liveness kill. Nếu Redis bắt buộc thì readiness đổi. Kiểm Ready trở lại và restartCount không tăng ngoài ý định.","sampleAnswer":"Redis optional down vẫn Ready nếu fallback đủ; DB required down Not Ready nhưng không restart chỉ vì DB; deadlock qua ngưỡng liveness restart; boot hợp lệ còn trong startup budget không bị liveness kill. Nếu Redis bắt buộc thì readiness đổi. Kiểm Ready trở lại và restartCount không tăng ngoài ý định.","misconception":"Mọi health failure đều restart pod.; Cứ dependency fail là liveness fail.; Gọi endpoint 503 đã chứng minh kubelet restart."},"exercise":{"submissionInstructions":"Nộp bảng cho bốn case ở workspace, thêm một cột “điều kiện làm câu trả lời thay đổi”. Ví dụ Redis trở thành session store bắt buộc thì sao? Nêu cách kiểm trạng thái sau khi dependency hồi phục.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production."}}],"id":"8-practice"},{"title":"Tình huống mới","phase":"apply","sortIndex":9,"body":"Đóng lời giải trước khi làm. Nếu dùng gợi ý, hệ thống vẫn ghi nhận bài làm nhưng gắn nhãn có hỗ trợ.","activities":[{"id":"health-probe-semantics--r1--transfer-model-load","kind":"exercise","prompt":"Service AI cần 90 giây tải model khi boot, sau đó API gợi ý bên ngoài đôi lúc timeout nhưng app có fallback. Thiết kế probes và nêu phép kiểm để không nhầm boot chậm với deadlock.","stableKey":"transfer-model-load","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism","health-probe-semantics--r1--application","health-probe-semantics--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"health-probe-semantics--r1--transfer-model-load--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Startup budget bao boot hợp lệ 90 giây với biến thiên, không để liveness kill oan.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"health-probe-semantics--r1--transfer-model-load--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Dependency tùy chọn có fallback không tự làm Not Ready; theo dõi degraded.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"health-probe-semantics--r1--transfer-model-load--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Kiểm boot kẹt/runtime deadlock/dependency timeout qua events, Ready, restartCount.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"Startup budget bao 90 giây cộng biến thiên hợp lệ; liveness tập trung tiến triển nội tại khi chạy. API gợi ý có fallback chấp nhận thì không tự làm Not Ready; giám sát degraded. Thử boot hợp lệ dài, boot kẹt quá budget, runtime deadlock và dependency timeout; kiểm events, Ready và restartCount tương ứng.","sampleAnswer":"Startup budget bao 90 giây cộng biến thiên hợp lệ; liveness tập trung tiến triển nội tại khi chạy. API gợi ý có fallback chấp nhận thì không tự làm Not Ready; giám sát degraded. Thử boot hợp lệ dài, boot kẹt quá budget, runtime deadlock và dependency timeout; kiểm events, Ready và restartCount tương ứng.","misconception":"Mọi health failure đều restart pod.; Cứ dependency fail là liveness fail.; Gọi endpoint 503 đã chứng minh kubelet restart."},"exercise":{"submissionInstructions":"Service AI cần 90 giây tải model khi boot, sau đó API gợi ý bên ngoài đôi lúc timeout nhưng app có fallback. Thiết kế probes và nêu phép kiểm để không nhầm boot chậm với deadlock.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production."}}],"id":"9-transfer"},{"title":"Phỏng vấn lại và tự giải thích","phase":"reflect","sortIndex":10,"body":"Probe tốt không hỏi chung chung hệ thống có hoàn hảo không. Nó trả đúng thông tin cho một hành động cụ thể và giúp hệ thống hồi phục mà không tự khuếch đại sự cố.\n\nAI trả kết quả theo từng tiêu chí và trích đoạn bài nộp làm bằng chứng. Khi chấm chưa xong, trạng thái là đang chấm; bạn có thể tiếp tục đọc và quay lại. Điểm phỏng vấn không tăng chỉ vì câu trả lời dài.","activities":[{"id":"health-probe-semantics--r1--final-interview","kind":"explain","prompt":"Thiết kế probes cho app checkout dùng database bắt buộc và Redis cache tùy chọn. Khi Redis down, khi database down và khi app deadlock, bộ điều khiển nên làm gì?","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism","health-probe-semantics--r1--application","health-probe-semantics--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"health-probe-semantics--r1--final-interview--criterion-0","criterion":"Hành động điều khiển","expectedEvidence":"Nối readiness với nhận traffic, liveness với restart container và startup với giai đoạn boot.","misconception":"Mọi health failure đều restart pod.","maxScore":2},{"id":"health-probe-semantics--r1--final-interview--criterion-1","criterion":"Phụ thuộc và phục hồi","expectedEvidence":"Chọn check theo khả năng phục vụ và liệu restart app có sửa nguyên nhân không.","misconception":"Cứ dependency fail là liveness fail.","maxScore":2},{"id":"health-probe-semantics--r1--final-interview--criterion-2","criterion":"Bằng chứng vận hành","expectedEvidence":"Nêu Ready, restartCount, sự kiện probe và khả năng phục hồi; không chỉ HTTP status.","misconception":"Gọi endpoint 503 đã chứng minh kubelet restart.","maxScore":2}],"answer":{"explanation":"Redis tùy chọn mất thì app có thể degraded và vẫn Ready nếu fallback đủ khả năng phục vụ. Database bắt buộc mất làm readiness fail nhưng liveness của app không nên fail chỉ vì dependency đó. Deadlock khiến tiến trình không xử lý được thì liveness failure tới ngưỡng có thể restart container. Startup kiểm boot để tránh kill app đang khởi động hợp lệ. Cần quan sát Ready, restartCount, probe events và request thật để xác nhận.","sampleAnswer":"Redis tùy chọn mất thì app có thể degraded và vẫn Ready nếu fallback đủ khả năng phục vụ. Database bắt buộc mất làm readiness fail nhưng liveness của app không nên fail chỉ vì dependency đó. Deadlock khiến tiến trình không xử lý được thì liveness failure tới ngưỡng có thể restart container. Startup kiểm boot để tránh kill app đang khởi động hợp lệ. Cần quan sát Ready, restartCount, probe events và request thật để xác nhận.","misconception":"Mọi health failure đều restart pod.; Cứ dependency fail là liveness fail.; Gọi endpoint 503 đã chứng minh kubelet restart."}}],"id":"10-reflection"}]},"en":{"title":"Health probes — withdraw traffic or restart?","description":"Health probes provide signals for a controller to decide whether a container should receive traffic, continue starting or restart.","body":"## Summary\n\nA useful probe does not vaguely ask whether everything is perfect. It provides the right information for a specific action and helps recovery without amplifying an incident.\n\n## Learning outcomes\n\n- Choose appropriate actions for boot failures, internal failures and dependency outages.\n- Design a probe policy for an application with degraded operation.\n- Explain restart storms, timeouts and the evidence required to establish recovery.\n\n## Prerequisites\n\n- Understand Kubernetes containers, Pods and Services.\n- Distinguish the application from the database or cache it calls.\n\n## Included scope\n\n- Liveness, readiness, startup and their failure consequences.\n- Required and optional dependencies, timeouts and flapping.\n- Design a decision table and check it with controlled states.\n\n## Excluded scope\n\n- Implementing framework-specific health endpoints.\n- Cluster deployment and comprehensive production tuning.\n- Deploying a monitoring stack.\n\n## Key claims\n\n- Readiness failure does not itself restart a container.\n- Liveness failure reaching its threshold can lead to a container restart.\n- A startup probe postpones liveness and readiness until startup succeeds.\n\n## Corrections\n\n- Do not use a database ping as default liveness: restarting the application does not repair an external database outage.\n- Readiness need not ping every dependency; evaluate degraded-service capability.\n- Promise.race bounds waiting but does not automatically cancel ongoing I/O.\n- Distinguish HTTP health checks from Kubernetes actions; Docker Compose does not prove kubelet semantics.\n\n## References\n\n- [kubernetes.io/docs/concepts/workloads/pods/probes/](https://kubernetes.io/docs/concepts/workloads/pods/probes/)\n- [kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/](https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/)","learningOutcomes":[{"id":"health-probe-semantics--r1--mechanism","text":"Choose appropriate actions for boot failures, internal failures and dependency outages."},{"id":"health-probe-semantics--r1--application","text":"Design a probe policy for an application with degraded operation."},{"id":"health-probe-semantics--r1--tradeoffs","text":"Explain restart storms, timeouts and the evidence required to establish recovery."}],"prerequisites":[{"id":"health-probe-semantics--r1--input-0","text":"Understand Kubernetes containers, Pods and Services."},{"id":"health-probe-semantics--r1--input-1","text":"Distinguish the application from the database or cache it calls."}],"references":[{"id":"health-probe-semantics--r1--legacy","label":"Pre-migration data source","citation":"legacy; courses/0-fullstack-mastery/modules/16-observability-logs-tracing-errors/contents/3-health-readiness-liveness-probes/bodies/0-typescript/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 0e662b08d1b6eaa70352be1993bf8993508e428d82392aa8d5fd9e7f50d4f0fa; checked 2026-09-05; New V2 sample; V1 remains unchanged."},{"id":"health-probe-semantics--r1--official-0","label":"kubernetes.io/docs/concepts/workloads/pods/probes/","url":"https://kubernetes.io/docs/concepts/workloads/pods/probes/","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."},{"id":"health-probe-semantics--r1--official-1","label":"kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/","url":"https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."}],"retrieval":[{"id":"health-probe-semantics--r1--retrieval-1","kind":"retrieval","prompt":"One day later: /ready returns 503 but restartCount=0. Is that wrong? Give a valid case and a recovery check.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism"],"afterDays":1,"rubric":[{"id":"health-probe-semantics--r1--retrieval-1--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"This can be correct: a required dependency outage may make the app Not Ready without a restart. Restore the dependency and observe Ready returning to true; use both endpoint results and events.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"This can be correct: a required dependency outage may make the app Not Ready without a restart. Restore the dependency and observe Ready returning to true; use both endpoint results and events.","sampleAnswer":"This can be correct: a required dependency outage may make the app Not Ready without a restart. Restore the dependency and observe Ready returning to true; use both endpoint results and events.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"health-probe-semantics--r1--retrieval-2","kind":"retrieval","prompt":"One week later: cache timeouts leave the Service without ready endpoints although the app has a fallback. Do you fix thresholds or semantics first?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--application"],"afterDays":7,"rubric":[{"id":"health-probe-semantics--r1--retrieval-2--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"First check whether the cache is truly required and whether the fallback can handle load. If optional, fix readiness semantics. Thresholds reduce flapping but do not fix a wrongly classified dependency.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"First check whether the cache is truly required and whether the fallback can handle load. If optional, fix readiness semantics. Thresholds reduce flapping but do not fix a wrongly classified dependency.","sampleAnswer":"First check whether the cache is truly required and whether the fallback can handle load. If optional, fix readiness semantics. Thresholds reduce flapping but do not fix a wrongly classified dependency.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"health-probe-semantics--r1--retrieval-3","kind":"retrieval","prompt":"After 21 days: application memory rises although every health call times out after two seconds. Propose a check-related cause and a way to verify it.","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"health-probe-semantics--r1--retrieval-3--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"I/O losing Promise.race may remain stuck and accumulate. Observe in-flight requests or sockets, add client cancellation or timeout and a concurrency bound, then verify stable resource usage. HTTP response duration alone is insufficient.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"I/O losing Promise.race may remain stuck and accumulate. Observe in-flight requests or sockets, add client cancellation or timeout and a concurrency bound, then verify stable resource usage. HTTP response duration alone is insufficient.","sampleAnswer":"I/O losing Promise.race may remain stuck and accumulate. Observe in-flight requests or sockets, add client cancellation or timeout and a concurrency bound, then verify stable resource usage. HTTP response duration alone is insufficient.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}}],"sections":[{"title":"Interview context","phase":"challenge","sortIndex":0,"body":"In a DevOps interview, a chart shows Redis down for two minutes and every application container repeatedly restarting. Redis recovers, but the application needs additional time to boot and load configuration. 'Does restarting the application bring Redis back?' You answer, 'A failed health check means restart.' Begin by separating 'Can it serve?' from 'Would restarting help?'\n\nAnswer using your current understanding. This initial diagnostic does not establish mastery. You will answer again after practice, and the lesson remains open if you do not yet know the answer.","activities":[{"id":"health-probe-semantics--r1--opening-interview","kind":"explain","prompt":"Design probes for a checkout app with a required database and optional Redis cache. What should the controller do when Redis fails, the database fails or the app deadlocks?","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism","health-probe-semantics--r1--application","health-probe-semantics--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"health-probe-semantics--r1--opening-interview--criterion-0","criterion":"Controller actions","expectedEvidence":"Connect readiness to traffic eligibility, liveness to container restart and startup to initialization.","misconception":"Every health failure restarts the Pod.","maxScore":2},{"id":"health-probe-semantics--r1--opening-interview--criterion-1","criterion":"Dependencies and recovery","expectedEvidence":"Choose checks based on serving capability and whether restarting the app can repair the cause.","misconception":"Every dependency failure is a liveness failure.","maxScore":2},{"id":"health-probe-semantics--r1--opening-interview--criterion-2","criterion":"Operational evidence","expectedEvidence":"Identify Ready, restartCount, probe events and recovery behavior, not merely HTTP status.","misconception":"Receiving HTTP 503 proves kubelet restarted the container.","maxScore":2}],"answer":{"explanation":"If optional Redis is down, the app can remain Ready in degraded mode if its fallback can carry the workload. A required database outage fails readiness, but should not alone fail application liveness. An internal deadlock can justify a container restart after the liveness threshold. Startup probes protect legitimate initialization from premature termination. Verify Ready, restartCount, probe events and actual requests.","sampleAnswer":"If optional Redis is down, the app can remain Ready in degraded mode if its fallback can carry the workload. A required database outage fails readiness, but should not alone fail application liveness. An internal deadlock can justify a container restart after the liveness threshold. Startup probes protect legitimate initialization from premature termination. Verify Ready, restartCount, probe events and actual requests.","misconception":"Every health failure restarts the Pod.; Every dependency failure is a liveness failure.; Receiving HTTP 503 proves kubelet restarted the container."}}],"id":"0-interview"},{"title":"Predict before observing","phase":"predict","sortIndex":1,"body":"The app can still serve requests through the database when Redis fails; Redis only accelerates access. Liveness currently pings Redis and has reached its failure threshold.","activities":[{"id":"health-probe-semantics--r1--predict-restart","kind":"choice","prompt":"What consequence can this configuration produce?","stableKey":"predict-restart","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"A health check is a control signal, so design it from the signal's consequences.","misconception":"Redis restarts automatically because the probe is in the app; Readiness automatically becomes liveness"},"options":[{"id":"health-probe-semantics--r1--predict-restart--option-1","label":"A healthy app container restarts while the Redis fault remains","explanation":"Correct: the action does not affect the component causing the fault.","isCorrect":true},{"id":"health-probe-semantics--r1--predict-restart--option-2","label":"Redis restarts automatically because the probe is in the app","explanation":"Incorrect: kubelet checks and acts on the configured container, not remote Redis.","isCorrect":false},{"id":"health-probe-semantics--r1--predict-restart--option-3","label":"Readiness automatically becomes liveness","explanation":"Incorrect: the probes have distinct meanings.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Experiment and observe","phase":"explore","sortIndex":2,"body":"Operate a model with three events: Redis outage, database outage and application deadlock. Observe Ready and restartCount. A good design does not maximize restarts; it chooses an action suited to the failure.\n\n**A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.**\n\n```mermaid\nflowchart TD\n S{Boot complete?} -->|no| W[Startup probe budget]\n S -->|yes| L{Internal liveness}\n L -->|failure threshold| R[Restart container]\n L -->|healthy| D{Can serve required traffic?}\n D -->|yes or acceptable degraded| Y[Ready]\n D -->|no| N[Not ready: remove from normal Service traffic]\n```\n\n> A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.","activities":[{"id":"health-probe-semantics--r1--exploration","kind":"simulation","prompt":"Try an incorrect path first, read the observed state, then find a solution. Finish by explaining the cause.","stableKey":"exploration","outcomeIds":["health-probe-semantics--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"health-probe-semantics--r1--exploration--state-healthy","debriefQuestion":"At which step does restarting help, and at which step does it only amplify the incident?","states":[{"id":"health-probe-semantics--r1--exploration--state-healthy","label":"Healthy system","observation":"Ready=true; restartCount=0.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-degraded","label":"Optional Redis is down","observation":"Ready=true; database fallback is used; restartCount=0.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-not-ready","label":"Required database is down","observation":"Ready=false; no restart for the dependency outage.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-recovered","label":"Database recovered","observation":"Ready=true after the success condition is met; restartCount=0.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-deadlock","label":"App deadlock","observation":"Liveness fails repeatedly; the container makes no progress.","isSuccess":false},{"id":"health-probe-semantics--r1--exploration--state-restarted","label":"Restart the container","observation":"restartCount=1; startup checks initialization; Ready becomes true only when serving is possible.","isSuccess":true}],"actions":[{"id":"health-probe-semantics--r1--exploration--action-redis-down","label":"Disconnect Redis"},{"id":"health-probe-semantics--r1--exploration--action-db-down","label":"Disconnect the database"},{"id":"health-probe-semantics--r1--exploration--action-db-up","label":"Restore the database"},{"id":"health-probe-semantics--r1--exploration--action-deadlock","label":"Introduce an internal fault"},{"id":"health-probe-semantics--r1--exploration--action-restart","label":"Reach the liveness failure threshold"}],"transitions":[{"id":"health-probe-semantics--r1--exploration--transition-0","fromStateId":"health-probe-semantics--r1--exploration--state-healthy","actionId":"health-probe-semantics--r1--exploration--action-redis-down","toStateId":"health-probe-semantics--r1--exploration--state-degraded"},{"id":"health-probe-semantics--r1--exploration--transition-1","fromStateId":"health-probe-semantics--r1--exploration--state-degraded","actionId":"health-probe-semantics--r1--exploration--action-db-down","toStateId":"health-probe-semantics--r1--exploration--state-not-ready"},{"id":"health-probe-semantics--r1--exploration--transition-2","fromStateId":"health-probe-semantics--r1--exploration--state-not-ready","actionId":"health-probe-semantics--r1--exploration--action-db-up","toStateId":"health-probe-semantics--r1--exploration--state-recovered"},{"id":"health-probe-semantics--r1--exploration--transition-3","fromStateId":"health-probe-semantics--r1--exploration--state-recovered","actionId":"health-probe-semantics--r1--exploration--action-deadlock","toStateId":"health-probe-semantics--r1--exploration--state-deadlock"},{"id":"health-probe-semantics--r1--exploration--transition-4","fromStateId":"health-probe-semantics--r1--exploration--state-deadlock","actionId":"health-probe-semantics--r1--exploration--action-restart","toStateId":"health-probe-semantics--r1--exploration--state-restarted"}]}}],"id":"2-experiment"},{"title":"HTTP 200 means little without knowing who consumes it","phase":"explain","sortIndex":3,"body":"Suppose /health returns 503. That number alone does not specify an action. Used for readiness, it means the Pod is not considered ready for ordinary Service traffic. Used for liveness with enough consecutive failures, it can cause kubelet to restart the container. The same endpoint produces different consequences when attached to different decisions.\n\nStart with the desired action. If an external database outage prevents serving, withdrawing traffic may be appropriate; restarting every app will not repair the database. If an internal fault permanently stalls the event loop, a restart may help. 'Something somewhere is wrong' is too vague a signal for every action.","id":"3-theory-1"},{"title":"Three separate questions","phase":"explain","sortIndex":4,"body":"**When a startup probe is configured, liveness and readiness wait for startup success.**\n\n| Probe | Question | Consequence of failure |\n| --- | --- | --- |\n| Startup | Has the container finished starting? | Continue checking within the startup budget; reaching the failure threshold can restart it |\n| Liveness | Can the container still make progress? | Restart the container after the failure threshold is reached |\n| Readiness | Can it currently accept traffic under the service contract? | Not Ready; no automatic restart |\n\nA startup budget must cover legitimate initialization such as model loading or local-data warming. After startup succeeds, liveness can use runtime-failure thresholds. Do not hide every slow boot behind an enormous initial delay that also delays useful failure detection.\n\nOne failed check does not necessarily cause an immediate action. Period, timeout, failureThreshold and, where applicable, successThreshold affect state changes. Period multiplied by threshold is an estimate, not a millisecond-exact guarantee. Inspect events and experiment with the actual configuration.","id":"4-theory-2"},{"title":"Required dependencies are a product decision","phase":"explain","sortIndex":5,"body":"Redis can be an optional cache in one app and a mandatory session store in another. Technology names cannot decide readiness. An optional-cache fallback must support the workload during an outage; claiming degraded service is unjustified if fallback traffic collapses the database. State workload assumptions and possible feature reductions.\n\nDeep readiness checks that ping every dependency can make all replicas Not Ready when a minor service fluctuates. Larger thresholds may reduce short noise, but do not fix dependency classification. Separate dependencies required by the serving contract from auxiliary services, while exposing degradation through metrics and alerts.\n\nA broken local connection pool differs from a remote database outage. If a pool fault should trigger restart, the check must distinguish a repairable local condition from an external outage. A failed database ping alone cannot do that.","id":"5-theory-3"},{"title":"Timeouts must also bound checking costs","phase":"explain","sortIndex":6,"body":"A dependency check must not hold a health request forever. Coordinate application deadlines with probe timeouts. Returning from Promise.race does not cancel its losing I/O Promise: creating a new stuck ping every second can still exhaust resources. Use client timeout or cancellation where supported, bound concurrent checks and clean up timers.\n\nProbes themselves generate load. Heavy queries from every replica can harm the dependency being observed. Choose cheap signals closely related to serving ability. For readiness flapping, record state sequences and causes and evaluate suitable hysteresis; do not increase timeout until it hides deadlocks.","id":"6-theory-4"},{"title":"Observe the recovery cycle","phase":"explain","sortIndex":7,"body":"A complete exercise goes beyond seeing /ready return 503. After disconnecting a dependency, inspect Pod Ready, unintended restartCount changes, traffic destinations and time to recover after restoration. A successful Compose endpoint check verifies endpoint code; Kubernetes behavior requires actual probe configuration and kubelet evidence.\n\nThis lesson uses a deterministic simulation to teach action selection. Simulation evidence is separate and must not be labelled cluster verification. Real deployment must also address shutdown and draining: Not Ready does not guarantee every open connection has ended or every client has instantly refreshed its endpoint cache.","activities":[{"id":"health-probe-semantics--r1--quiz-dependency","kind":"choice","prompt":"The external database is down but application processes are healthy. Which action is usually appropriate if the database is required?","stableKey":"quiz-dependency","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--application"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Liveness and readiness answer different questions.","misconception":"Restart every app every second; Always Ready because the process is alive"},"options":[{"id":"health-probe-semantics--r1--quiz-dependency--option-1","label":"Fail readiness, but not liveness merely because the database is down","explanation":"Correct: withdraw traffic according to the contract without restarting something that cannot repair the cause.","isCorrect":true},{"id":"health-probe-semantics--r1--quiz-dependency--option-2","label":"Restart every app every second","explanation":"Incorrect: this can create a restart storm and additional reconnection load.","isCorrect":false},{"id":"health-probe-semantics--r1--quiz-dependency--option-3","label":"Always Ready because the process is alive","explanation":"Incorrect: being alive does not imply being able to serve.","isCorrect":false}]},{"id":"health-probe-semantics--r1--quiz-timeout","kind":"choice","prompt":"Does a Promise.race timeout automatically cancel a hanging socket request?","stableKey":"quiz-timeout","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--tradeoffs"],"placementSortIndex":1,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"A check must both finish within a bound and control resource use.","misconception":"Yes; Just increase failureThreshold"},"options":[{"id":"health-probe-semantics--r1--quiz-timeout--option-1","label":"Yes","explanation":"Incorrect: the losing Promise is not automatically cancelled.","isCorrect":false},{"id":"health-probe-semantics--r1--quiz-timeout--option-2","label":"No; stopping that work requires I/O-client cancellation or timeout","explanation":"Correct: distinguish bounding waiting from bounding work.","isCorrect":true},{"id":"health-probe-semantics--r1--quiz-timeout--option-3","label":"Just increase failureThreshold","explanation":"Incorrect: thresholds do not cancel I/O.","isCorrect":false}]}],"id":"7-theory-5"},{"title":"Practice with evidence","phase":"apply","sortIndex":8,"body":"Practice agnostically with a decision table and simulation, without writing another backend. Apply each exploration event and predict Ready and restartCount before reading the observation.\n\n**Add reasoning and observable signals; question marks are for your answers.**\n\n```text\nCase                Ready   Restart?\nRedis optional down  ?       ?\nDatabase down        ?       ?\nApp deadlock         ?       ?\nValid slow boot      ?       ?\n```\n\nA future Kubernetes extension requires probe manifests, real logs and events. This sample creates no cluster and does not disrupt real dependencies.","activities":[{"id":"health-probe-semantics--r1--practice-policy","kind":"exercise","prompt":"Submit a table for the four workspace cases with an additional column: 'What would change this answer?' For example, what if Redis becomes a required session store? Explain how to verify recovery after a dependency returns.","stableKey":"practice-policy","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism","health-probe-semantics--r1--application","health-probe-semantics--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"health-probe-semantics--r1--practice-policy--criterion-0","criterion":"Requested result","expectedEvidence":"Distinguish Ready and restart behavior for optional cache, required database, deadlock and boot cases.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"health-probe-semantics--r1--practice-policy--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Explain how making Redis required or losing sufficient fallback capacity changes readiness.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"health-probe-semantics--r1--practice-policy--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Explain how to observe readiness recovery without unintended restart-count increases.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"Optional Redis may be down while Ready remains true if the fallback is sufficient. Required database failure means Not Ready without restarting merely for that outage. Deadlock can trigger a liveness restart, while valid boot within the startup budget must not be killed by liveness. Making Redis mandatory changes readiness. Verify that Ready recovers and restartCount changes only as intended.","sampleAnswer":"Optional Redis may be down while Ready remains true if the fallback is sufficient. Required database failure means Not Ready without restarting merely for that outage. Deadlock can trigger a liveness restart, while valid boot within the startup budget must not be killed by liveness. Making Redis mandatory changes readiness. Verify that Ready recovers and restartCount changes only as intended.","misconception":"Every health failure restarts the Pod.; Every dependency failure is a liveness failure.; Receiving HTTP 503 proves kubelet restarted the container."},"exercise":{"submissionInstructions":"Submit a table for the four workspace cases with an additional column: 'What would change this answer?' For example, what if Redis becomes a required session store? Explain how to verify recovery after a dependency returns.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works."}}],"id":"8-practice"},{"title":"A new situation","phase":"apply","sortIndex":9,"body":"Close the solution before starting. If you use hints, the system should still record your attempt and label it as assisted.","activities":[{"id":"health-probe-semantics--r1--transfer-model-load","kind":"exercise","prompt":"An AI service loads its model for 90 seconds during boot. Its external recommendation API sometimes times out, but the app has a fallback. Design probes and checks that distinguish valid slow startup from deadlock.","stableKey":"transfer-model-load","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism","health-probe-semantics--r1--application","health-probe-semantics--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"health-probe-semantics--r1--transfer-model-load--criterion-0","criterion":"Requested result","expectedEvidence":"Allow legitimate 90-second boot plus variation without premature liveness termination.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"health-probe-semantics--r1--transfer-model-load--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"An optional dependency with a fallback does not automatically imply Not Ready; monitor degradation.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"health-probe-semantics--r1--transfer-model-load--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Check stuck boot, runtime deadlock and dependency timeout through events, Ready and restartCount.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"The startup budget covers the legitimate 90-second boot plus expected variation; runtime liveness focuses on internal progress. A recommendation API with an acceptable fallback does not automatically make the app Not Ready; monitor degraded behavior. Test valid long boot, boot stuck beyond budget, runtime deadlock and dependency timeouts, checking events, Ready and restartCount.","sampleAnswer":"The startup budget covers the legitimate 90-second boot plus expected variation; runtime liveness focuses on internal progress. A recommendation API with an acceptable fallback does not automatically make the app Not Ready; monitor degraded behavior. Test valid long boot, boot stuck beyond budget, runtime deadlock and dependency timeouts, checking events, Ready and restartCount.","misconception":"Every health failure restarts the Pod.; Every dependency failure is a liveness failure.; Receiving HTTP 503 proves kubelet restarted the container."},"exercise":{"submissionInstructions":"An AI service loads its model for 90 seconds during boot. Its external recommendation API sometimes times out, but the app has a fallback. Design probes and checks that distinguish valid slow startup from deadlock.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works."}}],"id":"9-transfer"},{"title":"Interview again and explain your reasoning","phase":"reflect","sortIndex":10,"body":"A useful probe does not vaguely ask whether everything is perfect. It provides the right information for a specific action and helps recovery without amplifying an incident.\n\nAI should return criterion-level results and quote evidence from your submission. While grading is pending, the state remains pending; you can continue reading and return later. Interview scores do not increase merely because an answer is longer.","activities":[{"id":"health-probe-semantics--r1--final-interview","kind":"explain","prompt":"Design probes for a checkout app with a required database and optional Redis cache. What should the controller do when Redis fails, the database fails or the app deadlocks?","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["health-probe-semantics--r1--mechanism","health-probe-semantics--r1--application","health-probe-semantics--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"health-probe-semantics--r1--final-interview--criterion-0","criterion":"Controller actions","expectedEvidence":"Connect readiness to traffic eligibility, liveness to container restart and startup to initialization.","misconception":"Every health failure restarts the Pod.","maxScore":2},{"id":"health-probe-semantics--r1--final-interview--criterion-1","criterion":"Dependencies and recovery","expectedEvidence":"Choose checks based on serving capability and whether restarting the app can repair the cause.","misconception":"Every dependency failure is a liveness failure.","maxScore":2},{"id":"health-probe-semantics--r1--final-interview--criterion-2","criterion":"Operational evidence","expectedEvidence":"Identify Ready, restartCount, probe events and recovery behavior, not merely HTTP status.","misconception":"Receiving HTTP 503 proves kubelet restarted the container.","maxScore":2}],"answer":{"explanation":"If optional Redis is down, the app can remain Ready in degraded mode if its fallback can carry the workload. A required database outage fails readiness, but should not alone fail application liveness. An internal deadlock can justify a container restart after the liveness threshold. Startup probes protect legitimate initialization from premature termination. Verify Ready, restartCount, probe events and actual requests.","sampleAnswer":"If optional Redis is down, the app can remain Ready in degraded mode if its fallback can carry the workload. A required database outage fails readiness, but should not alone fail application liveness. An internal deadlock can justify a container restart after the liveness threshold. Startup probes protect legitimate initialization from premature termination. Verify Ready, restartCount, probe events and actual requests.","misconception":"Every health failure restarts the Pod.; Every dependency failure is a liveness failure.; Receiving HTTP 503 proves kubelet restarted the container."}}],"id":"10-reflection"}]}},"workspace":null,"files":[]}$lesson$::jsonb,
    '2026-11-08T00:00:00Z'
) ON CONFLICT DO NOTHING;
