    'vpc-routing', '231d8cc57', '3b75af90d0cfb6c6d650453b17b59c7f57c8ab0440b9bb61c95518c608918d9c', 'published', 'cloud', 'cloud', 'cloud-networking', 'courses/2-devops-mastery/modules/2-aws-foundations/contents/1-vpc-subnet-routing-and-igw', 'foundation', 75, 'agnostic', 5,
    $lesson${"vi":"VPC routing — lần theo đường đi của một gói tin","en":"VPC routing — follow a packet's journey"}$lesson$::jsonb,
    $lesson${"vi":"Routing trong VPC chọn next hop theo địa chỉ đích và route table gắn với subnet; khả năng kết nối còn phụ thuộc địa chỉ, chính sách mạng và đường trả lời.","en":"VPC routing chooses a next hop from the destination and the subnet's associated route table. Connectivity also depends on addressing, network policy and the return path."}$lesson$::jsonb,
    $lesson${"en.md":"5d0416ca868a1c723d717483abd02d27c9093f7b63a7de0d0511e2b82758e66e","sections/0-interview/en.md":"b44f67455d785850189a7eca10064b5ed61c3f60de4d2bfc4f56c01a7612c75b","sections/0-interview/vi.md":"c57ba10b2ca46559f484632c15ad86660dde21bafdf2df763ee9183849af0a03","sections/1-prediction/en.md":"2cd54fd73730c890aa5475a29095965c8f9f20eeb940739f7476ae7e037f0d69","sections/1-prediction/vi.md":"7404231aadcaf5599d14b4fcd7960db5341fd854db2b8097d38db0fff498c07a","sections/10-reflection/en.md":"a5ee289d7cf1c95bccf09d3784b2aa23e0b91205ce060f2fd4aa2314ab32b24b","sections/10-reflection/vi.md":"1ab253127ce27b5818335abd0ade33810a8bcf70d360767700277b3061976f1f","sections/2-experiment/en.md":"749d8ac88c85b186c5e10d8572fa92c281673d7d9f98429b5b5f4e053b3588b3","sections/2-experiment/vi.md":"8611aa6c4209c18bb75cac908405df3528842a9dc154d9c3bf06083dc226bf98","sections/3-theory-1/en.md":"03357bb6cfecba39d7a038ffe2a86e4c16ebdb3aa4aab3182ab13ba76447ea04","sections/3-theory-1/vi.md":"647bd5462eb950fd04d0cdaea98524108e766b9ad24ccf56531c14c38886c901","sections/4-theory-2/en.md":"9ee8442ed7e756f4b905e2b120615ede84310400df4ab540fb3685ff0cda4b40","sections/4-theory-2/vi.md":"7897e641be73f3e696ba74313521c2690cf599e76b494985c4a60f4ac71b7558","sections/5-theory-3/en.md":"f518d95f4891998a5ab09bc809d4b4814c318043f9d6d417b90deca7980b4c04","sections/5-theory-3/vi.md":"863c49eb9ca82d294b675de429dfefefed63b049664cdb1644d5f89dc3707c60","sections/6-theory-4/en.md":"b69ffc7897470d997efcfa0c24b051cc422b4edba38166ef7e407beb0780c41f","sections/6-theory-4/vi.md":"00b205a4f2476ca983ee1aec76a7c4899f85203ef8114986919213cd26f52e9b","sections/7-theory-5/en.md":"e9b51347aebd5b5075d1f6f1ecb6d696bc76895054dc621bc220cf5d7cc98354","sections/7-theory-5/vi.md":"285aa2b3fad4e79b371aad4af202e27c12490febdfd82f44b641b4b70c28039e","sections/8-practice/en.md":"51b97869ad84a19f491d13df2f41ddc490dccd53c4cf0b1de774d764f9fdc81c","sections/8-practice/vi.md":"d3864ceb05742e07084fc91a2c0eb109234e63f736459b09676df4250ea30f11","sections/9-transfer/en.md":"2e688000c8ce5ac590175e39ab4e8025865be8208a778b1d9854c816a18c4003","sections/9-transfer/vi.md":"ecb07c698e91a0cfd8bbe8d9da7022abbb6e202ea421b746d74059c151933621","vi.md":"118057cd0505fe07b577eedc154295acfe2cbbd9aeaadf0744b817c0f3a1a34b"}$lesson$::jsonb,
    $lesson${"locales":{"vi":{"title":"VPC routing — lần theo đường đi của một gói tin","description":"Routing trong VPC chọn next hop theo địa chỉ đích và route table gắn với subnet; khả năng kết nối còn phụ thuộc địa chỉ, chính sách mạng và đường trả lời.","body":"## Tóm tắt\n\nHãy debug mạng như lần theo một hành trình: gói tin ở đâu, muốn tới đâu, route nào thắng, điều kiện nào cho phép đi và reply quay về bằng đường nào. Nhãn public/private chỉ hữu ích sau khi bạn hiểu hành trình đó.\n\n## Kết quả học tập\n\n- Chọn route của một gói tin từ bảng tuyến cụ thể.\n- Thiết kế đường egress cho app private và đường app tới DB.\n- Giải thích điều kiện internet connectivity và giới hạn bảo vệ của private subnet.\n\n## Kiến thức đầu vào\n\n- Biết IPv4, CIDR và TCP port ở mức đọc được địa chỉ.\n- Biết app gọi database qua mạng.\n\n## Phạm vi bao gồm\n\n- Route table association và longest prefix match.\n- Public/private/isolated, IGW và public NAT gateway trong topology IPv4 đơn giản.\n- Phân biệt routing với SG và thiết kế phép kiểm đường đi.\n\n## Phạm vi không bao gồm\n\n- Terraform syntax và tạo tài nguyên AWS.\n- IPv6, Transit Gateway và routing appliance nâng cao.\n- Bảng giá cloud và thiết kế multi-region.\n\n## Luận điểm chính\n\n- Subnet public/private được phân loại theo đường tới IGW, không theo tag tên.\n- Direct IPv4 internet cần route phù hợp cùng public IPv4/EIP và policy cho phép.\n- Public NAT gateway cho private workload mở kết nối đi ra; không mở inbound tùy ý từ internet.\n\n## Điều chỉnh nhận thức\n\n- Không coi map_public_ip_on_launch=true là điều kiện định nghĩa public subnet.\n- Không coi private subnet tự ngăn lateral movement trong VPC.\n- Không gọi terraform init là luôn offline hoặc validate chứng minh kết nối thật.\n- Không giữ bảng giá legacy hoặc nói EIP attached miễn phí.\n- Không khẳng định public NAT zonal là lựa chọn duy nhất; bài giới hạn topology học tập thay vì hướng dẫn mọi sản phẩm NAT hiện có.\n\n## Tham khảo\n\n- [docs.aws.amazon.com/vpc/latest/userguide/VPC_Internet_Gateway.html](https://docs.aws.amazon.com/vpc/latest/userguide/VPC_Internet_Gateway.html)\n- [docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html](https://docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html)","learningOutcomes":[{"id":"vpc-routing--r1--mechanism","text":"Chọn route của một gói tin từ bảng tuyến cụ thể."},{"id":"vpc-routing--r1--application","text":"Thiết kế đường egress cho app private và đường app tới DB."},{"id":"vpc-routing--r1--tradeoffs","text":"Giải thích điều kiện internet connectivity và giới hạn bảo vệ của private subnet."}],"prerequisites":[{"id":"vpc-routing--r1--input-0","text":"Biết IPv4, CIDR và TCP port ở mức đọc được địa chỉ."},{"id":"vpc-routing--r1--input-1","text":"Biết app gọi database qua mạng."}],"references":[{"id":"vpc-routing--r1--legacy","label":"Nguồn dữ liệu trước migration","citation":"legacy; courses/2-devops-mastery/modules/2-aws-foundations/contents/1-vpc-subnet-routing-and-igw/bodies/0-agnostic/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 4cec443438635e3f06e19bf58be792f1ba515247b383b00824819671349cba8b; checked 2026-09-05; Bài mẫu V2 mới; không sửa V1."},{"id":"vpc-routing--r1--official-0","label":"docs.aws.amazon.com/vpc/latest/userguide/VPC_Internet_Gateway.html","url":"https://docs.aws.amazon.com/vpc/latest/userguide/VPC_Internet_Gateway.html","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."},{"id":"vpc-routing--r1--official-1","label":"docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html","url":"https://docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html","citation":"official; checked 2026-09-05; Tham khảo kỹ thuật; nội dung mới được biên soạn lại, không sao chép bài legacy."}],"retrieval":[{"id":"vpc-routing--r1--retrieval-1","kind":"retrieval","prompt":"Một ngày: default route đổi nhưng truy cập DB trong VPC không đổi. Giải thích bằng prefix và một điều kiện có thể vẫn chặn kết nối.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism"],"afterDays":1,"rubric":[{"id":"vpc-routing--r1--retrieval-1--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Đích DB khớp local /16 cụ thể hơn /0; SG/NACL hoặc DB listener vẫn có thể chặn dù route đúng.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Đích DB khớp local /16 cụ thể hơn /0; SG/NACL hoặc DB listener vẫn có thể chặn dù route đúng.","sampleAnswer":"Đích DB khớp local /16 cụ thể hơn /0; SG/NACL hoặc DB listener vẫn có thể chặn dù route đúng.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"vpc-routing--r1--retrieval-2","kind":"retrieval","prompt":"Một tuần: app private gọi API internet được. Có suy internet mở kết nối tùy ý ngược vào app được không?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--application"],"afterDays":7,"rubric":[{"id":"vpc-routing--r1--retrieval-2--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Không. NAT hỗ trợ mapping cho kết nối đi ra và reply; inbound khởi tạo mới không tự được cho phép. Nhưng cần kiểm các đường expose khác như ALB/proxy, không kết luận tuyệt đối từ chữ private.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Không. NAT hỗ trợ mapping cho kết nối đi ra và reply; inbound khởi tạo mới không tự được cho phép. Nhưng cần kiểm các đường expose khác như ALB/proxy, không kết luận tuyệt đối từ chữ private.","sampleAnswer":"Không. NAT hỗ trợ mapping cho kết nối đi ra và reply; inbound khởi tạo mới không tự được cho phép. Nhưng cần kiểm các đường expose khác như ALB/proxy, không kết luận tuyệt đối từ chữ private.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}},{"id":"vpc-routing--r1--retrieval-3","kind":"retrieval","prompt":"21 ngày: subnet tên public có public IPv4 nhưng không internet. Lập thứ tự kiểm mà không sửa SG tùy tiện.","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"vpc-routing--r1--retrieval-3--criterion-0","criterion":"Giải thích đúng tình huống ôn lại","expectedEvidence":"Kiểm route table association và IGW route/attachment, địa chỉ, SG/NACL và đường trả, DNS rồi listener/đích. Tên subnet không là bằng chứng. Dùng quan sát từng hop/policy để xác định thiếu điều kiện nào.","misconception":"Chỉ nhắc định nghĩa mà không nối nguyên nhân với kết quả trong tình huống; chấp nhận cách diễn đạt tương đương, không yêu cầu lặp đáp án.","maxScore":2}],"answer":{"explanation":"Kiểm route table association và IGW route/attachment, địa chỉ, SG/NACL và đường trả, DNS rồi listener/đích. Tên subnet không là bằng chứng. Dùng quan sát từng hop/policy để xác định thiếu điều kiện nào.","sampleAnswer":"Kiểm route table association và IGW route/attachment, địa chỉ, SG/NACL và đường trả, DNS rồi listener/đích. Tên subnet không là bằng chứng. Dùng quan sát từng hop/policy để xác định thiếu điều kiện nào.","misconception":"Đánh giá theo rubric của câu ôn lại; không chấm bằng độ dài."}}],"sections":[{"title":"Bối cảnh phỏng vấn","phase":"challenge","sortIndex":0,"body":"Trong phỏng vấn Cloud, interviewer cho bạn một instance nằm trong subnet tên “public-app”. Nó gọi internet không được dù Security Group đã cho outbound. “Em sẽ mở thêm port nào?” Bạn định sửa firewall, nhưng bảng route của subnet chỉ có route local. Tên subnet đã khiến bạn tin có một con đường chưa từng tồn tại.\n\nTrả lời câu hỏi bằng suy nghĩ hiện tại. Đây là lần chẩn đoán đầu vào, chưa tính đạt đầu ra. Bạn sẽ trả lời lại sau khi thực hành; bài vẫn mở nếu bạn chưa biết đáp án.","activities":[{"id":"vpc-routing--r1--opening-interview","kind":"explain","prompt":"Một app không có public IPv4 cần gọi API internet, còn database chỉ nhận kết nối từ app. Hãy vẽ đường đi, chỉ ra route table và các điều kiện ngoài routing phải kiểm.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism","vpc-routing--r1--application","vpc-routing--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"vpc-routing--r1--opening-interview--criterion-0","criterion":"Đường đi","expectedEvidence":"Theo route table association và longest prefix match, nêu từng hop tới đích.","misconception":"Tên public/private quyết định đường mạng.","maxScore":2},{"id":"vpc-routing--r1--opening-interview--criterion-1","criterion":"Điều kiện đủ","expectedEvidence":"Phân biệt route, địa chỉ public, SG/NACL và đường trả lời.","misconception":"Có IGW route là mọi instance tự nhận internet.","maxScore":2},{"id":"vpc-routing--r1--opening-interview--criterion-2","criterion":"Giới hạn cô lập","expectedEvidence":"NAT hỗ trợ kết nối đi ra và traffic trả về; private subnet không chặn mọi đường qua ALB/peering.","misconception":"Private nghĩa là không ai ngoài subnet có thể truy cập.","maxScore":2}],"answer":{"explanation":"Với topology IPv4 của bài, app ở private subnet route default tới public NAT gateway. NAT đặt ở subnet có đường IGW và địa chỉ public phù hợp. Traffic từ app tới DB trong VPC dùng route nội bộ thích hợp, không cần đi NAT theo default khi route local cụ thể hơn. DB SG chỉ cho nguồn app cần thiết. Route đúng chưa đủ: kiểm địa chỉ, SG/NACL, DNS, listener và đường trả lời; private subnet không tự ngăn truy cập qua ALB hay mạng đã kết nối.","sampleAnswer":"Với topology IPv4 của bài, app ở private subnet route default tới public NAT gateway. NAT đặt ở subnet có đường IGW và địa chỉ public phù hợp. Traffic từ app tới DB trong VPC dùng route nội bộ thích hợp, không cần đi NAT theo default khi route local cụ thể hơn. DB SG chỉ cho nguồn app cần thiết. Route đúng chưa đủ: kiểm địa chỉ, SG/NACL, DNS, listener và đường trả lời; private subnet không tự ngăn truy cập qua ALB hay mạng đã kết nối.","misconception":"Tên public/private quyết định đường mạng.; Có IGW route là mọi instance tự nhận internet.; Private nghĩa là không ai ngoài subnet có thể truy cập."}}],"id":"0-interview"},{"title":"Dự đoán trước khi quan sát","phase":"predict","sortIndex":1,"body":"Route table app có 10.20.0.0/16 → local và 0.0.0.0/0 → NAT. App gửi tới database 10.20.3.10.","activities":[{"id":"vpc-routing--r1--predict-route","kind":"choice","prompt":"Gói tin chọn route nào?","stableKey":"predict-route","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Chọn route theo đích và độ cụ thể, không theo tên tầng app/database.","misconception":"Default → NAT vì mọi traffic app private phải qua NAT; Không đi được vì app và DB khác subnet"},"options":[{"id":"vpc-routing--r1--predict-route--option-1","label":"Default → NAT vì mọi traffic app private phải qua NAT","explanation":"Sai: default chỉ dùng khi không có route phù hợp cụ thể hơn.","isCorrect":false},{"id":"vpc-routing--r1--predict-route--option-2","label":"10.20.0.0/16 → local","explanation":"Đúng: /16 cụ thể hơn /0 và bao đích 10.20.3.10.","isCorrect":true},{"id":"vpc-routing--r1--predict-route--option-3","label":"Không đi được vì app và DB khác subnet","explanation":"Sai: khác subnet trong VPC không tự có nghĩa không có đường.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Thử và quan sát","phase":"explore","sortIndex":2,"body":"Mô phỏng là bài sửa đường egress IPv4. App không có public IPv4. Bạn thử đưa default route thẳng tới IGW để thấy vì sao route một mình chưa đủ, rồi thay bằng đường qua public NAT đã cấu hình đầy đủ.\n\n**Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.**\n\n```mermaid\nflowchart LR\n A[Private app 10.20.2.10] -->|DB destination: local route| D[DB 10.20.3.10]\n A -->|Internet destination: default route| N[Public NAT]\n N --> G[Internet gateway]\n G --> I[Internet API]\n I -->|reply to initiated connection| G\n G --> N\n N --> A\n```\n\n> Sơ đồ cơ chế của bài học; các mũi tên thể hiện quan hệ được mô tả trong bài.","activities":[{"id":"vpc-routing--r1--exploration","kind":"simulation","prompt":"Thử đường sai trước, đọc trạng thái quan sát được, sau đó tìm đường giải quyết. Kết thúc bằng câu giải thích nguyên nhân.","stableKey":"exploration","outcomeIds":["vpc-routing--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"vpc-routing--r1--exploration--state-local-only","debriefQuestion":"Tại sao sửa default route không thay route được chọn cho địa chỉ database trong cùng VPC?","states":[{"id":"vpc-routing--r1--exploration--state-local-only","label":"Chỉ route local","observation":"App tới mạng VPC được nếu policy cho phép; không có đường internet.","isSuccess":false},{"id":"vpc-routing--r1--exploration--state-igw-no-ip","label":"Default tới IGW nhưng app không public IPv4","observation":"Direct IPv4 internet vẫn không hoạt động. Không phải chỉ thiếu một rule SG.","isSuccess":false},{"id":"vpc-routing--r1--exploration--state-nat","label":"Default tới public NAT đã sẵn sàng","observation":"App mở kết nối internet; response quay về qua NAT mapping.","isSuccess":false},{"id":"vpc-routing--r1--exploration--state-db-route","label":"Gửi tới DB trong VPC","observation":"Route local thắng default NAT; vẫn cần DB SG cho nguồn app.","isSuccess":true}],"actions":[{"id":"vpc-routing--r1--exploration--action-igw","label":"Trỏ default thẳng IGW"},{"id":"vpc-routing--r1--exploration--action-nat","label":"Trỏ default qua public NAT cấu hình đúng"},{"id":"vpc-routing--r1--exploration--action-db","label":"Thử địa chỉ DB"}],"transitions":[{"id":"vpc-routing--r1--exploration--transition-0","fromStateId":"vpc-routing--r1--exploration--state-local-only","actionId":"vpc-routing--r1--exploration--action-igw","toStateId":"vpc-routing--r1--exploration--state-igw-no-ip"},{"id":"vpc-routing--r1--exploration--transition-1","fromStateId":"vpc-routing--r1--exploration--state-igw-no-ip","actionId":"vpc-routing--r1--exploration--action-nat","toStateId":"vpc-routing--r1--exploration--state-nat"},{"id":"vpc-routing--r1--exploration--transition-2","fromStateId":"vpc-routing--r1--exploration--state-nat","actionId":"vpc-routing--r1--exploration--action-db","toStateId":"vpc-routing--r1--exploration--state-db-route"}]}}],"id":"2-experiment"},{"title":"Một subnet là một dải địa chỉ, tên chỉ là nhãn","phase":"explain","sortIndex":3,"body":"VPC cung cấp phạm vi mạng; subnet chia phạm vi đó thành dải địa chỉ trong một Availability Zone. Khi một gói tin cần đi tới đích, route table liên quan chỉ next hop phù hợp. Trong bài, app 10.20.2.10 và DB 10.20.3.10 nằm ở hai subnet khác nhau nhưng cùng VPC 10.20.0.0/16.\n\nĐừng mở đầu bằng câu “subnet tên private nên bị chặn”. Hãy tìm association tới route table, rồi đọc các route. Nếu không có association tường minh, subnet dùng main route table theo cấu hình VPC. Tag public hay private có ích cho quản lý nhưng không tự tạo hoặc xóa một route.","id":"3-theory-1"},{"title":"Route cụ thể hơn thắng route mặc định","phase":"explain","sortIndex":4,"body":"**Bảng minh họa; không phải hạ tầng đã tạo.**\n\n| Destination | Target | Ví dụ đích |\n| --- | --- | --- |\n| 10.20.0.0/16 | local | 10.20.3.10 |\n| 10.50.0.0/16 | kết nối mạng riêng đã cấu hình | 10.50.7.8 |\n| 0.0.0.0/0 | NAT | 8.8.8.8 khi không có route cụ thể hơn |\n\nMột địa chỉ có thể khớp nhiều route. Longest prefix match chọn route có prefix cụ thể nhất trong các route phù hợp theo quy tắc routing. Địa chỉ DB 10.20.3.10 vừa khớp /16 vừa khớp /0, nên route /16 được chọn. Default nghĩa là đường cuối cùng cho những đích không có route cụ thể hơn, không phải đường ưu tiên cao nhất.\n\nKết nối vẫn cần đường về. Chỉ kiểm outbound ở một đầu có thể bỏ qua route hoặc policy ở đầu kia. Với NACL không giữ trạng thái, còn phải xem traffic trả về và cổng liên quan. SG có semantics stateful khác NACL; không áp cùng một mô hình allow list đơn giản cho cả hai.","id":"4-theory-2"},{"title":"Public subnet chưa làm mọi instance public","phase":"explain","sortIndex":5,"body":"Trong topology IPv4 thông thường, subnet có đường trực tiếp tới IGW được xem là public. Nhưng một instance muốn giao tiếp trực tiếp internet còn cần public IPv4/EIP phù hợp, SG/NACL cho phép và ứng dụng/đích có thể nhận kết nối. map_public_ip_on_launch chỉ điều khiển cấp địa chỉ cho launch theo cấu hình; nó không tạo default route.\n\nVì vậy có hai lỗi khác nhau: instance có public IPv4 nhưng route không tới IGW; hoặc route tới IGW nhưng instance không có public IPv4. Mở SG rộng hơn không sửa hai lỗi đó. Khi debug, liệt kê từng điều kiện thay vì thử thay firewall ngẫu nhiên.","id":"5-theory-3"},{"title":"Private workload đi ra bằng NAT","phase":"explain","sortIndex":6,"body":"Với public NAT trong topology của bài, app private mở kết nối ra ngoài qua NAT, NAT dùng đường internet phù hợp và duy trì mapping để đưa traffic phản hồi về app. App không cần mang một public IPv4 riêng cho đường này. “Không mở inbound tùy ý” không có nghĩa chặn luôn gói trả lời; nếu không có reply thì kết nối outbound cũng không hữu ích.\n\nPrivate subnet có thể có egress, trong khi isolated subnet trong thiết kế đơn giản không có default route ra ngoài. Cả hai vẫn có thể có đường mạng khác được cấu hình. Dịch vụ có thể được expose qua load balancer/proxy đặt ở tầng public mà backend vẫn private. Vì vậy cần nói rõ “không kết nối trực tiếp từ internet tới instance theo đường này”, không nói “internet không bao giờ tác động được tới app”.","id":"6-theory-4"},{"title":"Phân tầng không thay kiểm soát truy cập","phase":"explain","sortIndex":7,"body":"App và DB khác subnet không tự cấm app bị chiếm quyền kết nối tới DB. Các route nội bộ có thể vẫn nối chúng. DB Security Group, danh tính ứng dụng, credential, quyền truy vấn và các lớp policy thích hợp mới giới hạn việc được phép làm. Network segmentation là một phần của defense in depth, không phải phép miễn kiểm tra ở tầng ứng dụng.\n\nTrước khi triển khai, chuẩn bị CIDR không overlap với mạng cần kết nối, xác định AZ và phụ thuộc egress. Chi phí, HA và lựa chọn NAT phải kiểm theo sản phẩm/region tại thời điểm dùng; bài học cơ chế không đóng đinh một bảng giá legacy. Seed này không tạo tài nguyên AWS. Bằng chứng mô phỏng chỉ chứng minh bạn chọn đúng route trong bảng đã cho.","activities":[{"id":"vpc-routing--r1--quiz-public","kind":"choice","prompt":"Subnet có route IGW, instance không public IPv4, SG outbound mở. Direct IPv4 internet có tự hoạt động?","stableKey":"quiz-public","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--application"],"placementSortIndex":0,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Kiểm đủ điều kiện thay vì suy từ một nhãn.","misconception":"Có vì subnet public; Chỉ cần đổi tag subnet"},"options":[{"id":"vpc-routing--r1--quiz-public--option-1","label":"Có vì subnet public","explanation":"Sai: địa chỉ là một điều kiện còn thiếu.","isCorrect":false},{"id":"vpc-routing--r1--quiz-public--option-2","label":"Không; cần địa chỉ public phù hợp hoặc đường egress khác như NAT","explanation":"Đúng: route không thay thế địa chỉ.","isCorrect":true},{"id":"vpc-routing--r1--quiz-public--option-3","label":"Chỉ cần đổi tag subnet","explanation":"Sai: tag không đổi network.","isCorrect":false}]},{"id":"vpc-routing--r1--quiz-private","kind":"choice","prompt":"DB trong private subnet có miễn nguy cơ truy cập từ app bị chiếm trong cùng VPC không?","stableKey":"quiz-private","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--tradeoffs"],"placementSortIndex":1,"hints":["Đối chiếu trạng thái trước thao tác với điều kiện kích hoạt; không suy kết quả chỉ từ tên gọi."],"answer":{"explanation":"Phân biệt internet exposure với kiểm soát truy cập nội bộ.","misconception":"Có, private chặn mọi subnet khác; Có nếu DB không có public IP"},"options":[{"id":"vpc-routing--r1--quiz-private--option-1","label":"Có, private chặn mọi subnet khác","explanation":"Sai: route nội bộ và policy có thể vẫn cho đường đó.","isCorrect":false},{"id":"vpc-routing--r1--quiz-private--option-2","label":"Không; cần kiểm SG, identity và quyền DB","explanation":"Đúng: private không tự ngăn lateral movement.","isCorrect":true},{"id":"vpc-routing--r1--quiz-private--option-3","label":"Có nếu DB không có public IP","explanation":"Sai: kẻ tấn công đi từ đường nội bộ không cần public IP của DB.","isCorrect":false}]}],"id":"7-theory-5"},{"title":"Thực hành có bằng chứng","phase":"apply","sortIndex":8,"body":"Bài thực hành dùng bảng route, không yêu cầu account AWS. Với mỗi đích, nộp route được chọn, next hop, đường trả lời và điều kiện chưa biết. Không tự đánh dấu “kết nối thành công” chỉ vì chọn đúng route.\n\n**Fixture agnostic để phân tích; không phải config cloud có thể apply.**\n\n```text\nVPC: 10.20.0.0/16\nApp: 10.20.2.10, no public IPv4\nDB: 10.20.3.10\nRoutes: 10.20.0.0/16 -> local; 0.0.0.0/0 -> public NAT\nDestinations: 10.20.3.10; 8.8.8.8\n```","activities":[{"id":"vpc-routing--r1--practice-packets","kind":"exercise","prompt":"Với fixture trên, lần theo hai gói tin tới DB và internet. Sau đó thay default NAT bằng IGW nhưng không gán public IPv4 cho app. Nêu đường nào đổi, đường nào giữ nguyên và vì sao.","stableKey":"practice-packets","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism","vpc-routing--r1--application","vpc-routing--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"vpc-routing--r1--practice-packets--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"DB chọn local /16; internet chọn default /0.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"vpc-routing--r1--practice-packets--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"Đổi NAT sang IGW không cấp public IPv4 còn thiếu; DB route giữ nguyên.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"vpc-routing--r1--practice-packets--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Không suy route đúng là connect thành công; kiểm policy và đường về.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"DB tiếp tục chọn local /16. Internet chọn default; qua NAT cấu hình đúng có thể egress khi policy cho phép. Đổi default tới IGW không tự cho app thiếu public IPv4 direct internet. Cần kiểm đường trả lời, SG/NACL, listener/DNS tùy phép thử.","sampleAnswer":"DB tiếp tục chọn local /16. Internet chọn default; qua NAT cấu hình đúng có thể egress khi policy cho phép. Đổi default tới IGW không tự cho app thiếu public IPv4 direct internet. Cần kiểm đường trả lời, SG/NACL, listener/DNS tùy phép thử.","misconception":"Tên public/private quyết định đường mạng.; Có IGW route là mọi instance tự nhận internet.; Private nghĩa là không ai ngoài subnet có thể truy cập."},"exercise":{"submissionInstructions":"Với fixture trên, lần theo hai gói tin tới DB và internet. Sau đó thay default NAT bằng IGW nhưng không gán public IPv4 cho app. Nêu đường nào đổi, đường nào giữ nguyên và vì sao.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production."}}],"id":"8-practice"},{"title":"Tình huống mới","phase":"apply","sortIndex":9,"body":"Đóng lời giải trước khi làm. Nếu dùng gợi ý, hệ thống vẫn ghi nhận bài làm nhưng gắn nhãn có hỗ trợ.","activities":[{"id":"vpc-routing--r1--transfer-three-tier","kind":"exercise","prompt":"Website có ALB nhận internet, app private gọi API thanh toán và DB chỉ nhận từ app. Đề xuất ba tầng, route và policy. Giải thích vì sao DB vẫn cần SG dù không có public IPv4.","stableKey":"transfer-three-tier","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism","vpc-routing--r1--application","vpc-routing--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"vpc-routing--r1--transfer-three-tier--criterion-0","criterion":"Kết quả theo yêu cầu","expectedEvidence":"Tách đường internet→ALB→app, app→NAT→internet và app→DB nội bộ.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"vpc-routing--r1--transfer-three-tier--criterion-1","criterion":"Cơ chế và điều kiện","expectedEvidence":"DB cho nguồn app cần thiết; không cho rằng khác subnet tự chặn truy cập.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2},{"id":"vpc-routing--r1--transfer-three-tier--criterion-2","criterion":"Bằng chứng và giới hạn","expectedEvidence":"Nêu route, địa chỉ và policy phù hợp; giới hạn kết luận private không ngăn mọi đường tấn công.","misconception":"Kết luận mâu thuẫn với điều kiện trong đề, hoặc chỉ nói đúng định nghĩa mà thiếu bằng chứng cụ thể được yêu cầu.","maxScore":2}],"answer":{"explanation":"ALB ở subnet có internet connectivity phù hợp; app private nhận từ ALB qua policy và egress qua đường NAT phù hợp; DB ở tầng không cần default internet, cho cổng DB từ app identity/SG thích hợp. Route nội bộ vẫn có thể nối các tầng nên DB SG cần giới hạn nguồn. Không kết luận private loại mọi tấn công qua app hoặc ALB.","sampleAnswer":"ALB ở subnet có internet connectivity phù hợp; app private nhận từ ALB qua policy và egress qua đường NAT phù hợp; DB ở tầng không cần default internet, cho cổng DB từ app identity/SG thích hợp. Route nội bộ vẫn có thể nối các tầng nên DB SG cần giới hạn nguồn. Không kết luận private loại mọi tấn công qua app hoặc ALB.","misconception":"Tên public/private quyết định đường mạng.; Có IGW route là mọi instance tự nhận internet.; Private nghĩa là không ai ngoài subnet có thể truy cập."},"exercise":{"submissionInstructions":"Website có ALB nhận internet, app private gọi API thanh toán và DB chỉ nhận từ app. Đề xuất ba tầng, route và policy. Giải thích vì sao DB vẫn cần SG dù không có public IPv4.","verificationMode":"reasoning","verificationInstructions":"Nộp artifact và phần giải thích theo đề. AI đánh giá bằng rubric; kết quả chạy mô hình chỉ là một phần bằng chứng, không thay thế giải thích và không chứng minh stack production."}}],"id":"9-transfer"},{"title":"Phỏng vấn lại và tự giải thích","phase":"reflect","sortIndex":10,"body":"Hãy debug mạng như lần theo một hành trình: gói tin ở đâu, muốn tới đâu, route nào thắng, điều kiện nào cho phép đi và reply quay về bằng đường nào. Nhãn public/private chỉ hữu ích sau khi bạn hiểu hành trình đó.\n\nAI trả kết quả theo từng tiêu chí và trích đoạn bài nộp làm bằng chứng. Khi chấm chưa xong, trạng thái là đang chấm; bạn có thể tiếp tục đọc và quay lại. Điểm phỏng vấn không tăng chỉ vì câu trả lời dài.","activities":[{"id":"vpc-routing--r1--final-interview","kind":"explain","prompt":"Một app không có public IPv4 cần gọi API internet, còn database chỉ nhận kết nối từ app. Hãy vẽ đường đi, chỉ ra route table và các điều kiện ngoài routing phải kiểm.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism","vpc-routing--r1--application","vpc-routing--r1--tradeoffs"],"placementSortIndex":0,"hints":["Vẽ hoặc kể thứ tự sự kiện. Nêu điều kiện khiến phương án của bạn không còn đúng."],"rubric":[{"id":"vpc-routing--r1--final-interview--criterion-0","criterion":"Đường đi","expectedEvidence":"Theo route table association và longest prefix match, nêu từng hop tới đích.","misconception":"Tên public/private quyết định đường mạng.","maxScore":2},{"id":"vpc-routing--r1--final-interview--criterion-1","criterion":"Điều kiện đủ","expectedEvidence":"Phân biệt route, địa chỉ public, SG/NACL và đường trả lời.","misconception":"Có IGW route là mọi instance tự nhận internet.","maxScore":2},{"id":"vpc-routing--r1--final-interview--criterion-2","criterion":"Giới hạn cô lập","expectedEvidence":"NAT hỗ trợ kết nối đi ra và traffic trả về; private subnet không chặn mọi đường qua ALB/peering.","misconception":"Private nghĩa là không ai ngoài subnet có thể truy cập.","maxScore":2}],"answer":{"explanation":"Với topology IPv4 của bài, app ở private subnet route default tới public NAT gateway. NAT đặt ở subnet có đường IGW và địa chỉ public phù hợp. Traffic từ app tới DB trong VPC dùng route nội bộ thích hợp, không cần đi NAT theo default khi route local cụ thể hơn. DB SG chỉ cho nguồn app cần thiết. Route đúng chưa đủ: kiểm địa chỉ, SG/NACL, DNS, listener và đường trả lời; private subnet không tự ngăn truy cập qua ALB hay mạng đã kết nối.","sampleAnswer":"Với topology IPv4 của bài, app ở private subnet route default tới public NAT gateway. NAT đặt ở subnet có đường IGW và địa chỉ public phù hợp. Traffic từ app tới DB trong VPC dùng route nội bộ thích hợp, không cần đi NAT theo default khi route local cụ thể hơn. DB SG chỉ cho nguồn app cần thiết. Route đúng chưa đủ: kiểm địa chỉ, SG/NACL, DNS, listener và đường trả lời; private subnet không tự ngăn truy cập qua ALB hay mạng đã kết nối.","misconception":"Tên public/private quyết định đường mạng.; Có IGW route là mọi instance tự nhận internet.; Private nghĩa là không ai ngoài subnet có thể truy cập."}}],"id":"10-reflection"}]},"en":{"title":"VPC routing — follow a packet's journey","description":"VPC routing chooses a next hop from the destination and the subnet's associated route table. Connectivity also depends on addressing, network policy and the return path.","body":"## Summary\n\nDebug networks by following a journey: where is the packet, where is it going, which route wins, what permits passage and how does the reply return? Public/private labels become useful after that journey is understood.\n\n## Learning outcomes\n\n- Select a packet's route from a concrete routing table.\n- Design private-application egress and application-to-database paths.\n- Explain internet-connectivity conditions and the protection limits of private subnets.\n\n## Prerequisites\n\n- Read IPv4 addresses, CIDR blocks and TCP ports.\n- Understand applications connecting to databases over a network.\n\n## Included scope\n\n- Route-table association and longest-prefix matching.\n- Public, private and isolated subnets, IGWs and public NAT gateways in a simple IPv4 topology.\n- Distinguish routing from security groups and design path checks.\n\n## Excluded scope\n\n- Terraform syntax and AWS resource creation.\n- IPv6, Transit Gateway and advanced routing appliances.\n- Cloud pricing tables and multi-region design.\n\n## Key claims\n\n- Public and private subnet classification follows the IGW path, not name tags.\n- Direct IPv4 internet access needs a suitable route, public IPv4 or EIP, and permitting policies.\n- A public NAT gateway supports private workloads initiating outbound connections; it does not open arbitrary inbound internet connections.\n\n## Corrections\n\n- map_public_ip_on_launch=true does not define a public subnet.\n- A private subnet does not automatically prevent lateral movement inside a VPC.\n- Do not claim terraform init is always offline or that validate proves real connectivity.\n- Do not preserve legacy pricing or claim attached EIPs are free.\n- Do not claim zonal public NAT is the only choice; this lesson limits its learning topology rather than documenting every available NAT product.\n\n## References\n\n- [docs.aws.amazon.com/vpc/latest/userguide/VPC_Internet_Gateway.html](https://docs.aws.amazon.com/vpc/latest/userguide/VPC_Internet_Gateway.html)\n- [docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html](https://docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html)","learningOutcomes":[{"id":"vpc-routing--r1--mechanism","text":"Select a packet's route from a concrete routing table."},{"id":"vpc-routing--r1--application","text":"Design private-application egress and application-to-database paths."},{"id":"vpc-routing--r1--tradeoffs","text":"Explain internet-connectivity conditions and the protection limits of private subnets."}],"prerequisites":[{"id":"vpc-routing--r1--input-0","text":"Read IPv4 addresses, CIDR blocks and TCP ports."},{"id":"vpc-routing--r1--input-1","text":"Understand applications connecting to databases over a network."}],"references":[{"id":"vpc-routing--r1--legacy","label":"Pre-migration data source","citation":"legacy; courses/2-devops-mastery/modules/2-aws-foundations/contents/1-vpc-subnet-routing-and-igw/bodies/0-agnostic/vi.md; git cbe25d78dc56535ab86be7ea21097a56e911a1f7; sha256 4cec443438635e3f06e19bf58be792f1ba515247b383b00824819671349cba8b; checked 2026-09-05; New V2 sample; V1 remains unchanged."},{"id":"vpc-routing--r1--official-0","label":"docs.aws.amazon.com/vpc/latest/userguide/VPC_Internet_Gateway.html","url":"https://docs.aws.amazon.com/vpc/latest/userguide/VPC_Internet_Gateway.html","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."},{"id":"vpc-routing--r1--official-1","label":"docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html","url":"https://docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html","citation":"official; checked 2026-09-05; Technical reference; the new content is authored independently rather than copied from the legacy lesson."}],"retrieval":[{"id":"vpc-routing--r1--retrieval-1","kind":"retrieval","prompt":"One day later: the default route changes, but access to the VPC database does not. Explain using prefixes and name a condition that could still block connectivity.","stableKey":"retrieval-1","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism"],"afterDays":1,"rubric":[{"id":"vpc-routing--r1--retrieval-1--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"The database matches local /16, which is more specific than /0. SGs, NACLs or the database listener can still block connectivity despite a correct route.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"The database matches local /16, which is more specific than /0. SGs, NACLs or the database listener can still block connectivity despite a correct route.","sampleAnswer":"The database matches local /16, which is more specific than /0. SGs, NACLs or the database listener can still block connectivity despite a correct route.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"vpc-routing--r1--retrieval-2","kind":"retrieval","prompt":"One week later: a private app can call an internet API. Does that imply arbitrary inbound internet connections can reach it?","stableKey":"retrieval-2","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--application"],"afterDays":7,"rubric":[{"id":"vpc-routing--r1--retrieval-2--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"No. NAT maintains mappings for outbound connections and their replies; it does not automatically permit new inbound connections. Inspect other exposure paths such as ALBs or proxies instead of drawing an absolute conclusion from 'private.'","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"No. NAT maintains mappings for outbound connections and their replies; it does not automatically permit new inbound connections. Inspect other exposure paths such as ALBs or proxies instead of drawing an absolute conclusion from 'private.'","sampleAnswer":"No. NAT maintains mappings for outbound connections and their replies; it does not automatically permit new inbound connections. Inspect other exposure paths such as ALBs or proxies instead of drawing an absolute conclusion from 'private.'","misconception":"Evaluate against this retrieval question's rubric, not answer length."}},{"id":"vpc-routing--r1--retrieval-3","kind":"retrieval","prompt":"After 21 days: an instance with public IPv4 in a subnet named public has no internet access. Order your checks without arbitrarily changing SG rules.","stableKey":"retrieval-3","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--tradeoffs"],"afterDays":21,"rubric":[{"id":"vpc-routing--r1--retrieval-3--criterion-0","criterion":"Explain the retrieval scenario correctly","expectedEvidence":"Check route-table association, IGW route and attachment, addresses, SGs, NACLs and return paths, then DNS and listeners or destinations. The subnet name is not evidence. Observe each hop and policy to identify the missing condition.","misconception":"Repeats a definition without connecting the scenario's cause and result. Accept equivalent reasoning; do not require verbatim reproduction of the sample answer.","maxScore":2}],"answer":{"explanation":"Check route-table association, IGW route and attachment, addresses, SGs, NACLs and return paths, then DNS and listeners or destinations. The subnet name is not evidence. Observe each hop and policy to identify the missing condition.","sampleAnswer":"Check route-table association, IGW route and attachment, addresses, SGs, NACLs and return paths, then DNS and listeners or destinations. The subnet name is not evidence. Observe each hop and policy to identify the missing condition.","misconception":"Evaluate against this retrieval question's rubric, not answer length."}}],"sections":[{"title":"Interview context","phase":"challenge","sortIndex":0,"body":"In a cloud interview, an instance in a subnet named 'public-app' cannot reach the internet despite outbound security-group permission. 'Which port will you open?' Before changing the firewall, you discover that the subnet has only a local route. Its name made you assume a path that never existed.\n\nAnswer using your current understanding. This initial diagnostic does not establish mastery. You will answer again after practice, and the lesson remains open if you do not yet know the answer.","activities":[{"id":"vpc-routing--r1--opening-interview","kind":"explain","prompt":"An app without public IPv4 must call an internet API, while its database accepts connections only from the app. Draw the paths, identify route tables and state the non-routing conditions to verify.","stableKey":"opening-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":true,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism","vpc-routing--r1--application","vpc-routing--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"vpc-routing--r1--opening-interview--criterion-0","criterion":"Path","expectedEvidence":"Use route-table association and longest-prefix matching to identify each hop.","misconception":"Public/private names determine paths.","maxScore":2},{"id":"vpc-routing--r1--opening-interview--criterion-1","criterion":"Sufficient conditions","expectedEvidence":"Distinguish routing, public addressing, SGs, NACLs and return paths.","misconception":"An IGW route automatically gives every instance internet access.","maxScore":2},{"id":"vpc-routing--r1--opening-interview--criterion-2","criterion":"Isolation limits","expectedEvidence":"NAT supports outbound connections and replies; private subnets do not block every ALB or peering path.","misconception":"Private means nobody outside the subnet can connect.","maxScore":2}],"answer":{"explanation":"In the lesson's IPv4 topology, the private app's default route targets a public NAT gateway. The NAT sits in a subnet with an IGW path and suitable public addressing. App-to-database traffic within the VPC uses the more specific internal route instead of the NAT default. The database security group permits only required app sources. Routing alone is insufficient: inspect addresses, SGs and NACLs, DNS, listeners and return paths. A private subnet does not automatically block access through an ALB or a connected network.","sampleAnswer":"In the lesson's IPv4 topology, the private app's default route targets a public NAT gateway. The NAT sits in a subnet with an IGW path and suitable public addressing. App-to-database traffic within the VPC uses the more specific internal route instead of the NAT default. The database security group permits only required app sources. Routing alone is insufficient: inspect addresses, SGs and NACLs, DNS, listeners and return paths. A private subnet does not automatically block access through an ALB or a connected network.","misconception":"Public/private names determine paths.; An IGW route automatically gives every instance internet access.; Private means nobody outside the subnet can connect."}}],"id":"0-interview"},{"title":"Predict before observing","phase":"predict","sortIndex":1,"body":"The app route table contains 10.20.0.0/16 → local and 0.0.0.0/0 → NAT. The app sends to database 10.20.3.10.","activities":[{"id":"vpc-routing--r1--predict-route","kind":"choice","prompt":"Which route does the packet select?","stableKey":"predict-route","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Select routes by destination and specificity, not by application or database tier names.","misconception":"Default to NAT because all private-app traffic must use NAT; No route because the app and database are in different subnets"},"options":[{"id":"vpc-routing--r1--predict-route--option-1","label":"Default to NAT because all private-app traffic must use NAT","explanation":"Incorrect: the default is used only when no more specific matching route exists.","isCorrect":false},{"id":"vpc-routing--r1--predict-route--option-2","label":"10.20.0.0/16 → local","explanation":"Correct: /16 is more specific than /0 and contains 10.20.3.10.","isCorrect":true},{"id":"vpc-routing--r1--predict-route--option-3","label":"No route because the app and database are in different subnets","explanation":"Incorrect: different subnets within a VPC do not automatically lack a path.","isCorrect":false}]}],"id":"1-prediction"},{"title":"Experiment and observe","phase":"explore","sortIndex":2,"body":"The simulation repairs IPv4 egress for an app without public IPv4. First point the default directly at IGW to observe why routing alone is insufficient, then use a fully configured public NAT path.\n\n**A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.**\n\n```mermaid\nflowchart LR\n A[Private app 10.20.2.10] -->|DB destination: local route| D[DB 10.20.3.10]\n A -->|Internet destination: default route| N[Public NAT]\n N --> G[Internet gateway]\n G --> I[Internet API]\n I -->|reply to initiated connection| G\n G --> N\n N --> A\n```\n\n> A diagram of the lesson's mechanism; arrows represent the relationships explained in the text.","activities":[{"id":"vpc-routing--r1--exploration","kind":"simulation","prompt":"Try an incorrect path first, read the observed state, then find a solution. Finish by explaining the cause.","stableKey":"exploration","outcomeIds":["vpc-routing--r1--mechanism"],"placementSortIndex":0,"simulation":{"engine":"state-machine","initialStateId":"vpc-routing--r1--exploration--state-local-only","debriefQuestion":"Why does changing the default route leave the chosen route for the same-VPC database unchanged?","states":[{"id":"vpc-routing--r1--exploration--state-local-only","label":"Local route only","observation":"The app can reach VPC networks if policies permit; no internet path exists.","isSuccess":false},{"id":"vpc-routing--r1--exploration--state-igw-no-ip","label":"Default to IGW, but the app has no public IPv4","observation":"Direct IPv4 internet still does not work. A missing SG rule is not the only issue.","isSuccess":false},{"id":"vpc-routing--r1--exploration--state-nat","label":"Default to ready public NAT","observation":"The app initiates an internet connection; the response returns through the NAT mapping.","isSuccess":false},{"id":"vpc-routing--r1--exploration--state-db-route","label":"Send to the VPC database","observation":"The local route beats default NAT; the database SG must still allow the app source.","isSuccess":true}],"actions":[{"id":"vpc-routing--r1--exploration--action-igw","label":"Point the default directly at IGW"},{"id":"vpc-routing--r1--exploration--action-nat","label":"Point the default at correctly configured public NAT"},{"id":"vpc-routing--r1--exploration--action-db","label":"Try the database address"}],"transitions":[{"id":"vpc-routing--r1--exploration--transition-0","fromStateId":"vpc-routing--r1--exploration--state-local-only","actionId":"vpc-routing--r1--exploration--action-igw","toStateId":"vpc-routing--r1--exploration--state-igw-no-ip"},{"id":"vpc-routing--r1--exploration--transition-1","fromStateId":"vpc-routing--r1--exploration--state-igw-no-ip","actionId":"vpc-routing--r1--exploration--action-nat","toStateId":"vpc-routing--r1--exploration--state-nat"},{"id":"vpc-routing--r1--exploration--transition-2","fromStateId":"vpc-routing--r1--exploration--state-nat","actionId":"vpc-routing--r1--exploration--action-db","toStateId":"vpc-routing--r1--exploration--state-db-route"}]}}],"id":"2-experiment"},{"title":"A subnet is an address range; its name is a label","phase":"explain","sortIndex":3,"body":"A VPC provides a network scope; subnets divide it into address ranges within Availability Zones. For a packet's destination, the associated route table identifies an appropriate next hop. Here app 10.20.2.10 and database 10.20.3.10 occupy different subnets in VPC 10.20.0.0/16.\n\nDo not start with 'It is named private, so it is blocked.' Find the route-table association and read its routes. Without an explicit association, the subnet uses the VPC's main route table. Public/private tags help management but do not create or remove routes.","id":"3-theory-1"},{"title":"More specific routes beat the default","phase":"explain","sortIndex":4,"body":"**An illustrative table, not provisioned infrastructure.**\n\n| Destination | Target | Example destination |\n| --- | --- | --- |\n| 10.20.0.0/16 | local | 10.20.3.10 |\n| 10.50.0.0/16 | A configured private-network connection | 10.50.7.8 |\n| 0.0.0.0/0 | NAT | 8.8.8.8 when no more specific route exists |\n\nAn address may match several routes. Longest-prefix matching chooses the most specific applicable prefix under routing rules. Database 10.20.3.10 matches both /16 and /0, so /16 wins. A default route is the fallback for destinations without a more specific match, not the highest-priority route.\n\nConnectivity also needs a return path. Inspecting only one endpoint's outbound rules can miss routes or policies at the other end. Stateless NACLs require attention to return traffic and relevant ports. SG stateful semantics differ from NACLs; do not apply one simplistic allow-list model to both.","id":"4-theory-2"},{"title":"A public subnet does not make every instance public","phase":"explain","sortIndex":5,"body":"In a conventional IPv4 topology, a subnet with a direct IGW route is public. Direct internet communication from an instance additionally needs suitable public IPv4 or EIP, permitting SG and NACL policies, and a reachable application or destination. map_public_ip_on_launch controls launch addressing under configuration; it does not create a default route.\n\nAn instance with public IPv4 but no IGW route and an instance with an IGW route but no public IPv4 have different failures. Broader SG rules repair neither. List the required conditions rather than changing firewalls at random.","id":"5-theory-3"},{"title":"Private workloads use NAT for egress","phase":"explain","sortIndex":6,"body":"With this topology's public NAT, a private app initiates an outbound connection through NAT. NAT uses a suitable internet path and keeps a mapping for replies. The app needs no dedicated public IPv4 for that path. 'No arbitrary inbound connections' does not mean replies are blocked; useful outbound communication needs them.\n\nA private subnet may have egress, while an isolated subnet in a simple design lacks an external default route. Either may still have other configured network paths. A public-tier load balancer or proxy can expose a service whose backend remains private. Say 'No direct internet-to-instance connection through this path,' not 'The internet can never affect this app.'","id":"6-theory-4"},{"title":"Tiers do not replace access control","phase":"explain","sortIndex":7,"body":"Placing app and database in different subnets does not automatically stop a compromised app from reaching the database; internal routes may connect them. Database SGs, application identity, credentials, query permissions and suitable policies limit permitted actions. Segmentation contributes to defense in depth rather than exempting application-layer checks.\n\nBefore deployment, choose CIDRs that do not overlap networks you need to connect, identify Availability Zones and egress dependencies. Verify cost, availability and NAT choices for the product and region when implementing; a mechanism lesson should not freeze legacy pricing. This seed creates no AWS resources. Its simulation proves only route selection in the supplied table.","activities":[{"id":"vpc-routing--r1--quiz-public","kind":"choice","prompt":"The subnet has an IGW route, the instance has no public IPv4 and outbound SG rules allow traffic. Does direct IPv4 internet connectivity automatically work?","stableKey":"quiz-public","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--application"],"placementSortIndex":0,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Check all conditions instead of inferring from a label.","misconception":"Yes, because the subnet is public; Just change the subnet tag"},"options":[{"id":"vpc-routing--r1--quiz-public--option-1","label":"Yes, because the subnet is public","explanation":"Incorrect: appropriate addressing is still missing.","isCorrect":false},{"id":"vpc-routing--r1--quiz-public--option-2","label":"No; it needs suitable public addressing or another egress path such as NAT","explanation":"Correct: a route does not replace an address.","isCorrect":true},{"id":"vpc-routing--r1--quiz-public--option-3","label":"Just change the subnet tag","explanation":"Incorrect: tags do not change networking.","isCorrect":false}]},{"id":"vpc-routing--r1--quiz-private","kind":"choice","prompt":"Is a database in a private subnet immune to access from a compromised app in the same VPC?","stableKey":"quiz-private","responseKind":"single-choice","evaluationMethod":"deterministic","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--tradeoffs"],"placementSortIndex":1,"hints":["Compare the state before the action with its trigger conditions; do not infer behavior from names alone."],"answer":{"explanation":"Distinguish internet exposure from internal access control.","misconception":"Yes, private blocks every other subnet; Yes, if the database has no public IP"},"options":[{"id":"vpc-routing--r1--quiz-private--option-1","label":"Yes, private blocks every other subnet","explanation":"Incorrect: internal routes and policies may still permit that path.","isCorrect":false},{"id":"vpc-routing--r1--quiz-private--option-2","label":"No; check security groups, identity and database permissions","explanation":"Correct: private placement does not automatically stop lateral movement.","isCorrect":true},{"id":"vpc-routing--r1--quiz-private--option-3","label":"Yes, if the database has no public IP","explanation":"Incorrect: an attacker using an internal path does not need the database's public IP.","isCorrect":false}]}],"id":"7-theory-5"},{"title":"Practice with evidence","phase":"apply","sortIndex":8,"body":"Practice with routing tables without requiring an AWS account. For each destination, submit the selected route, next hop, return path and unknown conditions. Do not mark connectivity successful merely because you selected the right route.\n\n**An agnostic analysis fixture, not deployable cloud configuration.**\n\n```text\nVPC: 10.20.0.0/16\nApp: 10.20.2.10, no public IPv4\nDB: 10.20.3.10\nRoutes: 10.20.0.0/16 -> local; 0.0.0.0/0 -> public NAT\nDestinations: 10.20.3.10; 8.8.8.8\n```","activities":[{"id":"vpc-routing--r1--practice-packets","kind":"exercise","prompt":"Trace packets to the database and internet using the fixture. Then replace the default NAT route with an IGW route without assigning the app public IPv4. Explain which paths change, which remain the same and why.","stableKey":"practice-packets","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism","vpc-routing--r1--application","vpc-routing--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"vpc-routing--r1--practice-packets--criterion-0","criterion":"Requested result","expectedEvidence":"Database traffic selects local /16; internet traffic selects default /0.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"vpc-routing--r1--practice-packets--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Replacing NAT with IGW does not supply missing public IPv4; the database route remains unchanged.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"vpc-routing--r1--practice-packets--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"Do not equate correct routing with a successful connection; check policy and the return path.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"The database still selects local /16. Internet destinations select the default, and correctly configured NAT can provide egress when policies permit. Replacing the default with IGW does not give an app lacking public IPv4 direct internet access. Check return paths, SGs, NACLs and, as relevant, listeners and DNS.","sampleAnswer":"The database still selects local /16. Internet destinations select the default, and correctly configured NAT can provide egress when policies permit. Replacing the default with IGW does not give an app lacking public IPv4 direct internet access. Check return paths, SGs, NACLs and, as relevant, listeners and DNS.","misconception":"Public/private names determine paths.; An IGW route automatically gives every instance internet access.; Private means nobody outside the subnet can connect."},"exercise":{"submissionInstructions":"Trace packets to the database and internet using the fixture. Then replace the default NAT route with an IGW route without assigning the app public IPv4. Explain which paths change, which remain the same and why.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works."}}],"id":"8-practice"},{"title":"A new situation","phase":"apply","sortIndex":9,"body":"Close the solution before starting. If you use hints, the system should still record your attempt and label it as assisted.","activities":[{"id":"vpc-routing--r1--transfer-three-tier","kind":"exercise","prompt":"A website has an internet-facing ALB, a private app calling a payment API and a database accepting connections only from the app. Propose the three tiers, routes and policies. Explain why the database still needs a security group without public IPv4.","stableKey":"transfer-three-tier","responseKind":"artifact-and-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism","vpc-routing--r1--application","vpc-routing--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"vpc-routing--r1--transfer-three-tier--criterion-0","criterion":"Requested result","expectedEvidence":"Separate internet→ALB→app, app→NAT→internet and internal app→database paths.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"vpc-routing--r1--transfer-three-tier--criterion-1","criterion":"Mechanism and conditions","expectedEvidence":"Permit necessary app sources to the database; different subnets do not automatically deny access.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2},{"id":"vpc-routing--r1--transfer-three-tier--criterion-2","criterion":"Evidence and limitations","expectedEvidence":"State suitable routes, addresses and policies, and explain that private placement does not eliminate every attack path.","misconception":"The conclusion contradicts the stated conditions, or gives only a definition without the concrete evidence requested.","maxScore":2}],"answer":{"explanation":"Place the ALB in subnets with suitable internet connectivity. Permit ALB-to-private-app traffic and give the app appropriate NAT egress. Put the database in a tier that does not need default internet access and permit the database port from the required app identity or security group. Internal routes can still connect tiers, so restrict database sources. Private placement does not eliminate attacks through the app or ALB.","sampleAnswer":"Place the ALB in subnets with suitable internet connectivity. Permit ALB-to-private-app traffic and give the app appropriate NAT egress. Put the database in a tier that does not need default internet access and permit the database port from the required app identity or security group. Internal routes can still connect tiers, so restrict database sources. Private placement does not eliminate attacks through the app or ALB.","misconception":"Public/private names determine paths.; An IGW route automatically gives every instance internet access.; Private means nobody outside the subnet can connect."},"exercise":{"submissionInstructions":"A website has an internet-facing ALB, a private app calling a payment API and a database accepting connections only from the app. Propose the three tiers, routes and policies. Explain why the database still needs a security group without public IPv4.","verificationMode":"reasoning","verificationInstructions":"Submit the requested artifact and explanation. AI evaluates the rubric; model execution is only part of the evidence. It neither replaces reasoning nor proves the production stack works."}}],"id":"9-transfer"},{"title":"Interview again and explain your reasoning","phase":"reflect","sortIndex":10,"body":"Debug networks by following a journey: where is the packet, where is it going, which route wins, what permits passage and how does the reply return? Public/private labels become useful after that journey is understood.\n\nAI should return criterion-level results and quote evidence from your submission. While grading is pending, the state remains pending; you can continue reading and return later. Interview scores do not increase merely because an answer is longer.","activities":[{"id":"vpc-routing--r1--final-interview","kind":"explain","prompt":"An app without public IPv4 must call an internet API, while its database accepts connections only from the app. Draw the paths, identify route tables and state the non-routing conditions to verify.","stableKey":"final-interview","responseKind":"written-explanation","evaluationMethod":"ai-rubric","isDiagnostic":false,"feedbackRelease":"after-submit","outcomeIds":["vpc-routing--r1--mechanism","vpc-routing--r1--application","vpc-routing--r1--tradeoffs"],"placementSortIndex":0,"hints":["Draw or describe the event order. State a condition under which your solution would no longer hold."],"rubric":[{"id":"vpc-routing--r1--final-interview--criterion-0","criterion":"Path","expectedEvidence":"Use route-table association and longest-prefix matching to identify each hop.","misconception":"Public/private names determine paths.","maxScore":2},{"id":"vpc-routing--r1--final-interview--criterion-1","criterion":"Sufficient conditions","expectedEvidence":"Distinguish routing, public addressing, SGs, NACLs and return paths.","misconception":"An IGW route automatically gives every instance internet access.","maxScore":2},{"id":"vpc-routing--r1--final-interview--criterion-2","criterion":"Isolation limits","expectedEvidence":"NAT supports outbound connections and replies; private subnets do not block every ALB or peering path.","misconception":"Private means nobody outside the subnet can connect.","maxScore":2}],"answer":{"explanation":"In the lesson's IPv4 topology, the private app's default route targets a public NAT gateway. The NAT sits in a subnet with an IGW path and suitable public addressing. App-to-database traffic within the VPC uses the more specific internal route instead of the NAT default. The database security group permits only required app sources. Routing alone is insufficient: inspect addresses, SGs and NACLs, DNS, listeners and return paths. A private subnet does not automatically block access through an ALB or a connected network.","sampleAnswer":"In the lesson's IPv4 topology, the private app's default route targets a public NAT gateway. The NAT sits in a subnet with an IGW path and suitable public addressing. App-to-database traffic within the VPC uses the more specific internal route instead of the NAT default. The database security group permits only required app sources. Routing alone is insufficient: inspect addresses, SGs and NACLs, DNS, listeners and return paths. A private subnet does not automatically block access through an ALB or a connected network.","misconception":"Public/private names determine paths.; An IGW route automatically gives every instance internet access.; Private means nobody outside the subnet can connect."}}],"id":"10-reflection"}]}},"workspace":null,"files":[]}$lesson$::jsonb,
    '2026-11-08T00:00:00Z'
) ON CONFLICT DO NOTHING;
