INSERT INTO lesson_topics (topic, title, source_note, description, prerequisites, related, path, ref, imported_at)
VALUES ('communication-patterns', 'Communication patterns', 'System Design module 3', 'Các dịch vụ nói chuyện với nhau thế nào: đồng bộ, bất đồng bộ, sự kiện, saga và tách mô hình đọc khỏi mô hình ghi.', $lesson$["Một request đi qua backend thế nào (topic Backend framework).","Giao dịch và index trong database."]$lesson$::jsonb, $lesson$["backend-framework","kubernetes"]$lesson$::jsonb, $lesson$[{"order":1,"key":"courses/1-system-design-mastery/modules/3-communication-patterns/contents/0-api-gateway","titles":{"vi":"API Gateway: một điểm vào cho nhiều service","en":"API Gateway: One Entry Point for Many Services"}},{"order":2,"key":"courses/1-system-design-mastery/modules/3-communication-patterns/contents/1-synchronous-communication-rest-grpc","titles":{"vi":"Giao tiếp đồng bộ: REST vs gRPC (hybrid)","en":"Synchronous Communication: REST vs gRPC"}},{"order":3,"key":"courses/1-system-design-mastery/modules/3-communication-patterns/contents/2-asynchronous-event-driven","titles":{"vi":"Bất đồng bộ hướng sự kiện với Kafka","en":"Asynchronous Event-Driven Communication"}},{"order":4,"key":"courses/1-system-design-mastery/modules/3-communication-patterns/contents/3-publish-subscribe-pattern","titles":{"vi":"Pub/Sub với NATS: broadcast tới mọi subscriber so với queue","en":"Publish-Subscribe with NATS: broadcast to every subscriber versus a queue"}},{"order":5,"key":"courses/1-system-design-mastery/modules/3-communication-patterns/contents/4-database-per-service","titles":{"vi":"Database-per-Service: mỗi service sở hữu dữ liệu","en":"Database-per-Service: Each Service Owns Its Data"}},{"order":6,"key":"courses/1-system-design-mastery/modules/3-communication-patterns/contents/5-saga-orchestration-and-choreography","titles":{"vi":"Saga Pattern: Orchestration vs Choreography","en":"Saga Pattern: Orchestration vs Choreography"}},{"order":7,"key":"courses/1-system-design-mastery/modules/3-communication-patterns/contents/6-cqrs-and-read-models","titles":{"vi":"CQRS: tách Command/Query và read model","en":"CQRS: Splitting Command/Query and the Read Model"}},{"order":8,"key":"courses/1-system-design-mastery/modules/3-communication-patterns/contents/7-event-sourcing","titles":{"vi":"Event Sourcing: event log là nguồn sự thật","en":"Event Sourcing: The Event Log Is the Source of Truth"}}]$lesson$::jsonb, '231d8cc57', '2026-11-08T00:00:00Z')
