INSERT INTO lesson_topics (topic, title, source_note, description, prerequisites, related, path, ref, imported_at)
VALUES ('kubernetes', 'Kubernetes', 'System Design module 2 và DevOps module 18', 'Từ pod tới control plane: Kubernetes quyết định chạy, nối mạng, kiểm tra sức khoẻ và cập nhật ứng dụng thế nào.', $lesson$["Container và image.","Đọc được YAML và lệnh shell cơ bản."]$lesson$::jsonb, $lesson$["cloud-networking","communication-patterns"]$lesson$::jsonb, $lesson$[{"order":1,"key":"courses/1-system-design-mastery/modules/2-kubernetes-fundamentals/contents/0-monolith-vs-microservices","titles":{"vi":"Monolith vs Microservices: đánh đổi kiến trúc, khi nào nên tách","en":"Monolith vs Microservices: Architectural Trade-offs and When to Split"}},{"order":2,"key":"courses/1-system-design-mastery/modules/2-kubernetes-fundamentals/contents/1-introduction-to-kubernetes","titles":{"vi":"Kubernetes nền tảng: Deployment, Service, load-balance qua replica","en":"Kubernetes Foundations: Deployment, Service, Load Balancing Across Replicas"}},{"order":3,"key":"courses/1-system-design-mastery/modules/2-kubernetes-fundamentals/contents/2-kubernetes-core-concepts","titles":{"vi":"Ứng dụng multi-tier trên K8s: ConfigMap, Secret, Service DNS, state","en":"Multi-tier apps on K8s: ConfigMap, Secret, Service DNS, state"}},{"order":4,"key":"courses/1-system-design-mastery/modules/2-kubernetes-fundamentals/contents/3-complex-applications-and-helm-charts","titles":{"vi":"Helm cho production database: sharding, HA, replication","en":"Helm for production databases: sharding, HA, replication"}},{"order":5,"key":"courses/1-system-design-mastery/modules/2-kubernetes-fundamentals/contents/4-kubernetes-on-cloud","titles":{"vi":"Kubernetes trên cloud quản lý (DOKS): Ingress, TLS, cert tự động","en":"Kubernetes on managed cloud (DOKS): Ingress, TLS, automatic certificates"}},{"order":6,"key":"courses/2-devops-mastery/modules/18-kubernetes-core-and-internals/contents/0-pods-and-deployments","titles":{"vi":"Pods và Deployments — đơn vị chạy nhỏ nhất và bộ điều khiển giữ app sống","en":"Pods and Deployments —