rking"}},{"order":14,"key":"courses/2-devops-mastery/modules/18-kubernetes-core-and-internals/contents/8-csi-and-storage-lifecycle","titles":{"vi":"CSI & Storage Lifecycle","en":"CSI & Storage Lifecycle"}},{"order":15,"key":"courses/2-devops-mastery/modules/18-kubernetes-core-and-internals/contents/9-admission-controllers-and-extensions","titles":{"vi":"Admission Controllers & Extensions","en":"Admission Controllers & Extensions"}}]$lesson$::jsonb, '231d8cc57', '2026-11-08T00:00:00Z')
